INSERT INTO m251_art VALUES
(0,0,$m251$الديباجة$m251$,$m251$قانون رقم 11 لسنة 2018 بإصدار قانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m251$,'988bc67dab451d464bc80aae8776129e'),
(1,-1,$m251$مادة 1 إصدار$m251$,$m251$يعمل بأحكام القانون المرافق فى شأن إعادة الهيكلة والإفلاس والصلح الواقى منه .
وتسرى أحكامه على التاجر وفقا للتعريف الوارد فى المادة ( 10 ) من قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 ، وذلك فيما عدا شركات المحاصة وشركات القطاع العام وشركات قطاع الأعمال العام .$m251$,'1180ab2277e6f9eb32a8122c48257493'),
(2,-1,$m251$مادة 2 إصدار$m251$,$m251$يصدر وزير العدل اللوائح والقرارات اللازمة لتطبيق أحكام القانون المرافق خلال ثلاثة أشهر من تاريخ العمل به .$m251$,'ab4b93a4c05ffa3e611ae97225033a65'),
(3,-1,$m251$مادة 3 إصدار$m251$,$m251$تسرى أحكام قانون المرافعات المدنية والتجارية ، وقانون الإثبات فى المواد المدنية والتجارية وذلك فيما لم يرد بشأنه نص خاص فى القانون المرافق .$m251$,'69d5acf7f9ecfca8b32646e50cad7627'),
(4,-1,$m251$مادة 4 إصدار$m251$,$m251$تحيل المحاكم من تلقاء نفسها ما قد يوجد لديها من إجراءات التفليسة والمنازعات والتظلمات فى تلك الإجراءات ، وكافة الدعاوى الناشئة عن الإفلاس إلى المحكمة الاقتصادية المختصة ، بالحالة التى تكون عليها دون رسوم ، وذلك فيما عدا المنازعات المحكوم فيها والمؤجلة للنطق بالحكم أو القرار .
وتخضع إجراءات التفليسة التى لم تكتمل قبل العمل بأحكام هذا القانون للإجراءات الواردة بأحكام القانون المرافق .$m251$,'65f78a61ed7385b21fa109bae65c9601'),
(5,-1,$m251$مادة 5 إصدار$m251$,$m251$يلغى الباب الخامس من قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 ، كما يلغى كل حكم يخالف أحكام القانون المرافق .$m251$,'67a3ea21056292ed00766a67aaf7ab2f'),
(6,-1,$m251$مادة 6 إصدار$m251$,$m251$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد مرور ثلاثين يوما من تاريخ نشره .$m251$,'399226acd4241beafe1c48d0956ee7a2'),
(1,0,$m251$المادة 1$m251$,$m251$فى تطبيق أحكام هذا القانون ، يقصد بالعبارات والكلمات التالية المعانى الموضحة قرين كل منها :
إدارة الإفلاس : الإدارة المنشأة بموجب هذا القانون داخل كل محكمة اقتصادية لتلقى طلبات إعادة الهيكلة ، والصلح الواقى من الإفلاس ، وشهر الإفلاس ، ومباشرة إجراءات الوساطة .
قاضى الإفلاس : أحد قضاة إدارة الإفلاس يختص بفحص الطلبات المعروضة على الإدارة .
المحكمة المختصة : الدائرة الابتدائية بالمحكمة الاقتصادية المختصة بنظر الدعاوى والمنازعات الناشئة عن تطبيق أحكام هذا القانون .
التدابير التحفظية : التدابير الضرورية التى تتخذها المحكمة أو القاضى وفقا لأحكام هذا القانون بهدف حفظ أو إدارة أصول المدين على نحو آمن ، أو منع المفلس من الهرب أو إخفاء أمواله .
الوساطة : وسيلة ودية لتسوية المنازعات التجارية عن طريق وسيط (قاضى الإفلاس) ، يتولى تقريب وجهات النظر بين الأطراف المتنازعة بمناسبة علاقة عقدية أو غير عقدية ، ويقترح عليهم الحلول الملائمة لها .
الصلح الواقى : طلب يتوقى به المدين سيئ الحظ إشهار إفلاسه .
أمين الصلح : المسئول عن مباشرة إجراءات الصلح بين طالب الصلح الواقى من الإفلاس والدائنين ومتابعتها .
قاضى الصلح : القاضى المعين لمباشرة إجراءات الصلح الواقى من الإفلاس .
الرقيب : الشخص المعين لمراقبة تنفيذ عقد الصلح الواقى من الإفلاس .
أمين التفليسة : الممثل القانونى للتفليسة الذى تعينه المحكمة لإدارتها .
المراقب : الشخص الذى يتم اختياره لمراقبة أعمال التفليسة .
قاضى التفليسة : القاضى المعين لمباشرة إجراءات التفليسة .
أمين اتحاد الدائنين : ممثل التفليسة الذى يتم اختياره من قبل الدائنين عند قيام حالة اتحاد الدائنين بإيداع قائمة الديون المقبولة .
الخبراء : الأشخاص والمكاتب والشركات المقيدون بجدول خبراء إدارة الإفلاس .
إعادة الهيكلة : الإجراءات التى تساعد التاجر على خروجه من مرحلة الاضطراب المالى والإدارى .
لجنة إعادة الهيكلة : اللجنة المشكلة من بين الخبراء المقيدين بالجدول المنصوص عليه فى المادة (13) من هذا القانون لإعداد خطة إعادة الهيكلة .
المعاون : الشخص المسئول عن معاونة التاجر على تقويم وضعه المالى والإدارى ، ومتابعة تنفيذ خطة إعادة الهيكلة ، وفقا لأحكام هذا القانون .$m251$,'7efcafd7b52fabb3bc97db2e7f509e84'),
(2,0,$m251$المادة 2$m251$,$m251$تختص الدوائر الابتدائية بالمحاكم الاقتصادية التى يقع فى دائرتها موطن تجارى للمدين أو المركز الرئيسى للشركة بنظر الدعاوى التى تنشأ عن تطبيق أحكام هذا القانون ، فإذا كان هذا المركز خارج مصر اختصت المحكمة التى يقع فى دائرتها مركز الإدارة المحلى .
وإذا لم يكن للتاجر موطن تجارى كانت المحكمة المختصة هى التى يقع فى دائرتها محل إقامته المعتادة ، ويعد موطنا مختارا للتاجر آخر موطن مثبت بالسجل التجارى . ومع عدم الإخلال بالاتفاقات الدولية النافذة فى مصر ، يجوز شهر إفلاس التاجر الذى يكون له فى مصر فرع أو وكالة ولو لم يصدر حكم بشهر إفلاسه فى دولة أجنبية ، وفى هذه الحالة تكون المحكمة المختصة بشهر الإفلاس فى مصر هى التى يقع فى دائرتها الفرع أو الوكالة .$m251$,'4ceec535a33043f3ffb5464207c94e76'),
(3,0,$m251$المادة 3$m251$,$m251$استثناء من حكم المادة (8) من قانون المحاكم الاقتصادية الصادر بالقانون رقم 120 لسنة 2008 تنشأ بكل محكمة اقتصادية إدارة تسمى (إدارة الإفلاس) ، تشكل برئاسة قاض بمحكمة الاستئناف على الأقل وعضوية عدد كاف من قضاتها بدرجة رئيس محكمة على الأقل يسمون (قضاة الإفلاس) ، تختارهم جمعيتها العامة فى بداية كل عام قضائى ، ويلحق بها عدد كاف من خبراء إدارة الإفلاس والإداريين والكتابيين .$m251$,'60c19a7931f8c9ca7f16e647f6bc0d15'),
(4,0,$m251$المادة 4$m251$,$m251$تختص إدارة الإفلاس بالآتى :
(أ) مباشرة إجراءات الوساطة فى طلبات إعادة الهيكلة والصلح الواقى من الإفلاس وشهر الإفلاس .
(ب) استيفاء مستندات الطلبات التى تختص بها محكمة الإفلاس وتحضيرها وإعداد مذكرة بطلبات الخصوم وأسانيدهم ، وذلك خلال مدة لا تجاوز ستين يوما من تاريخ قيد الطلب .$m251$,'226c846d5730c0d2d4bc4f529c96fd10'),
(5,0,$m251$المادة 5$m251$,$m251$تقدم الطلبات إلى رئيس إدارة الإفلاس بعد قيدها بقلم كتاب المحكمة المختصة ، ويقوم بعرض الطلبات على قضاة الإفلاس لاتخاذ إجراءات الوساطة فيها على أن ينتهى من ذلك خلال ثلاثين يوما من تاريخ تقديم الطلب . ولرئيس الإدارة مد هذه المدة لمدة مماثلة ، وذلك لمرة واحدة على الأكثر .$m251$,'02b9e96907a1bbae9425b0c53a942bb6'),
(6,0,$m251$المادة 6$m251$,$m251$يتعين على قاضى الإفلاس الحفاظ على سرية كافة المعلومات المتعلقة بإجراءات الوساطة ، ما لم يكن إفشاؤها لازما بمقتضى القانون أو لأغراض إنفاذ التسوية .$m251$,'eaa01b783bae8d460b58ec5a90b22fab'),
(7,0,$m251$المادة 7$m251$,$m251$يشترط لانعقاد جلسات الوساطة حضور أطراف النزاع أو وكيل عنهم بموجب توكيل خاص يبيح له تسوية النزاع .
ويجوز لقاضى الإفلاس أن يجرى الوساطة بالطريقة التى يراها مناسبة مع مراعاة طلبات الأطراف وظروف الوساطة ، وله فى ذلك الاجتماع مع أطراف النزاع أو وكلائهم أو الانفراد بكل طرف على حدة ، واتخاذ ما يراه مناسبا لتقريب وجهات النظر بهدف الوصول إلى اتفاق تسوية ملزم للطرفين .$m251$,'d2c8533a2129fe835794d2c89ff4db5e'),
(8,0,$m251$المادة 8$m251$,$m251$يجوز لقاضى الإفلاس الاستعانة بمن يراه لازما لاستكمال إجراءات الوساطة بما فى ذلك خبراء لجنة إعادة الهيكلة وله تكليف أى من طرفى النزاع بسداد أمانة الخبير .$m251$,'924d7a5ab2c1f602dc39d4c9e483ad65'),
(9,0,$m251$المادة 9$m251$,$m251$إذا تم التوصل إلى تسوية النزاع ، يحرر اتفاق تسوية يوقع عليه كافة الأطراف ، ويبين فيه تفاصيل الاتفاق ، وما تم من إجراءات الوساطة . ويصدر قاضى الإفلاس قرارا باعتماد التسوية وإنهاء الطلب ، ويكون لهذا الاتفاق قوة السند التنفيذى .$m251$,'a411be63683bacdeb49ddc34b2ccb7c5'),
(10,0,$m251$المادة 10$m251$,$m251$إذا لم يتم التوصل إلى التسوية ، يرفض قاضى الإفلاس الطلب ويحدد له جلسة أمام المحكمة المختصة ويكلف من قدمه بإعلان ذوى الشأن ، وذلك بصحيفة تودع قلم الكتاب .$m251$,'ad25919ee7fe805aa3f449cdc6d65dcb'),
(11,0,$m251$المادة 11$m251$,$m251$فى حالة عدم حضور مقدم الطلب أمام قاضى الإفلاس جلستين ، يأمر القاضى بحفظ الطلب .$m251$,'382718dbdbe410d14398f7709a2fb1af'),
(12,0,$m251$المادة 12$m251$,$m251$قرارات قاضى الإفلاس نهائية لا يجوز الطعن عليها ، ما لم ينص القانون على خلاف ذلك ، أو كان القرار مما يجاوز اختصاصه ويكون الطعن فى هذه الحالة أمام المحكمة المختصة خلال عشرة أيام من تاريخ صدور القرار .$m251$,'62a49ad6c62d58cf81f8e4262155cadf'),
(13,0,$m251$المادة 13$m251$,$m251$ينشأ جدول يلحق بجداول خبراء المحاكم الاقتصادية يسمى (جدول خبراء إدارة الإفلاس) يقيد به عدد كاف من المكاتب والشركات المتخصصة فى مجال إعادة الهيكلة وإدارة الأصول وخبراء من وزارات المالية والاستثمار والتجارة والصناعة والقوى العاملة والبنك المركزى المصرى والهيئة العامة للاستثمار والهيئة العامة للرقابة المالية والبورصة المصرية والاتحاد العام للغرف التجارية المصرية واتحاد الصناعات المصرية وأمناء التفليسة والخبراء المثمنين وغيرهم عند الاقتضاء .
ويصدر الوزير المختص اللائحة المنظمة لاختيارهم ، وقيدهم ، وكيفية مباشرتهم لعملهم ، ومساءلتهم ، والحدين الأقصى والأدنى لمقابل ما يؤدونه من أعمال .$m251$,'55c94c7899cbcd2d0c4fa9f9c4ffe5cd'),
(14,0,$m251$المادة 14$m251$,$m251$للقاضى المختص فى أى مرحلة يكون عليها النزاع تشكيل لجنة تسمى (لجنة إعادة الهيكلة) من الخبراء المقيدين بجدول خبراء إدارة الإفلاس ، وتختص هذه اللجنة بوضع خطة إعادة الهيكلة وإدارة أصول التاجر وتقييمها بالإضافة إلى ما تكلف به من أعمال أخرى .
ويتولى القاضى المختص تقدير أتعاب اللجنة .$m251$,'8fac33f77f594b59333fefcaa4a5ae9f'),
(15,0,$m251$المادة 15$m251$,$m251$لكل تاجر ، لا يقل رأسماله عن مليون جنيه ، وزاول التجارة بصفة مستمرة خلال السنتين السابقتين على تقديم الطلب ولم يرتكب غشا أن يطلب إعادة الهيكلة .
ولا تجوز إعادة هيكلة الشركة وهى فى دور التصفية .$m251$,'1b879af92ed1b57db2ce83a6162303a4'),
(16,0,$m251$المادة 16$m251$,$m251$تجوز إعادة هيكلة نشاط أو أموال التاجر بعد وفاته بناء على طلب ورثته خلال السنة التالية للوفاة ، شريطة موافقة جميع الورثة .$m251$,'d556b9ef62b0b2c79aee590d2b23195e'),
(17,0,$m251$المادة 17$m251$,$m251$لا يجوز التقدم بطلب إعادة الهيكلة فى حالة صدور حكم بشهر إفلاس التاجر أو الحكم بافتتاح إجراءات الصلح الواقى منه .
ويترتب على تقديم طلب إعادة الهيكلة وقف طلبى شهر الإفلاس والصلح الواقى منه إلى حين انتهاء البت فى طلب إعادة الهيكلة .
ولا يجوز تقديم طلب آخر بإعادة الهيكلة إلا بعد مرور ثلاثة أشهر من رفض أو حفظ الطلب السابق .$m251$,'8bc0ebcb9de0fd0706d944606134a72c'),
(18,0,$m251$المادة 18$m251$,$m251$تهدف إعادة الهيكلة إلى وضع خطة لإعادة تنظيم أعمال التاجر المالية والإدارية تتضمن كيفية خروجه من مرحلة الاضطراب المالى والإدارى وسداد ديونه مع بيان مصادر التمويل المقترحة ، ويكون ذلك بعدة طرق منها إعادة تقييم الأصول ، وإعادة هيكلة الديون ومنها ديون الدولة ، وزيادة رأس المال ، وزيادة التدفقات النقدية الداخلية وخفض التدفقات النقدية الخارجية ، وإعادة الهيكلة الإدارية .$m251$,'bbe49e0a35633c25188d56a39df5ae3c'),
(19,0,$m251$المادة 19$m251$,$m251$يقدم طلب إعادة الهيكلة مبينا فيه أسباب الاضطراب المالى وتاريخ نشأته وما اتخذ فى شأنه من إجراءات لتجنب حدوثه أو معالجة آثاره وما يراه من إجراءات لازمة للخروج منه .
ويجب أن يرفق بالطلب المستندات الآتية :
(أ) الوثائق المؤيدة للبيانات المذكورة فيه .
(ب) شهادة من مكتب السجل التجارى تثبت قيام التاجر بما تفرضه الأحكام الخاصة بالسجل التجارى خلال السنتين السابقتين على طلب إعادة الهيكلة .
(ج) شهادة من الغرفة التجارية تفيد مزاولة التجارة بصفة مستمرة خلال السنتين السابقتين على طلب إعادة الهيكلة .
(د) صورة من الميزانية وحساب الأرباح والخسائر عن السنتين السابقتين على طلب إعادة الهيكلة .
(هـ) بيان بإجمالى المصروفات الشخصية فى السنتين السابقتين على طلب إعادة الهيكلة عدا الطلب المقدم من إحدى شركات المساهمة .
(و) بيان تفصيلى بالأموال المنقولة وغير المنقولة وقيمتها التقريبية عند طلب إعادة الهيكلة .
(ز) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم والتأمينات الضامنة لها .
(ح) شهادة تفيد عدم تقدمه بطلب إعادة هيكلة من قبل ، أو تقدمه بطلب سبق حفظه ومرت فترة ثلاثة أشهر على ذلك .
(ط) شهادة بعدم شهر إفلاس التاجر أو عقد صلح واق منه .
وإذا كان الطلب خاصا بشركة وجب أن يرفق به فضلا عن الوثائق المذكورة فى الفقرة السابقة صورة من عقد الشركة ونظامها مصدقا عليها من مكتب السجل التجارى والوثائق المثبتة لصفة مقدم الطلب وقرار الشركاء أو الجمعية العامة بطلب إعادة الهيكلة ، وبيان بأسماء الشركاء المتضامنين وعناوينهم وجنسياتهم .
ويجب أن تكون تلك الوثائق مؤرخة وموقعة من الطالب ، وإذا تعذر تقديم بعضها أو استيفاء بياناتها وجب أن يتضمن الطلب أسباب ذلك .
وللقاضى إلزام مقدم الطلب خلال المدة التى يحددها بتقديم معلومات أو مستندات إضافية حول وضعه الاقتصادى والمالى .$m251$,'0dc2c9b5cf05ac2baff4fa4a9cf67dbe'),
(20,0,$m251$المادة 20$m251$,$m251$ترفع لجنة إعادة الهيكلة تقريرا إلى قاضى الإفلاس ، خلال ثلاثة أشهر من تاريخ تقديم الطلب ، متضمنا رأيها عن سبب اضطراب أعمال التاجر وجدوى إعادة الهيكلة والخطة المقترحة لذلك ، ويجوز مدها بإذن قاضى الإفلاس ثلاثة أشهر أخرى ، على أن يتم تنفيذ خطة إعادة الهيكلة فى مدة لا تزيد على خمس سنوات .$m251$,'edf2c5fd7bf1cb27f94e9c3b237085bf'),
(21,0,$m251$المادة 21$m251$,$m251$يعتمد قاضى الإفلاس خطة إعادة الهيكلة التى ترفعها لجنة إعادة الهيكلة بناء على موافقة الأطراف الموقعين عليها ، وتكون خطة إعادة الهيكلة فى هذه الحالة ملزمة لهم .
ويعين قاضى الإفلاس معاونا لمساعدة التاجر إذ رأى موجبا لذلك ، من بين الأمناء أو الخبراء المقيدين بجدول خبراء إدارة الإفلاس أو من غيرهم ممن يختاره الأطراف على أن يحدد أتعاب المعاون وفقا لما اتفق عليه الأطراف وفى حالة تعذر ذلك يحدد القاضى تلك الأتعاب .$m251$,'0b8c7d1a552e8c20bf390cb906fa4816'),
(22,0,$m251$المادة 22$m251$,$m251$يقوم المعاون بجميع الأعمال التى يقتضيها الغرض من تعيينه ومنها :
(أ) معاونة التاجر على تقويم وضعه المالى والإدارى .
(ب) تقديم المشورة والدعم الفنى له .
(ج) وضع آلية تنفيذ إجراءات خطة إعادة الهيكلة .
(د) مساعدة التاجر فى التسوية الودية مع دائنيه .
(هـ) إعداد تقرير كل ثلاثة أشهر وعرضه على قاضى الإفلاس والأطراف لاطلاعهم على تقدم سير إجراءات خطة إعادة الهيكلة ومدى التزام التاجر بها .$m251$,'4adf16a03e3adda44a43f03fe06a05a4'),
(23,0,$m251$المادة 23$m251$,$m251$يجوز لقاضى الإفلاس استبدال المعاون بأجر من تلقاء نفسه أو بناء على طلب أى من أطراف خطة إعادة الهيكلة .$m251$,'c4bfb85598d73c95c64d4bd6d0c41301'),
(24,0,$m251$المادة 24$m251$,$m251$يستمر التاجر فى إدارة أمواله طوال فترة إعادة الهيكلة ويظل مسئولا عما ينشأ عنها من التزامات أو تعاقدات سابقة أو لاحقة لتاريخ اعتماد خطة إعادة الهيكلة بما لا يخالف هذه الخطة .$m251$,'c8c09c90bcdaded51cecc7fbb964a22e'),
(25,0,$m251$المادة 25$m251$,$m251$لايجوز للتاجر القيام بأى من التصرفات التى تؤثر على مصالح الدائنين بما فى ذلك البيع الذى لا علاقة له بممارسة أعماله التجارية المعتادة والتبرع والهبة والاقتراض أو الإقراض أو أى من الأعمال المجانية والكفالات وأى رهن أو تأمين أو أى من الأعمال المماثلة ، بما يخالف خطة إعادة الهيكلة .$m251$,'efc9a1860894d43b031c3f488c30a233'),
(26,0,$m251$المادة 26$m251$,$m251$يجوز لكل ذى مصلحة اللجوء إلى قاضى الإفلاس للنظر فى أى طلب يتعلق بخطة إعادة الهيكلة .$m251$,'296a46e271586d8525fd26133e1025a7'),
(27,0,$m251$المادة 27$m251$,$m251$استثناء من حكم المادة ( 10 ) ، يأمر قاضى الإفلاس بحفظ طلب إعادة الهيكلة فى الأحوال التالية :
(أ) إذا تعذر الاتفاق على خطة إعادة الهيكلة .
(ب) إذا لم يرفق التاجر بطلبه المعلومات أو المستندات المبينة سلفا أو التى كلف بتقديمها خلال الأجل الذى حدد لذلك .
(ج) إذا لم يقم التاجر بسداد التكاليف والمصروفات اللازمة لإجراءات إعادة الهيكلة ومن بينها أتعاب المعاون أو إذا تبين أن موجوداته لا تكفى لسدادها .
(د) زوال الأسباب التى دعت التاجر إلى التقدم بطلب إعادة الهيكلة .
(هـ) إذا كانت إجراءات إعادة الهيكلة غير ملائمة للتاجر استنادا إلى البيانات والمستندات المقدمة مع الطلب أو استنادا إلى التقرير الذى تعده لجنة إعادة الهيكلة .
(و) إذا لم يتفق جميع الورثة على إعادة الهيكلة .$m251$,'2b93f078f9b2a0df00536fed6b64139c'),
(28,0,$m251$المادة 28$m251$,$m251$ينهى القاضى خطة إعادة الهيكلة بانتهاء تنفيذها أو تعذر ذلك أو الإخلال بها لأى سبب بناء على طلب أى من أطرافها .$m251$,'63bb3f6f28c2dc1d7716a5596e196a58'),
(29,0,$m251$المادة 29$m251$,$m251$لايجوز بعد اعتماد خطة إعادة الهيكلة رفع دعوى بين التاجر وأى من الدائنين الموقعين ، تكون متعلقة بتلك الخطة أو السير فيها أو رفع الدعاوى الفردية أو اتخاذ الإجراءات القضائية ، وتوقف مدد التقادم المتعلقة بالدعاوى والمطالبات والديون الخاصة بهم ، وذلك كل لحين انتهاء خطة إعادة الهيكلة .$m251$,'ff303da6227b7e00a6fabdbcb4ea4413'),
(30,0,$m251$المادة 30$m251$,$m251$لكل تاجر يجوز شهر إفلاسه ، ولم يرتكب غشا أو خطأ لايصدر عن التاجر العادى ، أن يطلب الصلح الواقى من الإفلاس إذا اضطربت أعماله المالية اضطرابا من شأنه أن يؤدى إلى توقفه عن الدفع .
وللتاجر الذى توقف عن دفع ديونه ولو طلب شهر إفلاسه ، أن يطلب الصلح الواقى من الإفلاس إذا توافرت فيه الشروط المذكورة فى الفقرة السابقة وقدم طلب الصلح خلال خمسة عشر يوما من تاريخ توقفه عن الدفع .
ويجوز إجراء الصلح الواقى من الإفلاس لكل شركة توافرت فيها الشروط المنصوص عليها فى الفقرتين السابقتين ، ومع ذلك لايجوز منح هذا الصلح لشركة فى دور التصفية .$m251$,'8697567486787e108c88494c26f55454'),
(31,0,$m251$المادة 31$m251$,$m251$لا يقبل طلب الصلح الواقى من الإفلاس إلا إذا كان الطالب قد زاول التجارة بصفة مستمرة خلال السنتين السابقتين على تقديم الطلب وقام خلال هذه المدة بما تفرضه عليه الأحكام الخاصة بالسجل التجارى وبالدفاتر التجارية .
ولا يجوز للشركة طلب الصلح الواقى إلا بعد الحصول على إذن بذلك من أغلبية الشركاء أو من الجمعية العامة بحسب الأحوال .$m251$,'d806e859d7b6c3e0643a98342c41c11b'),
(32,0,$m251$المادة 32$m251$,$m251$لمن آل إليهم المتجر بطريق الإرث أو الوصية أن يطلبوا الصلح الواقى إذا قرروا الاستمرار فى التجارة وكان التاجر قبل وفاته ممن يجوز لهم طلب الصلح .
ويجب أن يطلب الورثة أو الموصى إليهم الصلح الواقى خلال ثلاثة أشهر من تاريخ الوفاة وإذا لم يتفق الورثة أو الموصى إليهم جميعا على طلب الصلح ، وجب على المحكمة أن تسمع أقوال من عارض منهم فى طلب الصلح ثم تفصل فيه وفقا لمصلحة ذوى الشأن .$m251$,'116b920cf76d1ad05010590af6c9c469'),
(33,0,$m251$المادة 33$m251$,$m251$لايجوز للمدين أثناء تنفيذ الصلح الواقى أو إعادة الهيكلة أن يطلب صلحا آخر .$m251$,'41cab781ffceaeac90c18cee2faf6771'),
(34,0,$m251$المادة 34$m251$,$m251$إذا قدم طلب إلى إدارة الإفلاس لشهر إفلاس المدين وطلب آخر بالصلح الواقى من الإفلاس ، فلا يجوز الفصل فى طلب شهر الإفلاس إلا بعد الفصل فى طلب الصلح .$m251$,'6a719117a0c405ec236493de30ebb2ef'),
(35,0,$m251$المادة 35$m251$,$m251$يقدم طلب الصلح الواقى إلى رئيس إدارة الإفلاس بالمحكمة المختصة يبين فيه أسباب اضطراب الأعمال ومقترحات الصلح وضمانات تنفيذها .$m251$,'8ce9e0832cde5e4d0047d8af2d83bd0b'),
(36,0,$m251$المادة 36$m251$,$m251$يرفق بطلب الصلح الواقى المستندات الآتية :
(أ) الوثائق المؤيدة للبيانات المذكورة فيه .
(ب) شهادة من مكتب السجل التجارى تثبت قيام التاجر بما تفرضه الأحكام الخاصة بالسجل التجارى خلال السنتين السابقتين على طلب الصلح .
(ج) شهادة من الغرفة التجارية تفيد بمزاولة التجارة بصفة مستمرة خلال السنتين السابقتين على طلب الصلح .
(د) صورة من الميزانية وحساب الأرباح والخسائر عن السنتين السابقتين على طلب الصلح .
(هـ) بيان بإجمالى المصروفات الشخصية فى السنتين السابقتين على طلب الصلح عدا الطلب المقدم من إحدى شركات المساهمة .
(و) بيان تفصيلى بالأموال المنقولة وغير المنقولة وقيمتها التقريبية عند طلب الصلح .
(ز) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم والتأمينات الضامنة لها .
(ح) ما يفيد إيداع مبلغ عشرة آلاف جنيه خزينة المحكمة على ذمة مصروفات نشر ما يصدر من أحكام .
(ط) شهادة بعدم شهر إفلاس التاجر أو تقديم طلب إعادة الهيكلة .
وإذا كان الطلب خاصا بشركة وجب أن يرفق به فضلا عن الوثائق المذكورة فى الفقرة السابقة صورة من عقد الشركة ونظامها مصدقا عليها من مكتب السجل التجارى والوثائق المثبتة لصفة مقدم الطلب وصورة من قرار الشركاء أو الجمعية العامة بطلب الصلح وبيان بأسماء الشركاء المتضامنين وعناوينهم وجنسياتهم .
ويجب أن تكون تلك الوثائق مؤرخة وموقعة من طالب الصلح وإذا تعذر تقديم بعضها أو استيفاء بياناتها وجب أن يتضمن الطلب أسباب ذلك .
وللقاضى إلزام مقدم الطلب خلال المدة التى يحددها أن يقدم مستندات إضافية أو معلومات حول وضعه الاقتصادى والمالى .$m251$,'c9a836b2e0523326f2e7ad71b064b04a'),
(37,0,$m251$المادة 37$m251$,$m251$للمحكمة التى تنظر فى طلب الصلح أن تأمر باتخاذ التدابير اللازمة للمحافظة على أموال المدين إلى حين الفصل فى الطلب .
ويجوز للمحكمة أن تتخذ من الإجراءات ما يمكنها من الإحاطة بحالة المدين المالية وأسباب اضطرابها .
وتنظر المحكمة فى طلب الصلح فى غير علانية وعلى وجه الاستعجال وتفصل فى الطلب بحكم انتهائى .$m251$,'d7949d11886da8ab94887f26cdde3637'),
(38,0,$m251$المادة 38$m251$,$m251$يجب أن تقضى المحكمة برفض طلب الصلح الواقى فى الأحوال الآتية :
(أ) إذا لم يقدم طالب الصلح الوثائق والبيانات المنصوص عليها فى المادة (36) من هذا القانون أو قدمها ناقصة دون مسوغ .
(ب) إذا سبق الحكم على التاجر بالإدانة فى إحدى جرائم الإفلاس بالتدليس أو فى جريمة التزوير أو السرقة أو النصب أو خيانة الأمانة أو إصدار شيك بدون مقابل وفاء أو اختلاس الأموال العامة ما لم يكن قد رد إليه اعتباره .
(ج) إذا اعتزل التجارة أو لجأ إلى الفرار .$m251$,'d72cb2292ad753d57f2a6fe40f7835a0'),
(39,0,$m251$المادة 39$m251$,$m251$إذا قضت المحكمة برفض طلب الصلح الواقى جاز أن تحكم على التاجر بغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه إذا تبين لها أنه تعمد الإيهام باضطراب أعماله أو إحداث الاضطراب فيها .$m251$,'d2d1af23d101b8ff4563814c9c7e6895'),
(40,0,$m251$المادة 40$m251$,$m251$إذا قضت المحكمة بقبول الصلح الواقى ، وجب أن تأمر بافتتاح الإجراءات ، ويجب أن يتضمن الحكم ما يأتى :
(أ) ندب أحد قضاة الصلح بالمحكمة للإشراف على إجراءاته .
(ب) تعيين أمين أو أكثر لمباشرة إجراءات الصلح ومتابعتها .
ويجوز للمحكمة أن تأمر فى حكم افتتاح إجراءات الصلح بأن يودع المدين خزينة المحكمة أمانة نقدية لمواجهة مصاريف الإجراءات ، ويجوز أن تقضى المحكمة بإلغاء إجراءات الصلح أو بوقفها إذا لم يودع المدين الأمانة فى الميعاد الذى عينته .$m251$,'0d060105a20cc52d3f0a41f3f0f17180'),
(41,0,$m251$المادة 41$m251$,$m251$يعين أمين الصلح من بين الأشخاص أو الشركات المرخص لهم فى مزاولة مهنة أمين التفليسة ، ويدون أمين الصلح يوميا بيوم جميع الأعمال المتعلقة بالصلح فى دفتر خاص يضع قاضى الصلح توقيعه أو ختمه عليه ويؤشر بنهاية الدفتر بما يفيد انتهاءه ، ويجوز للمحكمة وأطراف الصلح الاطلاع عليه .$m251$,'d626b347e2a36d573aa9eb79e8175317'),
(42,0,$m251$المادة 42$m251$,$m251$يجوز الطعن على قرارات قاضى الصلح بصحيفة تودع قلم كتاب المحكمة وتعلن لذوى الشأن خلال عشرة أيام من تاريخ إيداع القرار .
وتنظره المحكمة فى أول جلسة على ألا يشترك قاضى الصلح فى نظر الطعن .$m251$,'303c7d9a339d58a99f71abb00fa098a6'),
(43,0,$m251$المادة 43$m251$,$m251$يترتب على الطعن وقف تنفيذ القرار حتى تفصل المحكمة فى أمره ، ما لم تأمر باستمرار تنفيذه .
وإذا رفضت المحكمة الطعن تحكم على الطاعن بغرامة لاتجاوز خمسين ألف جنيه ، إذا تبين لها أنها تعمد تعطيل تنفيذ قرار قاضى الصلح .$m251$,'ec573e39d994c18e2dd8b1ba48e2363a'),
(44,0,$m251$المادة 44$m251$,$m251$يخطر قلم الكتاب أمين الصلح بالحكم الصادر بتعيينه فور صدوره .
ويقوم أمين الصلح خلال خمسة أيام من تاريخ الإخطار بقيد الحكم بافتتاح إجراءات الصلح فى السجل التجارى ونشر ملخصه مصحوبا بدعوة الدائنين إلى الاجتماع فى صحيفة يومية يعينها قاضى الصلح .
وعلى أمين الصلح أن يرسل فى الميعاد المذكور فى الفقرة السابقة الدعوة إلى الاجتماع مرفقا بها مقترحات الصلح إلى الدائنين المعلومة عناوينهم .$m251$,'86cbcc13b86e38942dcc7a6c376fb711'),
(45,0,$m251$المادة 45$m251$,$m251$يقوم قاضى الصلح فور صدور الحكم بافتتاح إجراءات الصلح بقفل دفاتر المدين ووضع توقيعه عليها .
ويباشر أمين الصلح خلال أربع وعشرين ساعة من وقت إخطاره بصدور الحكم إجراءات الجرد بحضور المدين وكاتب المحكمة .$m251$,'ad783f6e63160d036c396f612db4f939'),
(46,0,$m251$المادة 46$m251$,$m251$يستمر المدين بعد صدور الحكم بافتتاح إجراءات الصلح قائما على إدارة أمواله بإشراف أمين الصلح ، وله أن يقوم بجميع التصرفات العادية التى تقتضيها أعماله التجارية ، ومع ذلك لايجوز الاحتجاج على الدائنين بالتبرعات التى يجريها المدين بعد صدور الحكم المذكور .
ولا يجوز للمدين بعد صدور الحكم بافتتاح إجراءات الصلح أن يعقد صلحا أو رهنا من أى نوع أو أن يجرى تصرفا ناقلا للملكية لا تستلزمه أعماله التجارية العادية إلا بعد الحصول على إذن من قاضى الصلح ، ومع عدم الإخلال بحقوق المتصرف إليه حسن النية ، لا يحتج على الدائنين بكل تصرف يتم على خلاف ذلك .$m251$,'bf9a3f1f84d47c5f82e2191e2a6f6bd8'),
(47,0,$m251$المادة 47$m251$,$m251$توقف جميع الدعاوى وإجراءات التنفيذ الموجهة إلى المدين بمجرد الحكم بافتتاح إجراءات الصلح ، أما الدعاوى المرفوعة من المدين وإجراءات التنفيذ التى باشرها فتبقى سارية مع إدخال أمين الصلح فيها .
ولا يجوز بعد صدور الحكم بافتتاح إجراءات الصلح التمسك قبل الدائنين بقيد الرهون وحقوق الامتياز والاختصاص المقررة على أموال المدين .$m251$,'794dcc6b5e30e53521cdb734e2002842'),
(48,0,$m251$المادة 48$m251$,$m251$لا يترتب على صدور الحكم بافتتاح إجراءات الصلح حلول آجال الديون التى على المدين أو وقف سريان عوائدها .$m251$,'9442bb3f42528a2b7288b4e299fc3038'),
(49,0,$m251$المادة 49$m251$,$m251$إذا أخفى المدين بعد تقديم طلب الصلح جزءا من أمواله أو أتلفه أو أجرى بسوء نية تصرفات ضارة بالدائنين أو تصرفات مخالفة لأحكام المادة (46) من هذا القانون تقضى المحكمة من تلقاء ذاتها بإلغاء إجراءات الصلح .$m251$,'20171252067df0e847ee2bbc95d11ade'),
(50,0,$m251$المادة 50$m251$,$m251$على جميع الدائنين ولو كانت ديونهم غير حالة أو مضمونة بتأمينات خاصة أو ثابتة بأحكام نهائية أن يسلموا أمين الصلح خلال خمسة عشر يوما من تاريخ نشر ملخص الحكم بافتتاح إجراءات الصلح فى الصحف أصول مستندات ديونهم مصحوبة ببيان هذه الديون وتأميناتها إن وجدت ومقدارها مقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزى بيعا أو إقفالا أو تحويلات أو بنكنوتا إذا لم يوجد سعر تحويلات يوم صدور الحكم ، ويرسل البيان والمستندات إلى أمين الصلح بكتاب مسجل مصحوبا بعلم الوصول .
ويكون الميعاد المذكور فى الفقرة السابقة ثلاثين يوما بالنسبة إلى الدائنين المقيمين خارج مصر .
ولا يضاف إلى الميعاد المذكور فى الفقرتين السابقتين ميعاد للمسافة .$m251$,'cfe935ef823e6fdc6f055338c5c2c6dc'),
(51,0,$m251$المادة 51$m251$,$m251$يضع أمين الصلح بعد انتهاء الميعاد المنصوص عليه فى المادة ( 50 ) من هذا القانون قائمة بأسماء الدائنين الذين طلبوا الاشتراك فى إجراءات الصلح وبيانا بمقدار كل دين على حدة والمستندات التى تؤيده والتأمينات التى تضمنه إن وجدت وما يراه بشأن قبوله أو رفضه .
ولأمين الصلح أن يطلب من الدائن تقديم إيضاحات عن الدين أو تكملة مستنداته أو تعديل مقداره أو صفاته .$m251$,'2db128da914e5c246b32e6de2aa0ac69'),
(52,0,$m251$المادة 52$m251$,$m251$على أمين الصلح إيداع قائمة الديون قلم كتاب المحكمة خلال أربعين يوما على الأكثر من تاريخ صدور حكم افتتاح إجراءات الصلح ، ويجوز عند الاقتضاء إطالة هذا الميعاد بقرار من قاضى الصلح .
ويقوم أمين الصلح فى اليوم التالى للإيداع بنشر بيان بحصول الإيداع فى صحيفة يومية واسعة الانتشار يحددها قاضى الصلح .
ولكل ذى مصلحة الاطلاع على القائمة المودعة قلم كتاب المحكمة .$m251$,'383f5995ec78b6aa1517ca40dd10bd20'),
(53,0,$m251$المادة 53$m251$,$m251$للمدين ولكل دائن ورد اسمه بقائمة الديون أن ينازع فى الديون المدرجة بها خلال عشرة أيام من تاريخ النشر فى الصحف عن حصول الإيداع ، وتقدم المنازعة إلى قلم الكتاب ولا يضاف إلى هذا الميعاد ميعاد المسافة .$m251$,'59e24cd68e58de620916d812882fc041'),
(54,0,$m251$المادة 54$m251$,$m251$يضع قاضى الصلح بعد انقضاء الميعاد المنصوص عليه فى المادة (53) من هذا القانون قائمة نهائية بالديون غير المتنازع عليها ويؤشر على البيان الخاص بالدين بما يفيد قبوله ومقدار المقبول منه .
ويجوز لقاضى الصلح اعتبار الدين متنازعا عليه ولو لم تقدم بشأنه أى منازعة .
ويفصل قاضى الصلح فى الديون المتنازع عليها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة .
ويخطر قلم كتاب المحكمة ذوى الشأن بميعاد الجلسة قبل انعقادها بثلاثة أيام على الأقل ، كما يبلغهم القرار الصادر فى المنازعة فور صدوره .$m251$,'dc812bb5caae751a6045165eda895f98'),
(55,0,$m251$المادة 55$m251$,$m251$يجوز الطعن أمام المحكمة فى القرار الصادر من قاضى الصلح بقبول الدين أو رفضه خلال عشرة أيام من تاريخ إيداع القرار أو الإخطار به ، ولا يترتب على الطعن وقف إجراءات الصلح إلا إذا أمرت المحكمة بذلك .
ويجوز للمحكمة قبل الفصل فى الطعن أن تأمر بقبول الدين مؤقتا بمبلغ تقدره ولا يجوز قبول الدين مؤقتا إذا أقيمت بشأنه دعوى جنائية .
وإذا كانت المنازعة على الدين متعلقة بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا .$m251$,'b13a9c7dada2164d8171817518a2412d'),
(56,0,$m251$المادة 56$m251$,$m251$لا يجوز أن يشترك فى إجراءات الصلح الواقى الدائنون الذين لم يقدموا أصول مستندات ديونهم فى الميعاد المنصوص عليه فى المادة ( 50 ) من هذا القانون ولا الدائنون الذين لم تقبل ديونهم نهائيا أو مؤقتا .$m251$,'0cb85f540185836142743dada36de693'),
(57,0,$m251$المادة 57$m251$,$m251$يعين قاضى الصلح بعد الانتهاء من تحقيق الديون ميعادا لاجتماع الدائنين للمداولة فى مقترحات الصلح ، وترسل الدعوة إلى حضور هذا الاجتماع إلى كل دائن قبل دينه نهائيا أو مؤقتا ، ويجوز لقاضى الصلح أن يأمر بنشر الدعوة فى صحيفة يومية يعينها .$m251$,'8fbcc8ea5b8c29eb9e2be16697e32d10'),
(58,0,$m251$المادة 58$m251$,$m251$يودع أمين الصلح قلم كتاب المحكمة قبل الميعاد المعين لاجتماع الدائنين بخمسة أيام على الأقل تقريرا عن حالة المدين المالية وأسباب اضطرابها وبيانا بأسماء الدائنين الذين لهم الحق فى الاشتراك فى إجراءات الصلح ، ويجب أن يتضمن التقرير رأى أمين الصلح فى الشروط التى اقترحها المدين للصلح .
ويجوز لكل ذى مصلحة أن يطلب من قاضى الصلح الإذن له بالاطلاع على التقرير المذكور .$m251$,'97da89bf51d3a1c42dd8c5424efbab6e'),
(59,0,$m251$المادة 59$m251$,$m251$يتولى قاضى الصلح رئاسة اجتماع الدائنين .
ويجوز للدائن أن ينيب عنه وكيلا فى حضور الاجتماع ، ويجب أن يحضر المدين بنفسه أو ممثل الشركة المدينة بحسب الأحوال ، ولا يجوز أن يقيم عنه وكيلا فى الحضور بدلا منه إلا لعذر يقبله قاضى الصلح .
ولا تجوز المداولة فى شروط الصلح إلا بعد تلاوة تقرير أمين الصلح المشار إليه فى المادة (58) من هذا القانون ، ويجوز للمدين تعديل شروطه للصلح أثناء المداولة .$m251$,'cfdb2b2420677ba7f0df68280e1cbf07'),
(60,0,$m251$المادة 60$m251$,$m251$لا يقع الصلح إلا بموافقة أغلبية الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا بشرط أن يكونوا حائزين لثلثى قيمة هذه الديون ، ولا يحسب فى هاتين الأغلبيتين الدائنون الذين لم يشتركوا فى التصويت كما لا تحسب ديونهم .
وإذا كان الصلح خاصا بشركة أصدرت سندات قرض أو صكوك تمويل تجاوز قيمتها ثلث مجموع ديونها فلا يجوز إجراء الصلح إلا إذا وافقت على ذلك الجمعية العامة لجماعة مالكى هذه السندات أو الصكوك .$m251$,'0c132e656f83d94d29d49695177609fb'),
(61,0,$m251$المادة 61$m251$,$m251$لا يجوز لزوج طالب الصلح ولأقاربه حتى الدرجة الثانية الاشتراك فى مداولات الصلح أو التصويت على شروطه .
وإذا نزل أحد هؤلاء الدائنين المقبول دينهم نهائيا أو مؤقتا عن دينه إلى الغير بعد صدور الحكم بافتتاح إجراءات الصلح فلا يجوز للمتنازل إليه الاشتراك فى مداولات الصلح أو التصويت عليه .$m251$,'a585365631df66d5474e4cd81cf1b382'),
(62,0,$m251$المادة 62$m251$,$m251$لا يجوز للدائنين أصحاب التأمينات العينية أو المنقولة المسجلة المقررة على أموال طالب الصلح الاشتراك فى التصويت على الصلح بديونهم المضمونة بالتأمينات المذكورة إلا إذا نزلوا عن هذه التأمينات مقدما ، ويجوز أن يكون التنازل مقصورا على جزء من التأمين بشرط ألا يقل عما يقابل ثلث الدين ، ويتم إثبات التنازل فى محضر الجلسة .
إذا اشترك أحد الدائنين المذكورين فى الفقرة السابقة فى التصويت على الصلح دون أن يصرح بالتنازل عن تأمينه كله أو بعضه اعتبر ذلك تنازلا عن التأمين بأجمعه .
وفى جميع الأحوال لا يكون التنازل عن التأمين نهائيا إلا إذا تم الصلح وصدقت عليه المحكمة .
وإذا أبطل الصلح عاد التأمين الذى شمله التنازل .$m251$,'e7ecd10edaa10a92cc5af65297e10e90'),
(63,0,$m251$المادة 63$m251$,$m251$يوقع الصلح الواقى فى الجلسة التى تم فيها التصويت عليه وإلا كان لاغيا .
وإذا لم تتحقق إحدى الأغلبيتين المنصوص عليهما فى المادة ( 60 ) من هذا القانون تأجلت المداولة عشرة أيام لا مهلة بعدها .
ويجوز للدائنين الذين حضروا الاجتماع الأول أو كانوا ممثلين فيه ووقعوا محضر الصلح ألا يحضروا الاجتماع الثانى ، وفى هذه الحالة تبقى موافقتهم على الصلح فى الاجتماع الأول قائمة ونافذة فى الاجتماع الثانى إلا إذا حضروا هذا الاجتماع وعدلوا عن موافقتهم السابقة أو عدلوها أو إذا أدخل المدين تعديلا جوهريا فى مقترحاته بشأن الصلح فى الفترة بين الاجتماعين .$m251$,'7217aaed28879c71f2328dbb0182dee5'),
(64,0,$m251$المادة 64$m251$,$m251$يحرر محضر بما تم فى جلسة الصلح يوقعه قاضى الصلح وأمين الصلح والمدين والدائنون الحاضرون .
ويجوز لكل دائن له حق الاشتراك فى مداولات الصلح أن يبلغ قاضى الصلح كتابة بما لديه من اعتراض على الصلح وأسبابه وذلك خلال عشرة أيام من تاريخ التوقيع على محضر الصلح .
وعلى قاضى الصلح خلال سبعة أيام من انقضاء الميعاد المنصوص عليه فى الفقرة السابقة أن يرسل محضر الصلح إلى المحكمة التى أصدرت الأمر بافتتاح إجراءات الصلح للتصديق عليه ، وذلك مع تقرير من القاضى عن حالة المدين المالية وأسباب اضطراب أعماله وشروط الصلح وبيان بالاعتراضات التى قدمت على الصلح وأسبابها .$m251$,'08ef5325042c9f0f0f3681be9b6edb01'),
(65,0,$m251$المادة 65$m251$,$m251$يبلغ قلم كتاب المحكمة المدين والدائنين الذين قدموا اعتراضات على الصلح بميعاد الجلسة التى حددت لنظر هذه الاعتراضات وطلب التصديق على الصلح ، ويجوز لكل ذى مصلحة حضور هذه الجلسة .
وتفصل المحكمة فى الاعتراضات وفى طلب التصديق على الصلح بحكم واحد يكون نهائيا سواء أكان بقبول التصديق على الصلح أم برفض التصديق عليه .
ويجوز للمحكمة أن ترفض التصديق على الصلح ولو لم يقدم بشأنه أى اعتراض إذا وجدت أسباب تتصل بالمصلحة العامة أو بمصلحة الدائنين تبرر ذلك .
وإذا رفضت المحكمة الاعتراض على الصلح جاز لها الحكم على المعترض بغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرين ألف جنيه إذا تبين أنه تعمد تأخير الصلح .$m251$,'24e5f3e1c45371500e7c8007a887e707'),
(66,0,$m251$المادة 66$m251$,$m251$يجوز أن يتضمن الصلح الواقى منح المدين آجالا لوفاء الديون أو الفوائد ، كما يجوز أن يتضمن إبراء المدين من جزء من الدين أو الفوائد .
ويجوز أن يعقد الصلح بشرط الوفاء إذا أيسر المدين خلال مدة تعين فى شروط الصلح على ألا تجاوز خمس سنوات من تاريخ التصديق على الصلح ، ولا يعتبر المدين قد أيسر إلا إذا زادت موجوداته على الديون المترتبة عليه بما يعادل عشرة فى المائة على الأقل ، وللدائنين أن يشترطوا تقديم ضمان عينى أو شخصى لتنفيذ شروط الصلح .$m251$,'775bd9638562db0d5cd3d609a1205e1f'),
(67,0,$m251$المادة 67$m251$,$m251$يشهر الحكم الصادر بالتصديق على الصلح الواقى وفقا للأحكام المقررة لشهر حكم الإفلاس .
ويجب أن يشتمل ملخص الحكم الذى ينشر فى الصحف على اسم المدين وموطنه ورقم قيده فى السجل التجارى والمحكمة التى صدقت على الصلح وتاريخ حكم التصديق .$m251$,'6f21bdcf4d31616062ce38239ffa664d'),
(68,0,$m251$المادة 68$m251$,$m251$يسرى الصلح الواقى من الإفلاس بمجرد صدور الحكم بالتصديق عليه على جميع الدائنين الذين تعتبر ديونهم عادية وفقا لأحكام الإفلاس ولو لم يشتركوا فى إجراءاته أو لم يوافقوا على شروطه .
ولا يفيد من الصلح الواقى المدينون المتضامنون مع المدين أو كفلاؤه فى الدين ومع ذلك إذا وقع الصلح مع شركة استفاد من شروطه الشركاء المسئولون فى جميع أموالهم عن ديون الشركة إلا إذا نص فى عقد الصلح على غير ذلك .
ولا يسرى الصلح على دين النفقة ولا على الديون التى نشأت بعد صدور الحكم بافتتاح إجراءات الصلح .$m251$,'e5934670c1df8406a64c519a6ca7c402'),
(69,0,$m251$المادة 69$m251$,$m251$يجوز للمحكمة التى صدقت على الصلح أن تمنح المدين بناء على طلبه آجالا للوفاء بالديون التى لا يسرى عليها الصلح بشرط ألا تجاوز الآجال التى تمنحها المحكمة الأجل المقرر فى الصلح .
ولا يترتب على التصديق على الصلح حرمان المدين من الآجال التى تكون أبعد مدى من الأجل المقرر فى الصلح .$m251$,'c9d8fde259ae15a35d0e93c5a609ffb3'),
(70,0,$m251$المادة 70$m251$,$m251$تأمر المحكمة فى حكم التصديق على الصلح بناء على تقرير من قاضى الصلح باستبقاء أمين الصلح أو بتعيين رقيب من بين الدائنين أو من غيرهم لمراقبة تنفيذ شروط الصلح وإبلاغ المحكمة بما يقع من مخالفات لهذه الشروط .
ويؤشر أمين الصلح أو الرقيب بحسب الأحوال على سند الدين بالمبالغ المدفوعة ، وفى جميع الأحوال يجب أن يسلم الدائن مخالصة للمدين بما تم قبضه توقع من أمين الصلح أو الرقيب بحسب الأحوال ، تحت إشراف قاضى الصلح .
ويطلب الرقيب من المحكمة التى صدقت على الصلح خلال عشرة أيام من الانتهاء من تنفيذ شروط الصلح ، الحكم بقفل الإجراءات ، ويشهر هذا الطلب بالكيفية المنصوص عليها فى المادة (44) من هذا القانون .
ويصدر الحكم بقفل الإجراءات خلال ثلاثين يوما من تاريخ النشر فى الصحف ، ويقيد ملخصه فى السجل التجارى .$m251$,'fd8a4596a4a5e7c6734ef3f084988497'),
(71,0,$m251$المادة 71$m251$,$m251$يبطل الصلح الواقى من الإفلاس إذا ظهر بعد التصديق عليه تدليس من جانب المدين ، ويعتبر تدليسا على وجه الخصوص إخفاء الأموال أو إخفاء الديون أو اصطناعها أو تعمد المبالغة فى مقدارها .
ويجب أن يطلب إبطال الصلح خلال ستة أشهر من اليوم الذى يظهر فيه التدليس وإلا كان الطلب غير مقبول ، وفى جميع الأحوال لا يكون الطلب مقبولا إذا قدم بعد انقضاء سنة من تاريخ صدور الحكم بالتصديق على الصلح .
ولا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بإبطال الصلح ، وتبرأ ذمة المدين بقدر ما تم سداده .
ويترتب على إبطال الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروط الصلح .
وتختص المحكمة التى أصدرت الحكم بالتصديق على الصلح بنظر دعوى إبطال الصلح .$m251$,'3e106a94cfceedd3ffc17111d3b5c71e'),
(72,0,$m251$المادة 72$m251$,$m251$للمحكمة بناء على طلب كل دائن تسرى عليه شروط الصلح أن تقضى بفسخ الصلح فى الأحوال الآتية :
(أ) إذا لم ينفذ المدين شروط الصلح كما اتفق عليها .
(ب) إذا تصرف المدين بعد التصديق على الصلح تصرفا ناقلا لملكية متجره دون مسوغ مقبول .
(ج) إذا توفى المدين وتبين أنه لا ينتظر تنفيذ الصلح أو إتمام تنفيذه .
ولا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بفسخ الصلح .
ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروطه ، ويجب تكليف الكفيل بحضور الجلسة التى ينظر فيها طلب فسخ الصلح .$m251$,'d184663d4b8eb0d4bbf2b2215f50e1b7'),
(73,0,$m251$المادة 73$m251$,$m251$يقدر قاضى الصلح أجر كل من أمين الصلح والرقيب إذا كانا من غير الدائنين ، ويودع قرار القاضى فى هذا الشأن قلم كتاب المحكمة فى اليوم التالى لصدوره ، ويجوز لكل ذى مصلحة الاعتراض على القرار أمام المحكمة خلال خمسة عشر يوما من تاريخ الإيداع ، ويكون الحكم الصادر فى الاعتراض نهائيا .$m251$,'9c49b1a088f85135bd81e271f92d065a'),
(74,0,$m251$المادة 74$m251$,$m251$يجوز للمحكمة من تلقاء ذاتها أو بناء على تقرير من قاضى الصلح أن تأمر فى الحكم بقفل إجراءات الصلح بصرف مكافأة إجمالية للرقيب إذا كان من الدائنين وتبين أنه بذل فى عمله جهدا غير عادى وكانت حالة المدين المالية تسمح بذلك .$m251$,'8ef2f9fe0aae994dc73af4bb20fbfe04'),
(75,0,$m251$المادة 75$m251$,$m251$يعد فى حالة إفلاس كل تاجر ملتزم بموجب أحكام قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 بإمساك دفاتر تجارية إذا توقف عن دفع ديونه التجارية إثر اضطراب أعماله المالية .
ولا يترتب على التوقف عن الدفع أثر قبل صدور حكم شهر الإفلاس ، ما لم ينص القانون على غير ذلك .$m251$,'16d9e24676097c609f80fa6df89e4559'),
(76,0,$m251$المادة 76$m251$,$m251$يشهر إفلاس التاجر بناء على طلبه أو طلب أحد الدائنين أو النيابة العامة ، ويجوز للمحكمة أن تقضى بشهر الإفلاس من تلقاء ذاتها .
ويجوز شهر إفلاس التاجر بعد وفاته أو اعتزاله التجارة إذا توفى أو اعتزل التجارة وهو فى حالة توقف عن الدفع . ويجب تقديم طلب شهر الإفلاس خلال السنة التالية للوفاة أو اعتزال التجارة . ولا يسرى هذا الميعاد فى حالة اعتزال التجارة إلا من تاريخ شطب اسم التاجر من السجل التجارى .
ويجوز لورثة التاجر طلب شهر إفلاسه بعد وفاته مع مراعاة الميعاد المذكور فى الفقرة السابقة . فإذا اعترض بعض الورثة على شهر الإفلاس وجب أن تسمع المحكمة أقوالهم ثم تفصل فى الطلب وفقا لمصلحة ذوى الشأن .
وتعلن صحيفة دعوى شهر الإفلاس فى حالة وفاة التاجر إلى الورثة جملة فى آخر موطن للمتوفى .
ولا تقبل دعوى الدائن بشهر إفلاس مدينه التاجر بموجب دين مضمون بالكامل بتأمين عينى أو منقول مسجل ما لم تكن قيمة الدين تزيد على قيمة الضمان .$m251$,'e6c5e4a1aa4331b53edf76a5b856be4d'),
(77,0,$m251$المادة 77$m251$,$m251$يجب على التاجر أن يطلب شهر إفلاسه خلال خمسة عشر يوما من تاريخ توقفه عن الدفع وذلك بطلب يقدم إلى إدارة الإفلاس يذكر فيه أسباب التوقف عن الدفع وترفق به الوثائق الآتية :
(أ) الدفاتر التجارية الرئيسية .
(ب) صورة من آخر ميزانية وحساب الأرباح والخسائر .
(ج) بيان بإجمالى المصروفات الشخصية عن السنتين السابقتين على تقديم طلب شهر الإفلاس أو عن مدة اشتغاله بالتجارة إذا كانت أقل من ذلك عدا الطلب المقدم من إحدى شركات المساهمة .
(د) بيان تفصيلى بما يملكه من عقارات ومنقولات وقيمتها التقريبية فى تاريخ التوقف عن الدفع ، وكذلك المبالغ النقدية المودعة باسمه لدى البنوك سواء فى مصر أو خارجها .
(هـ) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم والتأمينات الضامنة لها .
(و) بيان بالاحتجاجات التى حررت ضد التاجر خلال السنتين السابقتين على تقديم طلب شهر الإفلاس .
(ز) شهادة بعدم صدور حكم بافتتاح صلح واق من الإفلاس ، أو ما يفيد عدم تقدمه بطلب إعادة هيكلة من قبل .
ويجب أن تكون الوثائق المشار إليها فى الفقرة السابقة مؤرخة وموقعة من التاجر ، وإذا تعذر تقديم بعض هذه الوثائق أو استيفاء بياناتها وجب عليه إيضاح أسباب ذلك .
وللقاضى إلزام مقدم الطلب خلال المدة التى يحددها بتقديم مستندات إضافية أو معلومات حول وضعه الاقتصادى أو المالى .$m251$,'82821a911b56a473705018593787c4d0'),
(78,0,$m251$المادة 78$m251$,$m251$لكل دائن بدين تجارى خال من النزاع حال الأداء أن يطلب الحكم بشهر إفلاس مدينه التاجر ويكون للدائن بدين مدنى حال هذا الحق إذا أثبت أن التاجر قد توقف عن دفع ديونه التجارية الحالة فضلا عن دينه المدنى .
ويكون للدائن بدين آجل الحق فى طلب شهر الإفلاس إذا لم يكن لمدينه التاجر موطن معروف فى مصر أو إذا لجأ إلى الفرار أو أغلق متجره أو شرع فى تصفيته أو أجرى تصرفات ضارة بدائنيه بشرط أن يقدم الدائن ما يثبت أن المدين توقف عن دفع ديونه التجارية الحالة .
ويطلب الدائن شهر إفلاس مدينه بطلب يقدم إلى إدارة الإفلاس التابعة للمحكمة المختصة مصحوبا بما يفيد إيداع مبلغ عشرة آلاف جنيه خزانة المحكمة على سبيل الأمانة لحساب مصروفات نشر الحكم الصادر بشهر الإفلاس ، يطلب فيه اتخاذ الإجراءات التحفظية اللازمة ويبين فيه الظروف التى يستدل منها على توقف المدين عن دفع ديونه .$m251$,'d6eb931492363c4a3388df2925834f8b'),
(79,0,$m251$المادة 79$m251$,$m251$لا يجوز شهر إفلاس التاجر بسبب توقفه عن دفع ما يستحق عليه من غرامات جنائية أو ضرائب أو رسوم أو تأمينات اجتماعية .$m251$,'cdda89e4c040e4846a082ff02d618fe4'),
(80,0,$m251$المادة 80$m251$,$m251$استثناء من أحكام المواد (4 ، 5 ، 9 ، 10 ، 11) من هذا القانون إذا طلبت النيابة العامة شهر إفلاس التاجر ، أو إذا رأت المحكمة شهر إفلاسه من تلقاء ذاتها ، وجب على قلم الكتاب أن يعلنه بيوم الجلسة .
وفى حالة وفاة التاجر أو اعتزاله التجارة لا يجوز للمحكمة أن تنظر فى شهر الإفلاس بناء على طلب النيابة العامة بعد انقضاء السنة التالية لوفاته أو اعتزاله التجارة .$m251$,'49792b1d540150ad9811a4064825d07a'),
(81,0,$m251$المادة 81$m251$,$m251$يخطر قلم كتاب المحكمة المختصة النيابة العامة بطلب شهر الإفلاس ، ولا يحول عدم حضورها أو عدم إبداء الرأى دون الحكم فى دعوى الإفلاس .$m251$,'a961467a6a79d5263424c02e3467aa4a'),
(82,0,$m251$المادة 82$m251$,$m251$يجوز للمحكمة المختصة بنظر دعوى الإفلاس أن تأمر باتخاذ التدابير اللازمة للمحافظة على أموال المدين أو إدارتها لمدة ثلاثة أشهر تجدد لمدد أخرى إلى أن يتم الفصل فى الدعوى ، كما يجوز أن تتخذ من الإجراءات ما يمكنها من الإحاطة بحالة المدين المالية وأسباب توقفه عن الدفع .$m251$,'09b642c413fa97c5fb5eeaeaf1a2676a'),
(83,0,$m251$المادة 83$m251$,$m251$تختص محكمة الإفلاس بنظر جميع الدعاوى الناشئة عن التفليسة والدعاوى التى للتفليسة على الغير أو للغير عليها .
وتعتبر الدعوى ناشئة عن التفليسة على وجه الخصوص إذا كانت متعلقة بأموالها أو بإدارتها أو بموجوداتها أو كان الفصل فيها يقتضى تطبيق أحكام هذا القانون .$m251$,'22e37c7507caaaaa2ade7a502585b1d8'),
(84,0,$m251$المادة 84$m251$,$m251$تحدد المحكمة فى حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع ، وتعين أمينا للتفليسة وتختار أحد قضاة المحكمة ليكون قاضيا للتفليسة ، وتأمر بوضع الأختام على محل تجارة المدين لحين الانتهاء من الجرد .
ويرسل قلم كتاب المحكمة إلى النيابة العامة ملخصا من حكم شهر الإفلاس فور صدوره .$m251$,'c2e3d8feb7ffb722dc93b162f41ed06c'),
(85,0,$m251$المادة 85$m251$,$m251$تستعين المحكمة فى تعيين تاريخ التوقف عن الدفع بكل فعل أو قول أو تصرف يصدر من المدين ويكشف عن اضطراب أعماله أو سعيه إلى الاستمرار فى نشاطه التجارى بوسائل غير مشروعة أو ضارة بدائنيه ، ويدخل فى ذلك على وجه الخصوص شروع المدين فى الهرب أو الانتحار ، أو إخفاء أمواله أو بيعها بخسارة أو عقد قروض بشروط باهظة أو الدخول فى مضاربات طائشة .
وإذا لم يعين فى حكم شهر الإفلاس التاريخ الذى توقف فيه المدين عن الدفع اعتبر تاريخ صدور حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع .
وإذا صدر حكم شهر الإفلاس بعد وفاة المدين أو بعد اعتزاله التجارة ولم يعين فيه تاريخ التوقف عن الدفع اعتبر تاريخ الوفاة أو اعتزال التجارة تاريخا مؤقتا للتوقف عن الدفع .$m251$,'9466a377fbe6a595b7edd1cea3765198'),
(86,0,$m251$المادة 86$m251$,$m251$يجوز للمحكمة من تلقاء ذاتها ، أو بناء على طلب النيابة العامة أو المدين أو أحد الدائنين أو أمين التفليسة أو غيرهم من ذوى المصلحة ، تعديل التاريخ المؤقت للتوقف عن الدفع وذلك حتى تاريخ إيداع قائمة الديون المحققة قلم كتاب المحكمة ، وبعد انقضاء هذا الميعاد يصير التاريخ المعين للتوقف عن الدفع نهائيا .
وفى جميع الأحوال لا يجوز إرجاع تاريخ التوقف عن الدفع إلى أكثر من سنتين سابقتين على تاريخ صدور الحكم بشهر الإفلاس .$m251$,'9bdcf26fccdf337c611861373724cc5f'),
(87,0,$m251$المادة 87$m251$,$m251$يقوم قلم كتاب المحكمة التى أصدرت الحكم بشهر الإفلاس بإخطار أمين التفليسة فور صدور الحكم بكتاب مسجل مصحوبا بعلم الوصول لمباشرة أعمال التفليسة .
وعلى أمين التفليسة شهر الحكم وكذلك الحكم بتعديل تاريخ التوقف عن الدفع فى السجل التجارى .
ويتولى أمين التفليسة نشر ملخص الحكم فى صحيفة يومية تعينها المحكمة فى حكم شهر الإفلاس ، ويجب أن يتم النشر خلال عشرة أيام من تاريخ إخطاره بالحكم ، ويشتمل الملخص المذكور فيما يتعلق بحكم شهر الإفلاس على اسم المفلس وموطنه ورقم قيده فى السجل التجارى والمحكمة التى أصدرت الحكم وتاريخ صدوره والتاريخ المؤقت للتوقف عن الدفع واسم قاضى التفليسة واسم أمينها وعنوانه ، كما يتضمن النشر دعوة الدائنين لتقديم ديونهم فى التفليسة ، وفى حالة تعديل تاريخ التوقف عن الدفع يشتمل النشر فضلا عن البيانات المذكورة على التاريخ الجديد الذى عينته المحكمة .
وعلى أمين التفليسة ، خلال خمسة عشر يوما من تاريخ إخطاره بحكم شهر الإفلاس ، أن يخطر به البنك المركزى المصرى لإخطار البنوك العاملة فى مصر ، والهيئة العامة للرقابة المالية والبورصة المصرية وشركة مصر للمقاصة والتأشير بملخصه باسم جماعة الدائنين فى كل مكتب للشهر العقارى يوجد فى دائرته عقار للمفلس ، ولا يترتب على هذا التأشير أى حق آخر لجماعة الدائنين ، والتأشير بالحكم بسجل الضمانات المنقولة .$m251$,'ae069b138bedcf0a2eb3b3e61e5a32ca'),
(88,0,$m251$المادة 88$m251$,$m251$يجوز لكل ذى مصلحة من غير الخصوم أن يعترض على حكم شهر الإفلاس أمام المحكمة التى أصدرته خلال ثلاثين يوما من تاريخ نشره فى الصحف ، ما لم يكن قد طعن عليه بالاستئناف فيرفع الاعتراض إلى المحكمة التى تنظر الاستئناف .
ويسرى على ميعاد استئناف الحكم الصادر فى دعوى شهر الإفلاس وغيره من الأحكام الصادرة فى الدعاوى الناشئة عن التفليسة وطريقة رفعها أحكام قانون المرافعات المدنية والتجارية .$m251$,'6ea70aad7de92a47226d461419c706c5'),
(89,0,$m251$المادة 89$m251$,$m251$تكون الأحكام الصادرة فى دعاوى الإفلاس واجبة النفاذ المعجل بلا كفالة بمسودتها ما لم ينص على غير ذلك .$m251$,'bfa08bd9240609c1b87d3bb24cd9f798'),
(90,0,$m251$المادة 90$m251$,$m251$لا يجوز الطعن بأى طريق فى :
(أ) الأحكام أو القرارات الخاصة بتعيين أو استبدال قاضى التفليسة أو أمينها أو مراقبها .
(ب) الأحكام الصادرة فى الطعن فى قرارات قاضى التفليسة .
(ج) الأحكام الصادرة بوقف إجراءات التفليسة إلى حين الفصل فى الطعن فى قرار قاضى التفليسة بشأن قبول الديون أو رفضها
(د) الأحكام الصادرة بشان قبول الديون المتنازع فيها مؤقتا .$m251$,'4afa2f6422da3cd14972590688b0991c'),
(91,0,$m251$المادة 91$m251$,$m251$إذا أوفى المدين جميع ما هو مستحق عليه من ديون تجارية قبل أن يحوز حكم شهر الإفلاس قوة الشىء المقضى به وجب على المحكمة أن تقضى بإلغاء حكم شهر الإفلاس على أن يتحمل المدين كافة مصاريف الدعوى .$m251$,'2117b27be3d7d75efa89b9d96676f97f'),
(92,0,$m251$المادة 92$m251$,$m251$إذا لم توجد فى التفليسة ، وقت شهرها ، نقود حاضرة لمواجهة شهر حكم الإفلاس ونشره أو وضع الأختام على أموال المفلس أو رفعها وجب دفع هذه المصاريف من مبلغ الأمانة التى أودعها طالب شهر الإفلاس ويسترد طالب شهر الإفلاس المبالغ التى دفعها بالامتياز على جميع الدائنين من أول نقود تدخل التفليسة ، كما يجوز لقاضى التفليسة أن يأمر بالمبادرة ببيع بعض أموال التفليسة لمواجهة هذه المصاريف .$m251$,'1ddc9eedb02fb2b1a97e1e97d9125b48'),
(93,0,$m251$المادة 93$m251$,$m251$إذا طلب المدين شهر إفلاسه وقضت المحكمة برفض الطلب جاز لها أن تحكم عليه بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه إذا تبين لها أنه تعمد اصطناع الإفلاس .
وإذا طلب أحد الدائنين شهر الإفلاس وقضت المحكمة برفض الطلب يحكم على الدائن بالغرامة المنصوص عليها فى الفقرة السابقة وينشر الحكم على نفقته فى الصحف التى تعينها ، إذا تبين لها أنه تعمد الإساءة إلى سمعة المدين التجارية ، وذلك مع عدم الإخلال بحق المدين فى طلب التعويض .$m251$,'5bb35b083268db40f6148eb51b68f6ee'),
(94,0,$m251$المادة 94$m251$,$m251$تعين المحكمة فى حكم الإفلاس من جدول خبراء إدارة الإفلاس ممثلا قانونيا لإدارة التفليسة يسمى (أمين التفليسة) .
ويجوز فى كل وقت لقاضى التفليسة من تلقاء نفسه أو بناء على طلب المفلس أو المراقب الأمر بإضافة أمين أو أكثر بشرط ألا يزيد عددهم على ثلاثة .
ويصدر بتنظيم مهنة أمناء التفليسات قرار من الوزير المختص .$m251$,'1255c3b1b1cd7bc15843cfcd31ad14ca'),
(95,0,$m251$المادة 95$m251$,$m251$لا يجوز أن يعين أمينا للتفليسة من كان زوجا للمفلس أو قريبا له حتى الدرجة الرابعة أو من كان خلال السنتين السابقتين على شهر الإفلاس شريكا له أو مستخدما عنده أو محاسبا له أو وكيلا عنه ، وكذلك من سبق الحكم عليه بالإدانة فى جناية أو فى جنحة ماسة بالشرف والأمانة .$m251$,'df8391f4fbb30942632ce09700f04fa5'),
(96,0,$m251$المادة 96$m251$,$m251$يقوم أمين التفليسة بإدارة أموال التفليسة والمحافظة عليها وينوب عن المفلس فى جميع الدعاوى والأعمال التى تقتضيها هذه الإدارة .
ويدون أمين التفليسة ، يوما بيوم ، جميع الأعمال المتعلقة بإدارة التفليسة فى دفتر خاص ترقم صفحاته ويضع عليها قاضى التفليسة توقيعه أو ختمه ويؤشر فى نهاية الدفتر بما يفيد انتهاءه .
ويجوز للمحكمة ولقاضى التفليسة وللمراقب الاطلاع على هذا الدفتر فى كل وقت ، وللمفلس أيضا الاطلاع عليه بإذن من قاضى التفليسة .$m251$,'d39d32927bacc47f28788f81fccf69da'),
(97,0,$m251$المادة 97$m251$,$m251$إذا تعدد أمناء التفليسة وجب أن يعملوا مجتمعين ويسألون بالتضامن عن إدارتهم .
ويجوز لقاضى التفليسة أن يقسم العمل بينهم أو أن يعهد إلى أحدهم بعمل معين ، وفى هذه الحالة لا يكون أمين التفليسة مسئولا إلا عن العمل الذى يكلف به .
ويجوز لأمناء التفليسة أن ينيبوا بعضهم البعض فى القيام بالأعمال المعهود بها إليهم ، ولا يجوز لهم إنابة الغير إلا بإذن من قاضى التفليسة ، وفى هذه الحالة يكون أمين التفليسة ونائبه مسئولين بالتضامن عن الأعمال المذكورة .$m251$,'1dc09008805d2465ed9f4e626cad527c'),
(98,0,$m251$المادة 98$m251$,$m251$يجوز للمفلس وللمراقب الاعتراض لدى قاضى التفليسة على أعمال أمينها قبل إتمامها ، ويترتب على الاعتراض وقف إجراء العمل . ويجب أن يفصل قاضى التفليسة فى الاعتراض خلال سبعة أيام من تاريخ تقديمه ، ويكون قرار قاضى التفليسة واجب النفاذ فورا .$m251$,'add09d39a4b69eb028086cb6321c381b'),
(99,0,$m251$المادة 99$m251$,$m251$يجوز للمحكمة ، من تلقاء ذاتها أو بناء على طلب قاضى التفليسة أو المفلس أو المراقب ، أن تحكم بعزل أمين التفليسة وتعيين غيره أو بإنقاص عدد الأمناء إذا تعددوا .$m251$,'499dc685b5d88a8883549ddffb03be3e'),
(100,0,$m251$المادة 100$m251$,$m251$تقدر أتعاب ومصاريف أمين التفليسة بقرار من قاضى التفليسة بعد أن يقدم الأمين تقريرا عن إدارته .
ويجوز لقاضى التفليسة أن يأمر بصرف مبالغ لأمين التفليسة قبل تقديم التقرير المذكور فى الفقرة السابقة خصما من أتعابه .
ويجوز لكل ذى شأن الطعن أمام المحكمة فى قرار قاضى التفليسة الخاص بتقدير أتعاب أمين التفليسة ومصاريفه .$m251$,'b3891e3fcc1d35349ed52a7f794947e4'),
(101,0,$m251$المادة 101$m251$,$m251$يتولى قاضى التفليسة بالإضافة إلى السلطات المقررة له ما يأتى :
1 - مراقبة إدارة التفليسة وملاحظة سير إجراءاتها والأمر باتخاذ التدابير اللازمة للمحافظة على أموالها ، بما فى ذلك تكليف أمين التفليسة بإقامة دعاوى أو مباشرة إجراءات معينة .
2 - دعوة الدائنين إلى الاجتماع فى الأحوال المبينة فى القانون ويتولى رئاسة الاجتماعات .
3 - يقدم للمحكمة كل ثلاثة أشهر تقريرا عن حالة التفليسة ، كما يقدم لها تقريرا عن كل نزاع يتعلق بالتفليسة ويكون من اختصاصها الفصل فيه .
4 - استدعاء المفلس أو ورثته أو وكلائه أو مستخدميه أو أى شخص آخر لسماع أقوالهم فى شئون التفليسة .$m251$,'1f4cd436f741a946b6378d2131cc3966'),
(102,0,$m251$المادة 102$m251$,$m251$تودع القرارات التى يصدرها قاضى التفليسة قلم كتاب المحكمة فى اليوم التالى لصدورها ، وللقاضى أن يأمر قلم الكتاب بإخطارها لكل ذى مصلحة ، ويكون الإخطار بكتاب مسجل مصحوبا بعلم الوصول ، إلا إذا أمر قاضى التفليسة بإخطارها بطريقة أخرى .$m251$,'3c4efc7ee5162a69dda79bd253c74eb9'),
(103,0,$m251$المادة 103$m251$,$m251$لا يجوز الطعن فى القرارات التى يصدرها قاضى التفليسة ما لم ينص القانون على غير ذلك أو كان القرار مما يجاوز اختصاصه ، ويقدم الطعن خلال عشرة أيام من تاريخ إيداع القرار . بصحيفة تودع قلم كتاب المحكمة وتعلن لذوى الشأن وتنظره المحكمة فى أول جلسة ، على ألا يشترك قاضى التفليسة المطعون فى قراره فى نظر هذا الطعن ، ويوقف الطعن تنفيذ القرار حتى تفصل المحكمة فى أمره ما لم تر المحكمة الأمر باستمرار تنفيذه .
وإذا رفضت المحكمة الطعن جاز لها أن تحكم على الطاعن بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه ، إذا تبين لها أنه تعمد تعطيل تنفيذ قرار قاضى التفليسة .$m251$,'536afd302b25eada428ccb4699c81bd2'),
(104,0,$m251$المادة 104$m251$,$m251$للمحكمة فى كل وقت ، أن تأمر باستبدال قاضى التفليسة بغيره من قضاة المحكمة ، أو تندب غيره فى حالة غيابه المؤقت .$m251$,'32deac252ade1c80c5eae8c70e15c820'),
(105,0,$m251$المادة 105$m251$,$m251$يجوز لقاضى التفليسة تعيين مراقب أو أكثر من بين الدائنين الذين يرشحون أنفسهم لذلك .
ويجوز للمفلس ولكل دائن الاعتراض على قرار قاضى التفليسة الخاص بتعيين المراقب دون أن يترتب على الاعتراض وقف تنفيذ القرار ، ويقدم الاعتراض إلى قاضى التفليسة نفسه ، ويجب أن يفصل فيه على وجه السرعة .$m251$,'db584ecdef9289fc35f50972b9333a06'),
(106,0,$m251$المادة 106$m251$,$m251$لا يجوز أن يكون المراقب أو النائب عن الشخص الاعتبارى المعين مراقبا ، زوجا للمفلس أو قريبا له حتى الدرجة الرابعة .$m251$,'efa9ed923f9cef2b400cea5d91b15f07'),
(107,0,$m251$المادة 107$m251$,$m251$يقوم المراقب ، بالإضافة إلى السلطات المقررة له بنصوص خاصة ، بفحص الميزانية والتقرير المقدمين من المدين وغير ذلك من المهام التى يكلفه بها قاضى التفليسة فى شأن الرقابة على أعمال أمينها ، ومعاونة قاضى التفليسة فى ذلك .
وللمراقب أن يطلب من أمين التفليسة إيضاحات عن سير إجراءاتها وإيراداتها ومصروفاتها وحالة الدعاوى المتعلقة بها .$m251$,'22782079c5673a8934f90744fc146786'),
(108,0,$m251$المادة 108$m251$,$m251$لا يتقاضى المراقب أجرا نظير عمله ، ومع ذلك يجوز للمحكمة أن تقرر له مكافأة إجمالية عن عمله إذا بذل جهدا غير عادى وكانت الحالة المالية للتفليسة تسمح بذلك .
ويجوز عزل المراقب بقرار من قاضى التفليسة .
ولا يسأل المراقب إلا عن خطئه الجسيم .$m251$,'295aa8dfd8485d0bf8378e8e45a5dc98'),
(109,0,$m251$المادة 109$m251$,$m251$يجوز للمحكمة بناء على طلب قاضى التفليسة أو النيابة العامة أو أمين التفليسة أو المراقب أن تأمر عند الاقتضاء بمنع المفلس من مغادرة البلاد لمدة لا تجاوز ستة أشهر قابلة للتجديد إذا قام بعمل من شأنه الإضرار بحقوق الدائنين . وللمفلس أن يتظلم من هذا الأمر أمام المحكمة المختصة دون أن يترتب على التظلم وقف تنفيذه .
وللمحكمة أن تقرر فى كل وقت إلغاء أمر المنع من مغادرة البلاد ،$m251$,'e0b69ffef5a76a0c63f2ec514cda5f84'),
(110,0,$m251$المادة 110$m251$,$m251$لا يجوز للمفلس أن يتغيب عن موطنه دون أن يخطر أمين التفليسة كتابة بمحل وجوده ، ولا يجوز له أن يغير موطنه إلا بإذن من قاضى التفليسة .$m251$,'ba274afb61db07db35cc35a8789a88fb'),
(111,0,$m251$المادة 111$m251$,$m251$مع عدم الإخلال بأحكام القانون رقم 45 لسنة 2014 بإصدار قانون بتنظيم مباشرة الحقوق السياسية ، والقانون رقم 46 لسنة 2014 بإصدار قانون مجلس النواب ، يحرم مؤقتا من مباشرة الحقوق السياسية ومن العضوية فى المجلس النيابى أو المجالس المحلية ، كل من صدر ضده حكم نهائى لارتكابه إحدى جرائم التفالس بالتدليس أو التقصير ، ويكون الحرمان لمدة ست سنوات من تاريخ تنفيذ العقوبة ، ولا يسرى ذلك الحرمان إذا رد إليه اعتباره أو أوقف تنفيذ العقوبة بحكم قضائى .
ولا يجوز لمن أشهر إفلاسه أن يكون عضوا بالغرف التجارية أو الصناعية أو النقابات أو الاتحادات المهنية أو الرياضية أو مديرا أو عضوا بمجلس إدارة أى شركة أو الاشتغال بأعمال البنوك أو الوكالة التجارية أو التصدير والاستيراد أو السمسرة فى بيع أو شراء الأوراق المالية أو البيع بالمزاد العلنى . كل ذلك ما لم يرد إليه اعتباره .
ولا يجوز لمن أشهر إفلاسه أن ينوب عن غيره فى إدارة أمواله أو التصرف فيها . ومع ذلك يجوز للمحكمة المختصة أن تقضى بناء على طلب من قاضى التفليسة بحلول أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال محل المفلس فى تنفيذ هذه الإنابة بصفة دائمة أو مؤقتة مع التأشير بذلك القضاء على هامش التوكيل الصادر للمفلس من الغير ويسرى ذلك القضاء من تاريخ التأشير ، وللمحكمة أن تأذن للمفلس فى إدارة أموال أولاده القصر إذا لم يترتب على ذلك ضرر لهم .$m251$,'93833b13d5bc012d4fc15f1e08769d00'),
(112,0,$m251$المادة 112$m251$,$m251$تغل يد المفلس بمجرد صدور حكم شهر الإفلاس عن إدارة أمواله والتصرف فيها ، وتعتبر التصرفات التى يجريها المفلس فى يوم صدور حكم شهر الإفلاس حاصلة بعد صدوره .
وإذا كان التصرف مما لا يحتج به على الغير إلا بالقيد أو التسجيل أو غير ذلك من الإجراءات فلا يسرى على جماعة الدائنين إلا إذا كان التصرف ثابت التاريخ قبل تاريخ التوقف عن الدفع .
ولا يحول غل يد المفلس عن إدارة أمواله والتصرف فيها دون قيامه بالإجراءات اللازمة للمحافظة على حقوقه .$m251$,'08c69d0fac3d754f70f3dad1d39bd69b'),
(113,0,$m251$المادة 113$m251$,$m251$لا يجوز للمفلس بعد صدور حكم شهر الإفلاس الوفاء بما عليه من ديون أو استيفاء ما له من حقوق .
ومع ذلك إذا كان المفلس حاملا لورقة تجارية جاز الوفاء له بقيمتها عند حلول معياد استحقاقها إلا إذا عارض أمين التفليسة فى هذا الوفاء طبقا للمادة (431) من قانون التجارة رقم 17 لسنة 1999 ، على أن يتم إيداع قيمة الورقة التجارية حساب التفليسة .$m251$,'918dc66286eca2fedc48da61645325e3'),
(114,0,$m251$المادة 114$m251$,$m251$لا تقع المقاصة بعد صدور حكم شهر الإفلاس بين ما للمفلس من حقوق وما عليه من التزامات إلا إذا وجد ارتباط بينهما ، ويوجد الارتباط على وجه الخصوص إذا نشأت الحقوق والالتزامات عن سبب واحد أو شملها حساب جار .$m251$,'2719270a169625710a77140ec307df76'),
(115,0,$m251$المادة 115$m251$,$m251$يشمل غل اليد جميع الأموال التى تكون ملكا للمفلس فى يوم صدور حكم شهر الإفلاس والأموال التى تئول إليه ملكيتها وهو فى حالة إفلاس .
ومع ذلك لا يشمل غل اليد ما يأتى :
(أ) الأموال التى لا يجوز الحجز عليها قانونا والإعانة التى تقرر للمفلس .
(ب) الأموال المملوكة لغير المفلس .
(ج) الحقوق المتصلة بشخص المفلس أو بأحواله الشخصية .
(د) التعويضات التى تستحق للمستفيد فى عقد تأمين صحيح أبرمه المفلس قبل صدور حكم شهر الإفلاس ومع ذلك يلتزم المستفيد بأن يرد إلى التفليسة جميع أقساط التأمين التى دفعها المفلس ابتداء من التاريخ الذى عينته المحكمة للتوقف عن الدفع ما لم ينص القانون على غير ذلك .$m251$,'aa0d5bddb10ccfa02fca1affb920734f'),
(116,0,$m251$المادة 116$m251$,$m251$إذا آلت إلى المفلس تركة فلا يكون لدائنيه حق على أموالها إلا بعد أن يستوفى دائنو المورث حقوقهم من هذه الأموال .
ولا يكون لدائنى المورث أى حق على أموال التفليسة .$m251$,'1f5ce27900d7bd5c22510eb9cf20b3eb'),
(117,0,$m251$المادة 117$m251$,$m251$لا يجوز بعد صدور حكم شهر الإفلاس رفع دعوى من المفلس أو عليه أو السير فيها مع استثناء ما يأتى :
(أ) الدعاوى المتعلقة بالأموال والتصرفات التى لا يشملها غل اليد .
(ب) الدعاوى المتعلقة بأعمال التفليسة التى يجيز القانون للمفلس القيام بها .
(ج) الدعاوى الجنائية .
ويجوز للمحكمة أن تأذن بإدخال المفلس فى الدعاوى المتعلقة بالتفليسة ، كما يجوز لها أن تأذن بإدخال الدائن فى هذه الدعاوى إذا كانت له مصلحة خاصة فيها .
وإذا رفع المفلس أو رفعت عليه دعوى جنائية أو دعوى متعلقة بشخصه أو بأحواله الشخصية وجب إدخال أمين التفليسة فيها إذا اشتملت على طلبات مالية .$m251$,'0bff4501a3ef1930c96af51ccde06fc3'),
(118,0,$m251$المادة 118$m251$,$m251$استثناء من حكم المادة (121) من هذا القانون ، إذا حكم على المفلس بعد شهر إفلاسه بالتعويض عن ضرر أحدثه للغير قبل تقديم طلب شهر الإفلاس جاز للمحكوم له الدخول فى التفليسة بالتعويض المقضى به ما لم يثبت تواطؤه مع المفلس .$m251$,'a656e3c0ddc9b1bbff2096c7abde5aff'),
(119,0,$m251$المادة 119$m251$,$m251$يجوز لقاضى التفليسة بعد سماع أقوال أمينها أن يقرر إعانة للمفلس تصرف من أموال التفليسة بناء على طلبه أو طلب من يعولهم .
ولمن طلب الإعانة ولأمين التفليسة التظلم من تقديرها أمام قاضى التفليسة دون أن يترتب على ذلك وقف صرف الإعانة .
ويجوز فى كل وقت لقاضى التفليسة من تلقاء نفسه أو بناء على طلب أمين التفليسة أن يعدل مقدار الإعانة أو أن يأمر بإلغائها ، ويجوز التظلم من هذا القرار أمام قاضى التفليسة نفسه .
ويوقف صرف الإعانة متى حاز حكم التصديق على الصلح قوة الشىء المقضى ، وإذا لم يقع الصلح يوقف صرف الإعانة بمجرد قيام حالة الاتحاد .$m251$,'7fd29e648973035073a38cf5f1a75939'),
(120,0,$m251$المادة 120$m251$,$m251$مع مراعاة حكم المادة (111) من هذا القانون يجوز للمفلس بعد إذن قاضى التفليسة ، أن يمارس تجارة جديدة بغير أموال التفليسة ويكون للدائنين الذين تنشأ ديونهم بمناسبة هذه التجارة الأولوية فى استيفاء حقوقهم من أموالها .$m251$,'49c96448944dbf644dae02ab684d3445'),
(121,0,$m251$المادة 121$m251$,$m251$لا يجوز التمسك فى مواجهة جماعة الدائنين بالديون المقضى بها بموجب أحكام صدرت بعد القضاء بشهر الإفلاس ، مع مراعاة تطبيق نص المادة (118) من هذا القانون ، كما لا يجوز التمسك فى مواجهتهم بالتصرفات التالية إذا قام بها المدين بعد تاريخ التوقف عن الدفع ، وقبل الحكم بشهر الإفلاس :
(أ) منح التبرعات أيا كان نوعها ما عدا الهدايا الصغيرة التى يجرى عليها العرف .
(ب) وفاء الديون قبل حلول الأجل أيا كانت كيفية الوفاء ، ويعتبر إنشاء مقابل وفاء ورقة تجارية لم يحل ميعاد استحقاقها فى حكم الوفاء قبل حلول الأجل .
(ج) وفاء الديون الحالة بغير الشىء المتفق عليه ، ويعتبر الوفاء بطريق الأوراق التجارية أو النقل المصرفى فى حكم الوفاء بالنقود .
(د) كل رهن أو تأمين اتفاقى آخر وكذلك كل اختصاص يتقرر على أموال المدين ضمانا لدين سابق على التأمين .$m251$,'9ef92c930c54080763bb3af6d401e196'),
(122,0,$m251$المادة 122$m251$,$m251$كل ما أجراه المفلس من تصرفات غير ما ذكر فى المادة (121) من هذا القانون وخلال الفترة المشار إليها فيها يجوز الحكم بعدم نفاذه فى مواجهة جماعة الدائنين إذا كان التصرف ضارا بهم وكان المتصرف إليه يعلم وقت وقوع التصرف بتوقف المفلس عن الدفع .$m251$,'3bc9e12194e8caacf771b6abff2205c3'),
(123,0,$m251$المادة 123$m251$,$m251$إذا دفعت قيمة ورقة تجارية بعد تاريخ التوقف عن الدفع وقبل الحكم بشهر الإفلاس فلا يجوز أن يسترد من الحامل ما دفع له ، وإنما يلزم الساحب أو من سحبت الورقة التجارية لحسابه برد القيمة المدفوعة إذا كان يعلم وقت إنشاء الورقة التجارية بتوقف المفلس عن الدفع ، ويقع الالتزام بالرد فى حالة السند لأمر على المظهر الأول إذا كان يعلم وقت حصوله على السند بتوقف المفلس عن الدفع .$m251$,'336862169d95c1e3f486c5701dce3256'),
(124,0,$m251$المادة 124$m251$,$m251$يجوز الحكم بعدم نفاذ حقوق الرهن أو الامتياز أو الاختصاص المقررة على أموال المدين فى مواجهة جماعة الدائنين إذا قيدت بعد تاريخ التوقف عن الدفع وبعد انقضاء ثلاثين يوما من تاريخ تقرير الرهن أو الامتياز أو الاختصاص .
ويأخذ الدائن صاحب الرهن أو الاختصاص التالى للرهن أو الاختصاص الذى حكم بعدم نفاذه فى مواجهة جماعة الدائنين مرتبة هذا التأمين ، ومع ذلك لا يعطى الدائن المذكور من الثمن الناتج من بيع المال المقرر عليه التأمين إلا ما كان يحصل عليه بغرض نفاذ الرهن أو الاختصاص السابق ويئول الفرق إلى جماعة الدائنين .$m251$,'404ee0cffaeb3b49e8fc9a9ba6e60ba9'),
(125,0,$m251$المادة 125$m251$,$m251$يجوز لأمين التفليسة وحده أو بناء على طلب قاضى التفليسة أن يطلب عدم نفاذ تصرفات المدين فى حق جماعة الدائنين إذا وقع التصرف قبل صدور حكم شهر الإفلاس وذلك وفقا لأحكام القانون المدنى ، ويسرى الحكم الصادر بعدم نفاذ التصرف فى حق جميع الدائنين سواء نشأت حقوقهم قبل حصول التصرف أو بعد حصوله .$m251$,'f9255eb29861fcd4288ead9b5e2dda0e'),
(126,0,$m251$المادة 126$m251$,$m251$إذا حكم بعدم نفاذ أى تصرف فى حق جماعة الدائنين التزم المتصرف إليه بأن يرد إلى التفليسة ما حصل عليه من المفلس بمقتضى هذا التصرف أو قيمة الشىء وقت قبضه ، كما يلزم بدفع عوائد ما قبضه أو ثماره من تاريخ القبض .
ويكون للمتصرف إليه الحق فى استرداد العوض الذى قدمه للمفلس إذا وجد هذا العوض بعينه فى التفليسة ، فإذا لم يوجد كان من حق المتصرف إليه أن يطالب جماعة الدائنين بالمنفعة التى عادت عليهم من التصرف وأن يشترك فى التفليسة بوصفه دائنا عاديا بما يزيد على قيمة هذه المنفعة .$m251$,'242964c077443dd51f6e349446ad5a7b'),
(127,0,$m251$المادة 127$m251$,$m251$تسقط الدعاوى الناشئة عن تطبيق الأحكام المنصوص عليها فى المواد من ( 121 ) إلى ( 125 ) من هذا القانون بمضى سنتين من تاريخ صدور الحكم بشهر الإفلاس .$m251$,'b257d883228272f2efb2e6f3d973354f'),
(128,0,$m251$المادة 128$m251$,$m251$لا يجوز للدائنين العاديين أو الدائنين أصحاب حقوق الامتياز العامة بعد صدور حكم شهر الإفلاس إقامة دعاوى فردية على التفليسة أو اتخاذ أى إجراءات قضائية أخرى ضدها .
وكذلك يترتب على صدور حكم شهر الإفلاس وقف الدعاوى الفردية المقامة من الدائنين المذكورين فى الفقرة السابقة ووقف إجراءات التنفيذ التى بدأها هؤلاء الدائنون قبل صدور حكم شهر الإفلاس ، ومع ذلك إذا تحدد يوم لبيع عقار المفلس جاز الاستمرار فى إجراءات التنفيذ بإذن من قاضى التفليسة .
وأما الدائنون المرتهنون وأصحاب حقوق الامتياز الخاصة والحاصلون على اختصاص على أموال المدين فيجوز لهم إقامة الدعاوى الفردية أو الاستمرار فيها فى مواجهة أمين التفليسة . كما يجوز لهم التنفيذ أو الاستمرار فيه على الأموال التى تقع عليها تأميناتهم بشرط إخطار قاضى التفليسة بالتنفيذ ، ويكون التنفيذ فى مواجهة أمين التفليسة .$m251$,'961644cd38df62700a1322d12f3a4549'),
(129,0,$m251$المادة 129$m251$,$m251$الحكم بشهر الإفلاس يسقط آجال جميع الديون النقدية التى على المفلس سواء أكانت عادية أم مضمونة بامتياز عام أو خاص .$m251$,'c434b0f2f7418360766a4084a2e9689f'),
(130,0,$m251$المادة 130$m251$,$m251$الحكم بشهر الإفلاس يوقف سريان عوائد الديون العادية بالنسبة إلى جماعة الدائنين فقط ولا تجوز المطالبة بعوائد الديون المضمونة برهن أو امتياز أو اختصاص إلا من المبالغ الناتجة من بيع الأموال التى يقع عليها التأمين ، ويستنزل أصل الدين أولا ثم العوائد المستحقة قبل صدور الحكم بشهر الإفلاس ثم العوائد المستحقة بعد صدوره .$m251$,'7f78826084ca5bf85bc3a1a4838f2520'),
(131,0,$m251$المادة 131$m251$,$m251$لقاضى التفليسة أن يستنزل من الدين الآجل الذى لم يشترط فيه عائد مبلغا يعادل العائد المستحق عن المدة من تاريخ الحكم بشهر الإفلاس إلى تاريخ استحقاق الدين .$m251$,'300eedea781e80ef7ce0e475c93ca2dc'),
(132,0,$m251$المادة 132$m251$,$m251$يجوز الاشتراك فى التفليسة بالديون المعلقة على شرط فاسخ ، مع تقديم كفيل ، أما الديون المعلقة على شرط واقف فيجنب نصيبها فى التوزيعات إلى أن تتبين نتيجة الشرط .$m251$,'047affc45ea5378c8d0a792cd5593f38'),
(133,0,$m251$المادة 133$m251$,$m251$إذا وجد جملة ملتزمين بدين واحد شهر إفلاس أحدهم فلا يترتب على هذا الإفلاس أثر بالنسبة إلى الملتزمين الآخرين ما لم ينص القانون على غير ذلك .
وإذا تم الصلح مع الملتزم الذى أفلس فلا تسرى شروطه على الملتزمين الآخرين .$m251$,'1276206373459b162d11071224b91430'),
(134,0,$m251$المادة 134$m251$,$m251$إذا استوفى الدائن من أحد الملتزمين بدين واحد جزءا من الدين ثم أفلس باقى الملتزمين أو أفلس أحدهم فلا يجوز للدائن أن يشترك فى التفليسات إلا بالباقى من دينه ويبقى محتفظا بحقه فى مطالبة الملتزم غير المفلس بهذا الباقى ، ويجوز لهذا الملتزم أن يشترك فى كل تفليسة بما وفاه عنها .$m251$,'33cac39135723161b9e3fdb8d7a6191b'),
(135,0,$m251$المادة 135$m251$,$m251$إذا أفلس جميع الملتزمين بدين واحد دفعة واحدة ، جاز للدائن أن يشترك فى كل تفليسة بكل دينه إلى أن يستوفيه بتمامه ، من أصل وعوائد ومصاريف .
ولا يجوز لتفليسة الرجوع على تفليسة أخرى بما أوفته عنها .
وإذا كان مجموع ما حصل عليه الدائن يزيد على دينه وتوابعه عادت الزيادة إلى تفليسة من يكون مكفولا من الآخرين بحسب ترتيب التزاماتهم بالدين ، فإذا لم يوجد هذا الترتيب عادت الزيادة إلى التفليسات التى دفعت أكثر من حصتها فى الدين .$m251$,'e2b2297235776aeb40161f234e60cf48'),
(136,0,$m251$المادة 136$m251$,$m251$لا تدرج أسماء دائنى المفلس الحائزين بوجه قانونى على رهن أو امتياز خاص على منقول أو عقار فى جماعة الدائنين إلا على سبيل التذكرة .$m251$,'6de1274267438d4c050c85791f3bb1d5'),
(137,0,$m251$المادة 137$m251$,$m251$يجوز لأمين التفليسة فى كل وقت وبعد الحصول على إذن من قاضى التفليسة ، دفع الدين المضمون برهن واسترداد الأشياء المرهونة لحساب جماعة الدائنين .$m251$,'413124fce459a944eb17646acf7602dc'),
(138,0,$m251$المادة 138$m251$,$m251$على أمين التفليسة بعد استئذان قاضى التفليسة أن يدفع خلال الأيام العشرة التالية لصدور الحكم بشهر الإفلاس مما يكون تحت يده من نقود التفليسة وبالرغم من وجود أى دين آخر ، الأجور والمرتبات والمبالغ المستحقة قبل صدور الحكم بشهر الإفلاس عن مدة ثلاثين يوما للعاملين لدى المفلس ، فإذا لم يكن لدى أمين التفليسة النقود اللازمة لوفاء هذه الديون وجب الوفاء من أول نقود تدخل التفليسة ولو وجدت ديون أخرى تسبقها فى مرتبة الامتياز .
ويكون للمبالغ المستحقة للطوائف المذكورة والزائدة على ما تقدم مرتبة الامتياز المقررة قانونا .$m251$,'a4c0771b46412b245bd2c68056e1f54a'),
(139,0,$m251$المادة 139$m251$,$m251$يكون للمؤجر فى حالة إنهاء إيجار العقار الذى يمارس فيه المفلس التجارة طبقا للمادة (143) من هذا القانون امتياز لضمان الأجرة المستحقة له عن السنة السابقة على صدور حكم شهر الإفلاس وعن السنة الجارية ، وإذا بيعت المنقولات الموجودة فى العين المؤجرة أو نقلت ظل المؤجر محتفظا بحقه فى الامتياز .$m251$,'9608c7e0cea0a9ecd9941ee6278ec4c0'),
(140,0,$m251$المادة 140$m251$,$m251$لا يشمل الامتياز المقرر للحكومة بسبب الضرائب على اختلاف أنواعها إلا دين الضريبة المستحقة على المفلس عن السنتين السابقتين على صدور الحكم بشهر الإفلاس ، وتدخل الضرائب الأخرى المستحقة فى التوزيعات بوصفها ديونا عادية .$m251$,'a7105ad5053ba5a71ed992dee838015a'),
(141,0,$m251$المادة 141$m251$,$m251$يجوز لقاضى التفليسة بناء على اقتراح أمينها أن يأمر عند الاقتضاء باستخدام أول نقود تدخل التفليسة فى الوفاء بحقوق الدائنين الذين لهم امتياز على منقولات المفلس بشرط أن تكون أسماؤهم قد وردت بالقائمة النهائية للديون غير المتنازع فيها المشار إليها فى الفقرة الأولى من المادة (171) من هذا القانون ، وإذا حصلت منازعة فى الامتياز فلا يجوز الوفاء إلا بعد الفصل فيها بحكم نهائى .$m251$,'e2a12715fd4e764e22cffd7010ea180d'),
(142,0,$m251$المادة 142$m251$,$m251$لا يترتب على الحكم بشهر الإفلاس فسخ العقود الملزمة للجانبين التى يكون المفلس طرفا فيها إلا إذا كانت قائمة على اعتبارات شخصية .
وإذا لم ينفذ أمين التفليسة العقد أو لم يستمر فى تنفيذه جاز للطرف الآخر أن يطلب الفسخ ، وكل قرار يتخذه أمين التفليسة بشأن العقد يجب أن يعرض على قاضى التفليسة ليأذن به ، ويجوز للطرف الآخر أن يعين لأمين التفليسة مهلة مناسبة لإيضاح موقفه من العقد .
وللمتعاقد الاشتراك فى التفليسة كدائن عادى بالتعويض المترتب على الفسخ إلا إذا نص على احتفاظ التعويض بالامتياز المقرر له قانونا .$m251$,'29aca5e65deb10c94650d2b996a14ae4'),
(143,0,$m251$المادة 143$m251$,$m251$إذا كان المفلس مستأجرا للعقار الذى يمارس فيه التجارة فلا يترتب على صدور الحكم بشهر الإفلاس إنهاء الإجارة أو حلول الأجرة عن المدة المتبقية لانقضائها ، وكل شرط على خلاف ذلك يعتبر كأن لم يكن .
وإذا كان المؤجر قد بدأ فى التنفيذ على المنقولات الموجودة فى العقار ولم يكن التنفيذ قد تم عند صدور الحكم بشهر الإفلاس وجب التنفيذ لمدة تسعين يوما من تاريخ هذا الحكم مع عدم الإخلال بحق المؤجر فى اتخاذ الإجراءات التحفظية وفى طلب إخلاء العقار وفقا للقواعد العامة . ويجوز لقاضى التفليسة أن يأمر باستمرار وقف التنفيذ لمدة ثلاثين يوما أخرى لمرة واحدة إذا رأى ضرورة لذلك وعلى أمين التفليسة إخطار مؤجر العقار خلال مدة وقف التنفيذ برغبته فى إنهاء الإجارة أو الاستمرار فيها .
وإذا قرر أمين التفليسة الاستمرار فى الإجارة وجب أن يدفع الأجرة المتأخرة وأن يقدم ضمانا كافيا للوفاء بالأجرة المستقبلة . ويجوز للمؤجر أن يطلب من قاضى التفليسة إنهاء الإجارة إذا كان الضمان غير كاف ، وذلك خلال خمسة عشر يوما من تاريخ إخطاره برغبة أمين التفليسة فى الاستمرار فى الإجارة .
ولأمين التفليسة بعد الحصول على إذن من قاضى التفليسة وبعد موافقة المؤجر تأجير العقار من الباطن أو التنازل عن الإيجار وفقا للأحكام المنظمة للعلاقة بين المالك والمستأجر .$m251$,'91128684e50a9c69e6cac72dc49b3194'),
(144,0,$m251$المادة 144$m251$,$m251$إذا أفلس رب العمل وكان عقد العمل غير محدد المدة جاز للعامل ولأمين التفليسة إنهاء العقد مع مراعاة الأحكام المنصوص عليها فى قوانين العمل . ولا يجوز للعامل فى هذه الحالة مطالبة التفليسة بالتعويض إلا إذا كان الإنهاء تعسفيا أو بغير مراعاة مواعيد الإخطار .
وإذا كان عقد العمل محدد المدة فلا يجوز إنهاؤه إلا إذا تقرر عدم الاستمرار فى التجارة ، ويجوز للعامل فى هذه الحالة مطالبة التفليسة بالتعويض .
ويكون للتعويض المستحق للعامل وفقا للفقرتين السابقتين الامتياز المقرر له قانونا .$m251$,'c4a61f1306a4156b5c83b9355e77dff7'),
(145,0,$m251$المادة 145$m251$,$m251$لكل شخص أن يسترد من التفليسة الأشياء التى تثبت له ملكيتها أو حق استردادها وقت شهر الإفلاس .
ويكون لأمين التفليسة ، بعد أخذ رأى المراقب والحصول على إذن من قاضى التفليسة رد الشىء إلى مالكه أو صاحب الحق فى استرداده ، وإذا رفض طلب الاسترداد جاز لطالبه عرض النزاع على المحكمة .$m251$,'567147b8e0f61723b0b70f1ff5433b59'),
(146,0,$m251$المادة 146$m251$,$m251$يجوز استرداد الأشياء الموجودة فى حيازة المفلس ، على سبيل الوديعة أو لأجل بيعها لحساب مالكها أو لأجل تسليمها إليه ، بشرط أن توجد فى التفليسة عينا . كما يجوز استرداد ثمن البضائع إذا لم يكن قد تم الوفاء به نقدا أو بورقة تجارية أو بطريق قيده فى حساب جار بين المفلس والمشترى .
وعلى المسترد أن يدفع لأمين التفليسة الحقوق المستحقة للمفلس .
وإذا كان المفلس قد أودع البضائع لدى الغير جاز استردادها منه .
وإذا اقترض المفلس برهن البضائع وكان الدائن المرتهن لا يعلم وقت إنشاء الرهن بعدم ملكية المفلس لها فلا يجوز استردادها إلا بعد وفاء الدين المضمون بالرهن .$m251$,'2fe6d9c46d08b7ed4a2f2c4cffd37d8b'),
(147,0,$m251$المادة 147$m251$,$m251$يجوز استرداد الأوراق التجارية وغيرها من الأوراق ذات القيمة ، المسلمة إلى المفلس لتحصيلها أو لتخصيصها لوفاء معين إذا وجدت عينا فى التفليسة ولم تكن قيمتها قد دفعت ، ولا يجوز استرداد أوراق النقد المودعة لدى المفلس إلا إذا أثبت طالب الاسترداد ذاتيتها .$m251$,'c3da5c8de996cd6d83c93d1ad87ed10b'),
(148,0,$m251$المادة 148$m251$,$m251$إذا فسخ عقد البيع بحكم أو بمقتضى شرط فى العقد قبل صدور الحكم بشهر إفلاس المشترى ، جاز للبائع استرداد البضائع كلها أو بعضها فى التفليسة بشرط أن توجد عينا .
ويجوز الاسترداد ولو وقع الفسخ بعد صدور حكم شهر الإفلاس بشرط أن تكون دعوى الاسترداد أو دعوى الفسخ قد رفعت قبل صدور هذا الحكم .$m251$,'6a4826259eba25cc7f2e654bf70c5ec3'),
(149,0,$m251$المادة 149$m251$,$m251$إذا أفلس المشترى قبل دفع الثمن وكانت البضائع لا تزال لدى البائع ، جاز له حبسها .
وإذا أفلس المشترى بعد إرسال البضائع إليه وقبل دخولها مخازنه أو مخزن وكيله المكلف ببيعها ، جاز للبائع استرداد حيازتها ، ومع ذلك لا يجوز الاسترداد إذا فقدت البضائع ذاتيتها ، أو تصرف فيها المفلس قبل وصولها ، بغير تدليس ، بموجب وثائق الملكية أو النقل .
وفى جميع الأحوال يجوز لأمين التفليسة ، بعد استئذان قاضى التفليسة أن يطلب تسليم البضائع بشرط أن يدفع للبائع الثمن المتفق عليه ، فإذا لم يطلب أمين التفليسة ذلك جاز للبائع أن يتمسك بحقه فى الفسخ وطلب التعويض والاشتراك به فى التفليسة .$m251$,'b19dac1a4603c79cde25527eb6f7fbf6'),
(150,0,$m251$المادة 150$m251$,$m251$مع عدم الإخلال بأحكام قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم (115) لسنة 2015 ، إذا أفلس المشترى قبل دفع الثمن وبعد دخول البضائع مخازنه أو مخازن وكيله المكلف ببيعها ، فلا يجوز للبائع أن يطلب فسخ البيع أو استرداد البضائع ، كما يسقط حقه فى الامتياز ، وكل شرط يكون من شأنه تمكين البائع من استرداد البضائع أو الاحتفاظ بامتيازه عليها لا يحتج به على جماعة الدائنين .$m251$,'d47ec979b71a3816a82a3c6bda1a57c3'),
(151,0,$m251$المادة 151$m251$,$m251$تتقادم دعاوى الاسترداد التى توجه إلى أمين التفليسة فى الحالات المذكورة فى المواد من (145) إلى (149) من هذا القانون بمضى سنة من تاريخ نشر حكم شهر الإفلاس .$m251$,'7d43901e661c3f65b37c6d0a20b1d8dc'),
(152,0,$m251$المادة 152$m251$,$m251$توضع الأختام على محال المفلس ومكاتبه وخزائنه ودفاتره وأوراقه ومنقولاته .
ويقوم قاضى التفليسة بوضع الأختام فور صدور الحكم بشهر الإفلاس ، وله أن يندب أحد موظفى المحكمة لذلك ، كما يقوم بإخطار رئيس كل محكمة يوجد فى دائرتها مال للمفلس ليأمر بندب من يقوم بوضع الأختام على هذا المال .
وإذا تبين لقاضى التفليسة إمكان جرد أموال المفلس فى يوم واحد جاز له أو لمن يندبه ، البدء فى الجرد فورا دون حاجة إلى وضع الأختام .
ويحرر محضر بوضع الأختام أو بالجرد يوقعه من قام بهذا الإجراء ، ويسلم المحضر لقاضى التفليسة .$m251$,'18d7b9d9eeda7317dcc4dec158112cf0'),
(153,0,$m251$المادة 153$m251$,$m251$لا يجوز وضع الأختام على الملابس والمنقولات الضرورية للمفلس ولمن يعولهم ، ويعين قاضى التفليسة هذه الأشياء وتسلم إلى المفلس بقائمة يوقعها كل من قاضى التفليسة والمفلس .$m251$,'dd78b11662aad51aed9db6294ac001ca'),
(154,0,$m251$المادة 154$m251$,$m251$يجوز لقاضى التفليسة أن يأمر ، من تلقاء نفسه أو بناء على طلب أمين التفليسة ، بعدم وضع الأختام أو برفعها عن الأشياء الآتية :
(أ) الدفاتر التجارية .
(ب) الأوراق التجارية وغيرها من الأوراق التى تستحق الوفاء فى ميعاد قريب أو التى تحتاج إلى إجراءات للمحافظة على الحقوق الثابتة فيها .
(ج) النقود اللازمة للصرف على الشئون العاجلة للتفليسة .
(د) الأشياء القابلة لتلف سريع أو لنقص عاجل فى القيمة أو التى تقتضى صيانتها مصاريف باهظة .
(هـ) الأشياء اللازمة لتشغيل المتجر إذا تقرر الاستمرار فى تشغيله .
وتجرد الأشياء المذكورة فى الفقرة السابقة بحضور قاضى التفليسة أو من يندبه لذلك ، وتسلم لأمين التفليسة بقائمة يوقعها .$m251$,'be2c9a0411131c9f1d45001af4ad22e4'),
(155,0,$m251$المادة 155$m251$,$m251$يأمر قاضى التفليسة ، بناء على طلب أمينها ، برفع الأختام للبدء فى جرد أموال المفلس .
ويجب أن يبدأ رفع الأختام والجرد خلال ثلاثين يوما من تاريخ صدور حكم شهر الإفلاس .$m251$,'0ca8148eed3f1cd7aa148404420cb3a4'),
(156,0,$m251$المادة 156$m251$,$m251$يحصل الجرد بحضور قاضى التفليسة أو من يندبه لذلك وأمين التفليسة وكاتب المحكمة ، ويجب أن يخطر به المفلس ويجوز له الحضور .
وتحرر قائمة جرد من نسختين يوقعهما قاضى التفليسة أو من ندبه لذلك وأمين التفليسة ، وكاتب المحكمة وتودع إحداهما قلم كتاب المحكمة ، وتبقى الأخرى لدى أمين التفليسة .
وتذكر فى القائمة الأموال التى لم توضع عليها الأختام أو التى رفعت عنها .
وتجوز الاستعانة بخبير فى إجراء الجرد وتقويم الأموال .$m251$,'517d835c3bb6914bcb1d8dc556959144'),
(157,0,$m251$المادة 157$m251$,$m251$إذا شهر الإفلاس بعد وفاة التاجر ولم تحرر قائمة جرد بمناسبة الوفاة ، أو إذا توفى التاجر بعد شهر إفلاسه وقبل البدء فى تحرير قائمة الجرد أو قبل إتمامها ، وجب تحرير القائمة فورا أو الاستمرار فى تحريرها بالكيفية المبينة فى المادة (156) من هذا القانون ، ويجب أن يخطر به الورثة ويجوز لهم الحضور .$m251$,'d0cd5172314d82e4b6e2cc62882424b5'),
(158,0,$m251$المادة 158$m251$,$m251$يتسلم أمين التفليسة ، بعد الجرد ، أموال المفلس ، ودفاتره وأوراقه ويوقع فى نهاية قائمة الجرد بما يفيد ذلك .$m251$,'fe49406e08559be5b7f159c570ee4ec4'),
(159,0,$m251$المادة 159$m251$,$m251$لا يجوز تسليم الدفاتر التجارية إلى أمين التفليسة إلا بعد أن يقوم قاضى التفليسة بإقفالها .
ويدعى المفلس إلى حضور جلسة إقفال الدفاتر التجارية ، فإذا لم يحضر أقفلت الدفاتر بغير حضوره .
ولا يجوز للمفلس أن ينيب عنه غيره لحضور جلسة إقفال الدفاتر إلا لأسباب يقبلها قاضى التفليسة .$m251$,'e2c96eb6cb60c78cd484a0567a7b350f'),
(160,0,$m251$المادة 160$m251$,$m251$إذا لم يكن المفلس قد قدم الميزانية ، وجب على أمين التفليسة أن يقوم بإعدادها ، وإيداعها قلم كتاب المحكمة .
ويتسلم أمين التفليسة الرسائل الواردة باسم المفلس والمتعلقة بأشغاله ، ولأمين التفليسة فضها والاحتفاظ بها ، وللمفلس الاطلاع عليها .$m251$,'fab48d1010f8a4ae84c06d141107745e'),
(161,0,$m251$المادة 161$m251$,$m251$يقوم أمين التفليسة بجميع الأعمال اللازمة للمحافظة على حقوق المفلس لدى الغير ، ويطالب بهذه الحقوق ويستوفيها ، وعليه أن يقيد ما للمفلس من حقوق عينية على عقارات مدينه ، إذا لم يكن المفلس قد أجرى القيد .$m251$,'856fc9b2a2ed3dba3e3977fc1de3738e'),
(162,0,$m251$المادة 162$m251$,$m251$يجوز لقاضى التفليسة بعد أخذ رأى المراقب وسماع أقوال المفلس أو إخطاره ، أن يأذن لأمين التفليسة بالصلح أو بقبول التحكيم فى كل نزاع يتعلق بالتفليسة ، ولو كان خاصا بحقوق أو دعاوى عقارية .
فإذا كان النزاع غير معين القيمة ، أو كانت قيمته تزيد على عشرين ألف جنيه ، فلا يكون الصلح أو قبول التحكيم نافذا إلا بعد تصديق قاضى التفليسة على شروطه ، ويدعى المفلس إلى الحضور عند التصديق ويسمع قاضى التفليسة أقواله إذا حضر ، ولا يكون لاعتراضه أى أثر ، ويجوز الطعن أمام المحكمة فى قرار قاضى التفليسة إذا صدر برفض التصديق على شروط الصلح أو التحكيم .
ولا يجوز لأمين التفليسة النزول عن حق للمفلس ، أو الإقرار بحق للغير عليه إلا بالإجراءات المبينة فى هذه المادة .$m251$,'118dfecf1459c979e83b097e1757fb1a'),
(163,0,$m251$المادة 163$m251$,$m251$لقاضى التفليسة من تلقاء نفسه أو بناء على طلب أمينها أو طلب المفلس أن يندب لجنة إعادة الهيكلة ، لوضع خطة لاستمرار تجارة المفلس بما يشمل تشغيل المتجر إذا اقتضت ذلك المصلحة العامة أو مصلحة المفلس أو الدائنين .
ويعين قاضى التفليسة بناء على اقتراح اللجنة المشار إليها وبعد أخذ رأى أمين التفليسة من يتولى إدارة المتجر بناء على خطة إعادة الهيكلة ويحدد أجره ، ويجوز تعيين المفلس للإدارة ويعتبر الأجر الذى يحصل عليه بديلا عن الإعانة .
ويشرف أمين التفليسة أو أمين اتحاد الدائنين على من يعين للإدارة ، وعليه أن يقدم تقريرا شهريا إلى قاضى التفليسة عن سير التجارة .
ويجوز للمفلس ولأى من أمينيها ولأى من الدائنين الطعن أمام المحكمة فى قرار قاضى التفليسة برفض الإذن بالاستمرار فى خطة إعادة الهيكلة بما فيها تشغيل المتجر .$m251$,'7e576d002cb155ec18e2e15bd3a89ccb'),
(164,0,$m251$المادة 164$m251$,$m251$فى حالة وفاة المفلس يقوم ورثته مقامه فى إجراءات الإفلاس ، ولهم أن ينيبوا أحدهم ليمثلهم فى ذلك ، فإذا لم يتفقوا جاز لقاضى التفليسة بناء على طلب أمينها إنابة من يمثلهم ، وللقاضى فى كل وقت عزل من أنيب وتعيين غيره .$m251$,'68fb6bb40a3ad4f64a2402c476db1c90'),
(165,0,$m251$المادة 165$m251$,$m251$على أمين التفليسة أن يقدم إلى قاضى التفليسة خلال ثلاثين يوما من تاريخ إخطاره بالتعيين تقريرا عن أسباب الإفلاس وحالة التفليسة الظاهرة وظروفها ، ويجوز لقاضى التفليسة مد الميعاد المحدد لتقديم هذا التقرير ، وعلى القاضى إحالة التقرير مع ملاحظاته إلى النيابة العامة .
كما يجب على أمين التفليسة أن يقدم إلى قاضى التفليسة تقارير عن حالة التفليسة فى مواعيد دورية يحددها القاضى .$m251$,'34e8b1f6edbd0df293388a4a259373aa'),
(166,0,$m251$المادة 166$m251$,$m251$على جميع الدائنين ولو كانت ديونهم مصحوبة بتأمينات خاصة أو كانت ثابتة بأحكام نهائية أن يسلموا أمين التفليسة عقب صدور الحكم بشهر الإفلاس أصول مستندات ديونهم مصحوبة ببيان بهذه الديون وتأميناتها إن وجدت ومقدارها مقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزى بيعا أو إقفالا وتحويلات أو بنكنوتا إذا لم يوجد سعر تحويلات يوم صدور الحكم بشهر الإفلاس ، ويحرر أمين التفليسة إيصالا بتسلمه البيان ومستندات الدين .
ويجب أن يتضمن البيان تعيين محل مختار لأمين التفليسة فى دائرة المحكمة .
ويكون أمين التفليسة مسئولا عن المستندات لمدة سنة من تاريخ انتهاء التفليسة ، ويعيدها إلى الدائنين بعد قفل التفليسة .$m251$,'f9a71f6577b16bbb110de1acb14edd36'),
(167,0,$m251$المادة 167$m251$,$m251$إذا لم يقدم جميع الدائنين المقيدة أسماؤهم فى الميزانية أصول مستندات ديونهم مصحوبة بالبيان المشار إليه فى المادة (166) من هذا القانون خلال الثلاثين يوما التالية لنشر الحكم بشهر الإفلاس ودعوة الدائنين للتقدم بديونهم ، وجب على أمين التفليسة إعادة النشر فورا فى الصحيفة اليومية التى نشر فيها حكم الإفلاس وللقاضى تحديد وسيلة نشر أخرى يقوم بها أمين التفليسة بالإضافة إلى النشر فى الصحف .
وعلى أمين التفليسة خلال الميعاد المنصوص عليه بالفقرة السابقة إخطار الدائنين الواردة أسماؤهم بالميزانية المعتمدة للمفلس فى حالة وجودها بالحكم والتقدم فى التفليسة ، وكذا إخطار كافة الجهات الحكومية ويعد النشر دليلا على علم الكافة .
وعلى الدائنين تقديم أصول مستندات ديونهم مصحوبة بالبيان المشار إليه خلال ثلاثين يوما من تاريخ النشر الثانى فى الصحف وإلا سقط حقهم فى الدخول فى التفليسة .$m251$,'4944ff44d31d5a0fd65a2ce069212691'),
(168,0,$m251$المادة 168$m251$,$m251$يحقق أمين التفليسة الديون بمعاونة المراقب وبحضور المفلس أو بعد إخطاره بالحضور .
وإذا نازع أمين التفليسة أو المراقب أو المفلس فى صحة أحد الديون أو فى مقداره أو فى ضماناته وجب على أمين التفليسة إخطار الدائن فورا بذلك وللدائن تقديم إيضاحات كتابية أو شفوية خلال عشرة أيام من تاريخ تسلم الإخطار .
ولا تخضع الديون واجبة السداد المستحقة للحكومة بسبب الرسوم والضرائب على اختلاف أنواعها لإجراءات التحقيق .$m251$,'16bd923a98f136beae51d8e40d06236d'),
(169,0,$m251$المادة 169$m251$,$m251$يودع أمين التفليسة قلم كتاب المحكمة بعد الانتهاء من تحقيق الديون قائمة بها تشتمل على بيان بمستنداتها ، وأسباب المنازعة فيها إن وجدت ، وما يراه بشأن قبولها أو رفضها ، كما يودع كشفا بأسماء الدائنين الذين يدعون أن لهم تأمينات خاصة على أموال المفلس مبينا مقدار ديونهم ونوع تأميناتهم والأموال المقررة عليها .
ويجب أن يتم هذا الإيداع خلال أربعين يوما على الأكثر من تاريخ النشر الثانى لدعوة الدائنين للتقدم بديونهم .
وعلى أمين التفليسة خلال ستة أيام من تاريخ الإيداع أن ينشر فى صحيفة يومية بيانا بحصوله .
ولكل ذى مصلحة الاطلاع على القائمة والكشف المودعين بقلم كتاب المحكمة .$m251$,'be0a62edcc5673c7f9ce9eb720b1cadd'),
(170,0,$m251$المادة 170$m251$,$m251$للمفلس ولكل دائن ورد اسمه بقائمة الديون أن ينازع فى الديون المدرجة بها خلال عشرة أيام من تاريخ النشر فى الصحف عن حصول الإيداع ، وتسلم المنازعة إلى قلم كتاب المحكمة أو ترسل إليه بكتاب مسجل مصحوبا بعلم الوصول ، وعلى قلم الكتاب عرضها فورا على قاضى التفليسة ولا يضاف إلى هذا الميعاد ميعاد للمسافة .$m251$,'be337585166fce15dfc0c15923674ba8'),
(171,0,$m251$المادة 171$m251$,$m251$يضع قاضى التفليسة بعد انقضاء الميعاد المنصوص عليه فى المادة ( 170 ) من هذا القانون قائمة نهائية بالديون غير المتنازع فيها خلال ثلاثين يوما على الأكثر ، ويؤشر أمين التفليسة على البيان الذى يصحب مستندات هذه الديون بما يفيد قبولها ومقدار ما قبل من كل دين منها .
ويجوز لقاضى التفليسة اعتبار الدين متنازعا فيه ولو لم تقدم بشأنه أى منازعة .
ويفصل قاضى التفليسة فى الديون المتنازع فيها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة ، ويخطر قلم كتاب المحكمة ذوى الشأن بميعاد الجلسة قبل انعقادها بثلاثة أيام على الأقل .
يصير الدائنون فى حالة اتحاد بحكم القانون بعد إيداع القائمة النهائية الديون غير المتنازع فيها .$m251$,'63fdb9aa6a590d612b3ba28abad8d4b0'),
(172,0,$m251$المادة 172$m251$,$m251$يجوز الطعن أمام المحكمة فى القرار الصادر من قاضى التفليسة بقبول الدين أو رفضه ، وذلك خلال عشرة أيام من تاريخ صدور القرار ، ولا يترتب على الطعن وقف إجراءات التفليسة إلا إذا أمرت المحكمة بوقفها ، ويجوز للمحكمة قبل الفصل فى الطعن أن تقضى بقبول الدين مؤقتا بمبلغ تقدره ، ولا يجوز الطعن فى حكم المحكمة برفض الدين نهائيا أو بقبوله ، وإذا كان الطعن فى الدين متعلقا بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا ، ولايشترك الدائن الذى لم يقبل دينه نهائيا أو مؤقتا فى إجراءات التفليسة .$m251$,'d3c5d6add13a50da4b02bb59acb3ce30'),
(173,0,$m251$المادة 173$m251$,$m251$إذا توقفت أعمال التفليسة لعدم كفاية الأموال اللازمة لإدارتها ومواجهة أعمالها ، جاز لقاضى التفليسة من تلقاء نفسه أو بناء على تقرير من أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال أن يأمر بقفلها بقرار مسبب .
ويجوز للمفلس ولكل ذى مصلحة ولأمينها أن يطلبوا من قاضى التفليسة إلغاء قرار القفل خلال ثلاثة أشهر من تاريخ صدور القرار بقفلها إذا أثبت وجود مال كاف لمواجهة مصاريف استكمال أعمال التفليسة أو إذا أودع مبلغا كافيا لذلك يقدره قاضى التفليسة .
فإذا انقضت المدة المنصوص عليها فى الفقرة السابقة دون أن يتقدم أحد بطلب لقاضى التفليسة لإلغاء قرار القفل اعتبرت التفليسة منتهية بقوة القانون .$m251$,'fdfe565379a06d2e28a08ec4993373d0'),
(174,0,$m251$المادة 174$m251$,$m251$يجوز التظلم من قرارى قفل التفليسة ورفض إلغائه خلال عشرة أيام من تاريخ صدوره على ألا يترتب على التظلم وقف تنفيذ القرار أو قطع المدة المشار إليها بالفقرة الثانية من المادة (173) من هذا القانون .$m251$,'f45af7628f4dc9b06985996ef6a3373b'),
(175,0,$m251$المادة 175$m251$,$m251$يترتب على نهائية قرار قفل التفليسة لعدم كفاية أموالها أن يعود إلى كل دائن الحق فى اتخاذ الإجراءات ومباشرة الدعاوى الفردية ضد المفلس .
وإذا كان دين الدائن قد ثبت نهائيا فى التفليسة جاز له التنفيذ على أموال المفلس بناء على شهادة من قاضى التفليسة بمقدار دينه ، تعتبر بمثابة حكم نهائى فيما يتعلق بهذا التنفيذ ، ويؤشر على سند الدين بما يفيد استلام الدائن للشهادة .
وفى جميع الأحوال يجب أن تدفع بالأولوية مصاريف الإجراءات التى تمت فى أعمال التفليسة .$m251$,'dca520d1030a0de4aa9462c2a4abd45d'),
(176,0,$m251$المادة 176$m251$,$m251$يصدر قاضى التفليسة قرارا بانتهاء التفليسة فى الحالات الآتية :
(أ) إذا تم تحقيق الديون وأسفرت عن عدم وجود ديون مقبولة فى التفليسة أو وجود ديون متمثلة فى غرامات جنائية أو ضرائب ورسوم على اختلاف أنواعها أو تأمينات اجتماعية أو وجود دائن واحد فقط ، أو اجتمعت الديون فى يد دائن واحد .
(ب) سداد جميع الديون المقبولة فى التفليسة .
(ج) الصلح مع المدين المفلس .
(د) عدم وجود أموال للمفلس صالحة للتنفيذ عليها .
(هـ) تصفية جميع أموال المفلس والتصديق على الحساب الختامى .$m251$,'a4452f210a3ebbd3d6347cc141de26fb'),
(177,0,$m251$المادة 177$m251$,$m251$لا يجوز لقاضى التفليسة أن يأمر بإنهائها إلا بعد الاطلاع على تقرير من أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال يبين فيه تحقق إحدى الحالات المشار إليها فى المادة (176) من هذا القانون .
وتنتهى التفليسة بمجرد صدور قرار قاضى التفليسة بإنهائها ويستعيد المفلس جميع حقوقه .$m251$,'16abfb23759761b1d2d598955720c00f'),
(178,0,$m251$المادة 178$m251$,$m251$لقاضى التفليسة بناء على طلب كل ذى مصلحة وفى أى مرحلة كانت عليها الإجراءات أن يباشر إجراءات الوساطة للوصول إلى الصلح وله فى سبيل ذلك أن يأمر قلم الكتاب بدعوة الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا لحضور المداولة فى طلب الصلح .
يقدم أمين التفليسة أو أمين الاتحاد حسب الأحوال تقريرا إلى جماعة الدائنين مشتملا على حالة التفليسة وما تم بشأنها من إجراءات ، ومقترحات المفلس فى الصلح ورأيه فيها .$m251$,'1399bf817731035cb38d6eaa0c1009b3'),
(179,0,$m251$المادة 179$m251$,$m251$لا يقع الصلح إلا بموافقة جميع الدائنين ، ولا يجوز للدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك فى التصويت على الصلح بديونهم المضمونة بالتأمينات المذكورة إلا إذا نزلوا عن هذه التأمينات مقدما .$m251$,'266f0644bfa48b64a64aae77127c8d30'),
(180,0,$m251$المادة 180$m251$,$m251$يوقع محضر الصلح فى الجلسة التى تم فيها التصويت عليه ويقوم القاضى بالتصديق عليه ، ويتم نشره بإحدى الصحف اليومية .$m251$,'8923abac154230a578c19cb04e1e0977'),
(181,0,$m251$المادة 181$m251$,$m251$لا يجوز عقد الصلح مع مفلس حكم عليه بعقوبة الإفلاس بالتدليس ، وإذا بدأ التحقيق مع المفلس فى جريمة الإفلاس بالتدليس وجب تأجيل النظر فى الصلح .$m251$,'3a12a2e97fbe443ed54440c6ee75b349'),
(182,0,$m251$المادة 182$m251$,$m251$تزول جميع آثار الإفلاس بصدور قرار التصديق على الصلح ، ويكون على الأمين أن يقدم إلى المفلس حسابا ختاميا ويناقش الحساب بحضور قاضى التفليسة .
وتنتهى مهمة الأمين ويستلم المفلس أمواله ودفاتره وأوراقه منه بموجب إيصال ، ولا يكون الأمين مسئولا عن هذه الأشياء إذا لم يستلمها المفلس خلال سنة من تاريخ إقرار الحساب الختامى .
ويحرر قاضى التفليسة محضرا بجميع ما تقدم .$m251$,'0880c24d140a10caed665c2e0b4fc4bd'),
(183,0,$m251$المادة 183$m251$,$m251$يبطل الصلح إذا صدر بعد التصديق عليه حكم بإدانة المفلس فى إحدى جرائم الإفلاس بالتدليس .
وكذلك يبطل الصلح إذا ظهر بعد التصديق عليه تدليس ناشئ عن إخفاء موجودات المفلس أو المبالغة فى ديونه ، وفى هذه الحالة يجب أن يكون طلب إبطال الصلح خلال ستة أشهر من اليوم الذى يظهر فيه التدليس وإلا كان الطلب غير مقبول ، وفى جميع الأحوال لا يكون طلب إبطال الصلح مقبولا إذا قدم بعد انقضاء سنتين من تاريخ التصديق على الصلح .
ويترتب على إبطال الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروطه .
وتختص المحكمة التى أصدرت حكم شهر الإفلاس بنظر دعوى إبطال الصلح .$m251$,'88ed8ad402f07c464120fcb8804fb504'),
(184,0,$m251$المادة 184$m251$,$m251$إذا بدأ التحقيق مع المفلس فى جريمة الإفلاس بالتدليس بعد التصديق على الصلح أو إذا أقيمت عليه الدعوى الجنائية فى هذه الجريمة بعد التصديق على الصلح ، جاز للمحكمة التى أصدرت حكم شهر الإفلاس ، بناء على طلب النيابة العامة أو كل ذى مصلحة أن تأمر باتخاذ ما تراه من تدابير للمحافظة على أموال المدين ، وتلغى هذه التدابير بحكم القانون ، إذا تقرر حفظ التحقيق أو صدر قرار بأن لا وجه لإقامة الدعوى أو حكم ببراءة المفلس .$m251$,'55fe091b23ce72ae3fd2a3ff3d112c61'),
(185,0,$m251$المادة 185$m251$,$m251$إذا لم يقم المفلس بتنفيذ شروط الصلح جاز طلب فسخه من المحكمة التى أصدرت حكم شهر الإفلاس .
ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروطه ، ويجب تكليف هذا الكفيل بحضور الجلسة التى نظر فيها طلب فسخ الصلح .$m251$,'eccaa0fcff04a9300f783aa820370bfe'),
(186,0,$m251$المادة 186$m251$,$m251$التصرفات الحاصلة من المدين بعد التصديق على الصلح وقبل إبطاله أو فسخه تكون نافذة فى حق الدائنين ، ولا يجوز لهم طلب عدم نفاذها فى حقهم إلا طبقا للأحكام المنصوص عليها فى المادة (237) من القانون المدنى .
وتسقط دعوى عدم نفاذ التصرف المنصوص عليها فى الفقرة السابقة بمضى سنتين من تاريخ إبطال الصلح أو فسخه .$m251$,'2532f5104746a4845f715efc59be839c'),
(187,0,$m251$المادة 187$m251$,$m251$تعود إلى الدائنين بعد إبطال الصلح أو فسخه ديونهم كاملة وذلك بالنسبة إلى المفلس فقط .
ويشترك هؤلاء الدائنون فى جماعة الدائنين بديونهم الأصلية كاملة إذا لم يكونوا قد قبضوا شيئا من القدر الذى تقرر لهم فى الصلح وإلا وجب تخفيض ديونهم الأصلية بنسبة ما حصلوا عليه من القدر المذكور .
وتسرى الأحكام المذكورة فى الفقرتين السابقتين فى حالة شهر إفلاس المدين مرة أخرى قبل أن يصدر حكم بإبطال الصلح أو بفسخه .$m251$,'3030da41c783ac952f1e7e7b2a8a2b70'),
(188,0,$m251$المادة 188$m251$,$m251$يجوز أن يعقد الصلح على أن يتخلى المدين عن أمواله كلها أو بعضها لبيعها وتوزيع ثمنها على الدائنين ، وتسرى على هذا الصلح أحكام الصلح القضائى ويظل المدين ممنوعا عن التصرف والإدارة فى الأموال التى تخلى عنها .
وتباع الأموال التى يتخلى عنها المدين ويوزع ثمنها طبقا للقواعد المقررة لبيع وتوزيع أموال المفلس فى حالة الاتحاد .
وإذا كان الثمن الناتج عن بيع الأموال التى تخلى عنها المدين يجاوز الديون المطلوبة منه وجب رد المقدار الزائد إليه .$m251$,'fff37b5423a284ca230b942e8c5bd56b'),
(189,0,$m251$المادة 189$m251$,$m251$يدعو قاضى التفليسة الدائنين إثر قيام حالة الاتحاد للمداولة فى شئون التفليسة والنظر فى إبقاء أمين التفليسة أو تغييره ، ويسمى فى هذه المرحلة أمين الاتحاد ، وللدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك فى هذه المداولات والتصويت دون أن يترتب على ذلك سقوط تأميناتهم .
وإذا قررت أغلبية الدائنين الحاضرين تغيير أمين التفليسة وجب على قاضى التفليسة تعيين غيره فورا ، فإن أجمع الدائنون على تسمية أمين ، بخلاف صاحب الدور ، يستجيب قاضى التفليسة لاختيارهم .
وعلى أمين التفليسة السابق أن يقدم إلى أمين الاتحاد فى الميعاد الذى يعينه قاضى التفليسة وبحضوره حسابا عن إدارته ويخطر المدين بميعاد تقديم الحساب .
ويجوز للمحكمة المختصة بناء على طلب قاضى التفليسة تغيير أمين اتحاد الدائنين إذا أخل بواجباته .$m251$,'078f5e51f31e7598f55b38cad25e0e46'),
(190,0,$m251$المادة 190$m251$,$m251$يؤخذ رأى الدائنين خلال الاجتماع المنصوص عليه فى المادة (189) من هذا القانون فى أمر تقرير إعانة من أموال التفليسة للمفلس أو لمن يعولهم .
وإذا وافقت أغلبية الدائنين الحاضرين على تقرير الإعانة للمفلس أو لمن يعولهم وجب على قاضى التفليسة ، بعد أخذ رأى أمين الاتحاد ورأى المراقب ، تعيين مقدار الإعانة .
ويجوز لأمين الاتحاد وكذا المفلس أو من يعولهم ، الطعن أمام المحكمة فى قرار قاضى التفليسة بتعيين مقدار الإعانة ، وفى هذه الحالة يصرف نصف الإعانة لمن تقررت له إلى حين الفصل فى الطعن .$m251$,'a59c237f3945efe1c76e983537763945'),
(191,0,$m251$المادة 191$m251$,$m251$لا يجوز لأمين الاتحاد الاستمرار فى خطة إعادة الهيكلة المنصوص عليها فى المادة (163) من هذا القانون إلا بعد الحصول على تفويض يصدر بأغلبية تمثل ثلثى الدائنين عددا ومبلغا ، ويجوز لهم تعديل خطة إعادة التشغيل بعد أخذ رأى لجنة إعادة الهيكلة وتصديق قاضى التفليسة .
وإذا نشأت عن تنفيذ خطة إعادة الهيكلة التزامات تزيد على أموال الاتحاد كان الدائنون الذين وافقوا على الاستمرار فى التجارة مسئولين فى أموالهم الخاصة ودون تضامن بينهم عن الزيادة بشرط أن تكون ناشئة عن أعمال تدخل فى حدود التفويض الصادر منهم ، وتكون مسئولية كل دائن بنسبة دينه .$m251$,'948758d66fc2a74642f46eb64593f126'),
(192,0,$m251$المادة 192$m251$,$m251$تسرى على إفلاس الشركات الأحكام المذكورة فى هذا الفصل والقواعد التالية :$m251$,'dd6d6ef4fceda3ce926533573d0c5df9'),
(193,0,$m251$المادة 193$m251$,$m251$تعد فى حالة إفلاس كل شركة توقفت عن دفع ديونها إثر اضطراب أعمالها المالية ، ويلزم شهر إفلاسها بحكم يصدر بذلك .
ويجوز شهر إفلاس الشركة ولو كانت فى دور التصفية .$m251$,'b47b778fc487eefed7d142db4b60f1ee'),
(194,0,$m251$المادة 194$m251$,$m251$لا يجوز للممثل القانونى للشركة أن يطلب شهر إفلاسها إلا بعد الحصول على إذن بذلك من أغلبية الشركاء أو من الجمعية العامة حسب الأحوال .
ويجب أن يشتمل طلب شهر الإفلاس على أسماء الشركاء المتضامنين الحاليين والذين خرجوا من الشركة بعد توقفها عن الدفع مع بيان موطن كل شريك متضامن وجنسيته وتاريخ شهر خروجه من الشركة فى السجل التجارى .$m251$,'c30c08461d6b6d43ca3c353c49ebaefd'),
(195,0,$m251$المادة 195$m251$,$m251$يجوز لدائن الشركة طلب شهر إفلاسها ولو كان شريكا فيها ، أما الشركاء غير الدائنين فلا يجوز لهم بصفتهم الفردية طلب شهر إفلاس الشركة .
وإذا طلب الدائن شهر إفلاس الشركة ، وجب اختصام كافة الشركاء المتضامنين .$m251$,'13ffaca6c865b6a66fbf5002ee40da70'),
(196,0,$m251$المادة 196$m251$,$m251$يجوز للمحكمة من تلقاء ذاتها أو بناء على طلب الشركة أن تؤجل النظر فى شهر إفلاسها لمدة لا تجاوز ثلاثة أشهر إذا كان من المحتمل دعم مركزها المالى أو إذا اقتضت مصلحة الاقتصاد القومى ذلك ، وللمحكمة أن تأمر باتخاذ ما تراه من تدابير للمحافظة على موجودات الشركة .$m251$,'8416e7b3331e6c66d02ee4c3e047884f'),
(197,0,$m251$المادة 197$m251$,$m251$إذا شهر إفلاس الشركة وجب شهر إفلاس جميع الشركاء المتضامنين فيها ، ويشمل شهر الإفلاس الشريك المتضامن الذى خرج من الشركة بعد توقفها عن الدفع إذا طلب شهر إفلاس الشركة قبل انقضاء سنة من تاريخ شهر خروج الشريك فى السجل التجارى .
وتقضى المحكمة بحكم واحد بشهر إفلاس الشركة والشركاء المتضامنين ولو لم تكن مختصة بشهر إفلاس هؤلاء الشركاء .
وتعين المحكمة لتفليسة الشركة وتفليسات الشركاء المتضامنين قاضيا واحدا وأمينا واحدا أو أكثر ، ومع ذلك تكون كل تفليسة مستقلة عن غيرها من التفليسات من حيث موجوداتها وخصومها وإدارتها وتحقيق ديونها وكيفية انتهائها .$m251$,'2174ccd8d58e3b59f467c484f12eee69'),
(198,0,$m251$المادة 198$m251$,$m251$للمحكمة من تلقاء ذاتها أو بناء على طلب قاضى التفليسة أن تقضى بإسقاط الحقوق المنصوص عليها فى المادة (111) من هذا القانون عن أعضاء مجلس إدارة الشركة أو مديريها الذين ارتكبوا أخطاء جسيمة أدت إلى اضطراب أعمال الشركة وتوقفها عن الدفع .
إذا طلب شهر إفلاس الشركة جاز للمحكمة أن تقضى أيضا بشهر إفلاس كل شخص قام تحت ستار هذه الشركة بأعمال تجارية لحسابه الخاص وتصرف فى أموال الشركة كما لو كانت أمواله الخاصة .
وإذا تبين أن موجودات الشركة لا تكفى لوفاء (20٪) على الأقل من ديونها ، جاز للمحكمة بناء على طلب قاضى التفليسة أن تقضى بإلزام أعضاء مجلس الإدارة أو المديرين كلهم أو بعضهم بالتضامن بينهم أو بغير تضامن بدفع ديون الشركة كلها أو بعضها إلا إذا أثبتوا أنهم بذلوا فى تدبير شئون الشركة عناية الرجل الحريص .$m251$,'0d13ae80c7511985a74fefb2ee2cf6ca'),
(199,0,$m251$المادة 199$m251$,$m251$يقوم الممثل القانونى عن الشركة التى أشهر إفلاسها مقامها فى كل أمر يستلزم فيه القانون أخذ رأى المفلس أو حضوره وعليه الحضور أمام قاضى التفليسة أو أمينها متى طلب منه ذلك والإدلاء بما يطلب من معلومات أو إيضاحات .$m251$,'69868390c976c9246b10fdde26d3a459'),
(200,0,$m251$المادة 200$m251$,$m251$يجوز لأمين التفليسة بعد استئذان قاضى التفليسة أن يطالب الشركاء أو المساهمين بدفع الباقى من حصصهم أو باقى قيمة أسهمهم فى رأس المال ولو لم يحل ميعاد استحقاقه ، ولقاضى التفليسة أن يأمر بقصر هذه المطالبة على القدر اللازم لوفاء ديون الشركة .$m251$,'97aebea639def0db60b064b778acfa4b'),
(201,0,$m251$المادة 201$m251$,$m251$لا تخضع سندات القرض أو صكوك التمويل التى أصدرتها الشركة لإجراءات تحقيق الديون ، وتقبل هذه السندات أو الصكوك بقيمتها الاسمية بعد استنزال ما تكون الشركة قد دفعته منها ، وإذا اشترط أداء مكافأة عند الوفاء بسند القرض وجب قبول السند بقيمته الاسمية مضافا إليها الجزء الذى استحق من المكافأة حتى صدور الحكم بشهر الإفلاس .$m251$,'7dd7d345401263a19258e53adbd12e40'),
(202,0,$m251$المادة 202$m251$,$m251$توضع مقترحات الصلح بموافقة أغلبية الشركاء أو الجمعية العامة بحسب الأحوال .
ويتولى الممثل القانونى عن الشركة تقديم مقترحات الصلح إلى جماعة الدائنين .$m251$,'23ec27724fda7de2003b517359064615'),
(203,0,$m251$المادة 203$m251$,$m251$إذا كان الصلح خاصا بشركة أصدرت سندات قرض أو صكوك تمويل تجاوز قيمتها ثلث مجموع ديونها ، فلا يجوز منحها الصلح إلا إذا وافقت على شروطه الجمعية العامة لجماعة مالكى هذه السندات أو الصكوك ، وتؤجل دعوة الدائنين إلى الاجتماع للمداولة فى الصلح إلى أن تصدر تلك الموافقة .$m251$,'826630389ebb64fce058fcb5806dfb5b'),
(204,0,$m251$المادة 204$m251$,$m251$إذا انتهت تفليسة الشركة بالاتحاد وتم الصلح مع واحد أو أكثر من الشركاء المتضامنين فلا يجوز تخصيص أموال الشركة للوفاء بشروط هذا الصلح أو لضمان تنفيذها ، ويبرأ الشريك الذى حصل على الصلح من التضامن .
وإذا تم الصلح مع الشركة وانتهت تفليسات الشركاء المتضامنين بالاتحاد ، استمرت الشركة قائمة إلا إذا كان موضوع الصلح هو التخلى عن جميع أموالها .
وإذا انتهت تفليسة الشركة وتفليسات الشركاء بالصلح ، اعتبر كل صلح مستقلا عن غيره ولا تسرى شروطه إلا على دائنى التفليسة الخاصة به .$m251$,'0611bbda285ff5c43c5c6182f9878a7b'),
(205,0,$m251$المادة 205$m251$,$m251$لا تحل الشركة بانتهاء تفليستها بالاتحاد ، ومع ذلك يجوز حل هذه الشركة إذا تبين أن ما بقى من موجوداتها بعد تصفية الاتحاد لا يكفى لمتابعة أعمالها على وجه مجد .$m251$,'946b043f307528b960ca1513261005cf'),
(206,0,$m251$المادة 206$m251$,$m251$إذا انقضت ستة أشهر من تاريخ قيام حالة الاتحاد دون إنجاز التصفية ، وجب على أمين الاتحاد أن يقدم إلى قاضى التفليسة تقريرا عن حالة التصفية وأسباب التأخير فى إنجازها ، ويرسل القاضى هذا التقرير إلى الدائنين مع دعوتهم للاجتماع لمناقشته ، ويتكرر ذلك الإجراء كلما انقضت ستة أشهر دون أن ينجز أمين الاتحاد أعمال التصفية .$m251$,'271d98a59b14963bcacc4d10a94fe4b0'),
(207,0,$m251$المادة 207$m251$,$m251$يقدم أمين الاتحاد بعد الانتهاء من أعمال التصفية حسابا ختاميا إلى قاضى التفليسة ، ويرسل القاضى هذا الحساب إلى الدائنين مع دعوتهم للاجتماع لمناقشته ، ويخطر المفلس بهذا الاجتماع وله حضوره .
وينحل الاتحاد وتعتبر التفليسة منتهية بحكم القانون بعد المصادقة على الحساب المشار إليه فى الفقرة السابقة .
ويكون أمين الاتحاد مسئولا لمدة سنة من تاريخ انتهاء التفليسة عن الدفاتر والمستندات والأوراق المسلمة إليه .$m251$,'5ed79f6ad09a9f83b05b5ae26fca45dd'),
(208,0,$m251$المادة 208$m251$,$m251$يعود إلى كل دائن بعد انتهاء حالة الاتحاد الحق فى التنفيذ على المدين للحصول على الباقى من دينه بناء على شهادة من قاضى التفليسة بالمتبقى من دينه ، ويعتبر قبول الدين فى التفليسة بمثابة حكم نهائى فيما يتعلق بهذا التنفيذ ، على أن يؤشر على سند الدين بما يفيد استلام الدائن للشهادة .$m251$,'ece81d988e13dbf0f4d0b55a58141d9d'),
(209,0,$m251$المادة 209$m251$,$m251$إذا تبين بعد جرد أموال المفلس أن قيمتها لا تزيد على خمسمائة ألف جنيه ، جاز لقاضى التفليسة من تلقاء نفسه أو بناء على طلب من أمين التفليسة أو أحد الدائنين أن يأمر بالسير فى إجراءات التفليسة وفقا للأحكام الآتية :
(أ) تخفض إلى النصف المواعيد المنصوص عليها فى الفقرة الأولى من المادة (165) والمادة (167) والفقرة الثانية من المادة (168) والفقرة الثانية من المادة (169) والمادة (170) والفقرة الثالثة من المادة (171) من هذا القانون .
(ب) تكون جميع قرارات قاضى التفليسة غير قابلة للطعن فيها ، ما لم ينص القانون على خلاف ذلك ، أو كان القرار مما يجاوز اختصاصه .
(ج) لا يعين مراقب للتفليسة .
(د) لا يغير أمين التفليسة عند قيام حالة الاتحاد .
(هـ) لا يجرى إلا توزيع واحد على الدائنين بعد الانتهاء من بيع أموال التفليسة .$m251$,'c3878b86b8bb17dcd7018b3bf5a158f8'),
(210,0,$m251$المادة 210$m251$,$m251$مع عدم الإخلال بأحكام قيد الرهن الرسمى للعقارات والطائرات والسفن والرهن التجارى للمحال التجارية والضمانات المنقولة والتمويل العقارى والتأجير التمويلى والرهن الحيازى والملكية الفكرية المنصوص عليها فى القوانين المنظمة لها ، تسرى على بيع موجودات التفليسة الأحكام المنظمة فى هذا الباب .$m251$,'983cb2911df5e3855e0e739b79757053'),
(211,0,$m251$المادة 211$m251$,$m251$لا يجوز بيع أموال التفليسة خلال فترة الإجراءات التمهيدية التى يجرى فيها وضع الأختام والنشر ورفع الأختام والجرد ، ومع ذلك يجوز لقاضى التفليسة بناء على طلب أمينها أن يأذن ببيع الأشياء القابلة لتلف سريع أو نقص عاجل فى القيمة ، أو التى تقتضى صيانتها مصاريف باهظة ، كما يجوز الإذن ببيع أموال التفليسة إذا كان البيع لازما للحصول على نقود للصرف على شئونها ، أو كان البيع يحقق نفعا مؤكدا للدائنين أو للمفلس ولا يجوز الإذن بالبيع فى الحالة الأخيرة إلا بعد إخطار المفلس بالبيع وسماع أقواله .$m251$,'4683070fc757fe23b9dba9d0b65fa019'),
(212,0,$m251$المادة 212$m251$,$m251$يجوز الطعن أمام المحكمة فى القرار الصادر من قاضى التفليسة ببيع أموال المفلس أثناء فترة التمهيدية خلال عشرة أيام من تاريخ صدور قرار البدء فى اتخاذ إجراءات البيع .$m251$,'906ea4e1d6b155f1c3aa933539a393e2'),
(213,0,$m251$المادة 213$m251$,$m251$يجب على الدائنين المرتهنين اتخاذ إجراءات بيع المنقولات أو العقارات التى يقع عليها رهنهم وفقا للطريقة المحددة بعقود الضمان واستيفاء حقوقهم المضمونة بهذه المنقولات أو العقارات ، وذلك خلال عام على الأكثر من تاريخ شهر الإفلاس ، على أن يتم ذلك البيع فى مواجهة أمين التفليسة ، وإلا كان لأمين التفليسة أو أمين الاتحاد بحسب الأحوال دون غيره بعد إخطار الدائن حق التنفيذ عليها وفقا للأحكام الواردة بهذا القانون .
وفى حالة بيع المنقولات أو العقارات المرهونة بناء على طلب الدائن المرتهن بثمن يجاوز الدين ، وجب على أمين التفليسة أو أمين اتحاد الدائنين قبض المقدار الزائد لحساب جماعة الدائنين وإيداعه حساب التفليسة .
ولأمين اتحاد الدائنين بيع المنقولات أو العقارات المرهونة بعد الحصول على موافقة الدائن المرتهن بالبيع قبل انقضاء المدة المنصوص عليها بالفقرة الأولى من هذه المادة .
وتسرى الأحكام الواردة فى هذه المادة على أصحاب حقوق الامتياز الخاصة ، والحاصلين على اختصاص على أموال المدين .$m251$,'c33ccb774fe43545d800b9f183c212d8'),
(214,0,$m251$المادة 214$m251$,$m251$يجرى بيع موجودات التفليسة بإذن أو قرار من قاضى التفليسة بمباشرة إجراءات البيع بطريق المزايدة العلنية بناء على قائمة شروط البيع التى يودعها أمين التفليسة أو أمين اتحاد الدائنين - بحسب الأحوال - قلم كتاب المحكمة المختصة .$m251$,'75939e2063c7d0e5d88339bcf655caca'),
(215,0,$m251$المادة 215$m251$,$m251$فى حالة كون عقار المفلس مسجلا ، يقوم أمين اتحاد الدائنين بإعلان القرار الصادر من قاضى التفليسة باتخاذ إجراءات البيع إلى مكتب الشهر العقارى أو إلى مكتب السجل العينى المختص للتأشير به بغير رسوم خلال مدة لا تجاوز أسبوعا من تاريخ إعلانهما على هامش سند ملكية المدين المفلس للعقار ، أو بصحيفة الوحدة العقارية مباشرة بحسب الأحوال ، وإعلان ذلك إلى جميع الدائنين المقيدة حقوقهم على العقار وإلى حائزه الفعلى .$m251$,'68c3de4f86b9d272069aaa08014c4108'),
(216,0,$m251$المادة 216$m251$,$m251$يقوم التأشير بالقرار الصادر من قاضى التفليسة فى مكتب الشهر العقارى أو مكتب السجل العينى مقام تسجيل تنبيه نزع الملكية .$m251$,'1dd04f4c6f8941e57cfd5818451c87a9'),
(217,0,$m251$المادة 217$m251$,$m251$يصدر قاضى التفليسة قرارا بتعيين خبير من خبراء التقييم المقيدة أسماؤهم بجدول خبراء إدارة الإفلاس وله عند الاقتضاء تعيين خبير آخر ، وذلك لتقييم المبيع وفقا للمعايير الآتية :
(أ) قيمة المبيع عند شرائه .
(ب) التعديلات التى طرأت على المبيع .
(ج) أثر معدلات التضخم على المبيع .
(د) القيمة السوقية وقت التقييم .
(هـ) القيمة الإيجارية للمبيع وقت التقييم .$m251$,'a1dabdddd46190d27ced6bc91db522ba'),
(218,0,$m251$المادة 218$m251$,$m251$يضع أمين التفليسة أو أمين اتحاد الدائنين ، بحسب الأحوال ، قائمة شروط البيع بالمزاد العلنى ، ويقوم بإيداعها قلم كتاب المحكمة المختصة بعد اعتمادها من قاضى التفليسة خلال ثلاثين يوما من تاريخ صدور قرار قاضى التفليسة بمباشرة إجراءات البيع ، على أن تتضمن ما يأتى :
1 - تعيين الشىء المبيع مع تحديد البيانات التى تفيد فى بيان أوصافه ، وتحديد مساحته وموقعه وحدوده فى حالة بيع العقار .
2 - تاريخ إذن أو قرار قاضى التفليسة بمباشرة إجراءات البيع .
3 - تاريخ وساعة ومكان إجراءات البيع .
4 - شروط البيع والثمن الأساسى لبدء المزايدة وتحديد مقادير التدرج فى العروض .
5 - تجزئة المبيع إلى صفقات إذا كان لذلك محل ، مع ذكر الثمن الأساسى لكل صفقة .
6 - مقدار تأمين الاشتراك فى المزاد ، على ألا يقل عن واحد فى المائة ولا يجاوز خمسة فى المائة من الثمن الأساسى للمبيع وذلك نقدا أو بموجب شيك مقبول الدفع .
7 - قيمة إيجار القاعة التى ستتم فيها إجراءات البيع سواء بالمحكمة أو خارجها .
8 - تحديد النسبة المئوية التى يتحملها الراسى عليه المزاد والتى تحصل لحساب إجراءات التفليسة ، ليخصم منها النسبة المقررة لأمين التفليسة أو أمين اتحاد الدائنين - بحسب الأحوال - وخبراء التقييم وفقا لقرار قاضى التفليسة وبما لا يجاوز ثلاثة فى المائة من قيمة مبلغ رسو المزاد .
9 - إلزام الراسى عليه المزاد بسداد كافة الرسوم القضائية المقررة على بيع العقارات والمنقولات قبل استلام المبيع .
10 - تحديد تاريخ الجلسة المحددة للنظر فيما يحتمل تقديمه من الاعتراضات على القائمة أو الملاحظات عليها قبل الجلسة المحددة للبيع بأسبوعين على الأكثر .
وتتولى المحكمة المختصة وفقا للتعريف المنصوص عليه بالمادة (1) من هذا القانون نظر جميع الدعاوى التى تنشأ عن عقد البيع فى هذه الحالة .$m251$,'572643ccff904310126ce4c5b86edf61'),
(219,0,$m251$المادة 219$m251$,$m251$يقوم أمين التفليسة أو أمين اتحاد الدائنين - بحسب الأحوال - بالنشر عن إيداع قائمة شروط البيع فى إحدى الصحف اليومية واسعة الانتشار أو بأية وسيلة أخرى يحددها قاضى التفليسة ، وفى حالة بيع عقار المفلس يتم لصق الإعلانات على العقار .$m251$,'ca7951ccb526a3e2869e8fa0011c16e7'),
(220,0,$m251$المادة 220$m251$,$m251$يجوز لكل ذى مصلحة الاعتراض على قائمة شروط البيع وذلك بالتقرير به فى قلم كتاب المحكمة المختصة قبل الجلسة المحددة لنظر الاعتراضات بثلاثة أيام على الأقل ، وإلا سقط حقه فى التمسك بالاعتراض ، وتقضى المحكمة فى الاعتراض بموجب حكم لا يجوز الطعن عليه ، وذلك قبل الجلسة المحددة للبيع .$m251$,'4fe59c50287d15f879ef8f51c10f7c82'),
(221,0,$m251$المادة 221$m251$,$m251$يتحمل أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال مصاريف إعادة إجراءات المزاد والبيع إذا كان ذلك راجعا إلى خطئه . ولا يجوز الطعن على قرار قاضى التفليسة الصادر فى هذا الشأن .$m251$,'5a93e6dc284a7fd36820256dee845037'),
(222,0,$m251$المادة 222$m251$,$m251$يتولى أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال ، فى حضور قاضى التفليسة ، إجراء المزايدة فى اليوم المحدد للبيع . وتبدأ المزايدة بالنداء على الثمن الأساسى وتنتهى باعتماد قاضى التفليسة البيع على من تقدم بأكبر عرض ، ويعتبر العرض الذى لم يزايد عليه خلال ثلاث دقائق منهيا للمزايدة .$m251$,'8e2d8bdb58349ee9ef3c70cb94006f1e'),
(223,0,$m251$المادة 223$m251$,$m251$إذا كان العرض المقدم أقل من الثمن الأساسى أو لم يتقدم أحد الدائنين أو المتزايدين للمزاد ، جاز لقاضى التفليسة تأجيل المزاد إلى يوم آخر خلال الستين يوما التالية ، وله أن ينقص عشر الثمن الأساسى مرة بعد مرة كلما اقتضى الحال ذلك بما لا يجاوز مرتين ، يقوم بعدها قاضى التفليسة بإيقاف إجراءات البيع لحين تسويق المبيع بالكيفية التى يحددها وعرض الأمر على جماعة الدائنين . وعلى أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال الإعلان عن الجلسة المؤجل لها المزاد بالإجراءات المنصوص عليها بالمادة (219) من هذا القانون .$m251$,'d2ed5b82a456cb4cbfcf2d4287338a4d'),
(224,0,$m251$المادة 224$m251$,$m251$يجب على من يعتمد قاضى التفليسة عطاءه أن يودع ، حال انعقاد جلسة المزاد ، كامل الثمن الذى اعتمد والمصاريف ورسوم إجراء المزاد . ولقاضى التفليسة إعطاؤه مهلة لاستكمال السداد بعد استقطاع مبلغ التأمين بما لا يجاوز ثلاثة أشهر من تاريخ جلسة المزاد . فإذا لم يودع الراسى عليه المزاد الثمن كاملا خلال المدة المحددة ، يسقط حقه فى استرداد مبلغ التأمين ، وتعاد إجراءات المزاد بالشروط السابقة وفقا لآخر ثمن محدد .$m251$,'b058f0fa95af4cdc10e1611c247fa73b'),
(225,0,$m251$المادة 225$m251$,$m251$إذا كان المتزايد الراسى عليه المزاد دائنا وكان مقدار دينه ومرتبته يبرران إعفاءه من إيداع باقى الثمن ، أعفاه القاضى مع استنزال تلك القيمة من مقدار دينه المقبول عند إجراء التوزيعات .$m251$,'1ae834f69dc29e359c0ad77b828835e3'),
(226,0,$m251$المادة 226$m251$,$m251$يصدر قاضى التفليسة قرارا بتسليم المنقولات والعقارات غير المسجلة المبيعة للراسى عليه المزاد ، بعد سداد كامل الثمن وتقديمه ما يفيد سداد الرسوم المستحقة على المزاد . ويترتب على صدور القرار تطهير العقارات والمنقولات من كافة الديون والحقوق المترتبة عليها .$m251$,'b1905fa7b18cb85d25fb34b472608a5f'),
(227,0,$m251$المادة 227$m251$,$m251$يصدر قاضى التفليسة حكما بإيقاع البيع فى حالة بيع العقارات المسجلة دون غيرها بناء على ما تم من إجراءات وبعد سداد كامل الثمن ، على أن يتضمن الحكم قائمة شروط البيع وما اتبع من إجراءات يوم البيع ، ويجب أن يتضمن منطوق الحكم الأمر بتسليم العقار لمن حكم بإيقاع البيع عليه ، وذلك بعد تقديمه ما يفيد سداد الرسوم القضائية المستحقة على المزاد .$m251$,'af14bda82cb2dfc971d7104ce6da211e'),
(228,0,$m251$المادة 228$m251$,$m251$لا يجوز الطعن فى حكم إيقاع البيع إلا لعيب فى إجراءات المزايدة أو فى شكل الحكم ، ويرفع الطعن بالإجراءات المعتادة خلال خمسة عشر يوما من تاريخ صدور الحكم .$m251$,'0234759eca82370a7bcea721741567a7'),
(229,0,$m251$المادة 229$m251$,$m251$لمن حكم بإيقاع البيع عليه أن يشهر الحكم ما لم يطعن عليه ، على أن يتحمل مصاريف شهر الحكم ، ويترتب على هذا الشهر تطهير العقار من حقوق الامتياز والاختصاص والرهون الرسمية والحيازية وجميع الحقوق العينية التبعية . ويكون الحكم المشهر سندا بملكية من أوقع البيع عليه ، على ألا ينقل سوى ما كان للمدين المفلس من حقوق على العقار المبيع .$m251$,'b7df472101f4131dad2e056cd9f3ebf6'),
(230,0,$m251$المادة 230$m251$,$m251$لا يعلن قرار تسليم المنقولات المبيعة والعقارات غير المسجلة أو حكم إيقاع البيع ويجرى تنفيذه جبرا بمعرفة أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال ، بأن يكلف المدين أو الحائز أو الكفيل العينى أو الحارس بحسب الأحوال بالحضور فى مكان التسليم فى اليوم والساعة المحددين لإجرائه ، على أن يتم ذلك التكليف قبل اليوم المعين للتسليم بأسبوع على الأقل . وإذا كان فى العقار منقولات تعلق بها حق لغير المدين المفلس ، وجب على أمين اتحاد الدائنين أن يطلب من قاضى التفليسة اتخاذ التدابير اللازمة للمحافظة على حقوق أصحاب الشأن .$m251$,'dc254354d33b62c9eb779272e4ead506'),
(231,0,$m251$المادة 231$m251$,$m251$لا يترتب على رفع دعوى الاستحقاق ودعوى الاسترداد وقف إجراءات التنفيذ على العقار أو المنقول بحسب الأحوال ما لم تقض المحكمة المختصة بغير ذلك .$m251$,'05044433574be742d5e43a61d761bc27'),
(232,0,$m251$المادة 232$m251$,$m251$فى حالة وجود عقار للمدين المفلس بموجب عقد أو قرار تخصيص يتم اتخاذ إجراءات البيع أو التنازل عن حق التخصيص وفقا لأحكام وإجراءات بيع المنقولات والعقارات غير المسجلة الواردة فى هذا الباب . ويخطر أمين الاتحاد الجهة المانحة بقرار قاضى التفليسة بمباشرة إجراءات البيع للوقوف على الشروط الخاصة بالتنازل عن حق التخصيص وإدراجها بقائمة شروط البيع ، وعلى أمين اتحاد الدائنين اتخاذ إجراءات نقل التخصيص للراسى عليه المزاد بالجهة المانحة .$m251$,'e681db6ea661edaed579dc5891914688'),
(233,0,$m251$المادة 233$m251$,$m251$فى حالة بيع العقار المملوك على الشيوع لعدم إمكان القسمة بغير ضرر يجرى بيعه بذات الطرق الواردة بهذا الباب ، على أن تشتمل قائمة شروط البيع فضلا عن البيانات المذكورة فى المادة (218) من هذا القانون على بيان جميع الشركاء وموطن كل منهم . ويعلن أمين اتحاد الدائنين جميع الشركاء بإيداع قائمة شروط البيع ، ويكون لهم إبداء ما لديهم من اعتراضات وملاحظات على شروط البيع بطريق الاعتراض على القائمة .$m251$,'7b90429834dc87a116e79ce9384f3fd4'),
(234,0,$m251$المادة 234$m251$,$m251$يودع أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال المبالغ الناتجة عن بيع أموال المفلس خزينة المحكمة أو بنكا يعينه قاضى التفليسة وذلك فى يوم العمل التالى للتحصيل على الأكثر ، ويلزم بتعويض يقدره قاضى التفليسة إذا تأخر فى الإيداع ، وعليه أن يقدم إلى قاضى التفليسة بيانا بالمبالغ المذكورة خلال أسبوع من تاريخ الإيداع . ولا يجوز سحب تلك المبالغ أو غيرها مما يــودعه الغير حساب التفليسة إلا بأمر من قاضى التفليسة .$m251$,'8f70884575eef8522b38d68466f4cc7a'),
(235,0,$m251$المادة 235$m251$,$m251$تستنزل من المبالغ الناتجة عن بيع أموال المفلس الرسوم ومصاريف إدارة التفليسة والديون المستحقة على التفليسة والإعانات المقررة للمفلس ولمن يعولهم ، والمبالغ المستحقة للدائنين الممتازين ، ويوزع الباقى بين الدائنين بنسبة ديونهم المحققة قسمة غرماء .
وتجنب حصة الديون المتنازع فيها والديون التى قبلت مؤقتا وتحفظ حتى يتم الفصل فيها .$m251$,'6c0efe7f8e26dd13efb5720c4c02ed3b'),
(236,0,$m251$المادة 236$m251$,$m251$يجوز لقاضى التفليسة فى أية مرحلة كانت عليها التفليسة أن يأمر بإجراء توزيعات على الدائنين الذين حققت ديونهم ويعين مقدار المبلغ الذى يوزع . ويكون التوزيع بمقتضى قائمة يعدها أمين التفليسة أو أمين اتحاد الدائنين حسب الأحوال وتعتمد من قاضى التفليسة بإجراء التوزيع ، وله عند الاقتضاء أن يأمر بنشر قرار التوزيع فى صحيفة يومية .
ويجوز للمفلس ولكل ذى مصلحة الطعن أمام المحكمة المختصة فى قرار قاضى التفليسة الخاص بإجراء توزيعات على الدائنين ، وذلك خلال عشرة أيام تبدأ من تاريخ إيداع القائمة قلم الكتاب .$m251$,'e2eac0704f6c6b9ce0aa49b96711352b'),
(237,0,$m251$المادة 237$m251$,$m251$يؤشر أمين اتحاد الدائنين على سند الدين بالمبالغ المدفوعة . وفى جميع الأحوال ، يجب أن يعطى الدائن مخالصة على قائمة التوزيع .$m251$,'bc6656727ec8afd19a0c02fbd6fd9911'),
(238,0,$m251$المادة 238$m251$,$m251$إذا حصل توزيع ثمن العقارات أو المنقولات ، كان للدائنين المرتهنين أو الممتازين أو الحاصلين على اختصاص الذين لم يستوفوا حقوقهم كلها أو بعضها من ثمن العقارات والمنقولات المحملة بالتأمين أن يشتركوا فى قسمة الغرماء بالباقى لهم مع الدائنين العاديين فى توزيع الأموال التى يتعلق بها حق جماعة الدائنين بشرط أن تكون ديونهم قد حققت طبقا لأحكام هذا القانون . وإذا تبين عند التسوية النهائية أن ما حصل عليه أحدهم يزيد على مقدار دينه ، وجب استنزال الجزء الزائد ورده إلى جماعة الدائنين .$m251$,'53c582b2262a338f27db0863f4b1cc45'),
(239,0,$m251$المادة 239$m251$,$m251$فيما عدا حالة الإفلاس بالتدليس ، تعود بحكم القانون جميع الحقوق التى سقطت عن المفلس طبقا للمادة (111) من هذا القانون بعد انقضاء ثلاث سنوات من تاريخ انتهاء التفليسة .$m251$,'9ed50698bdc4126b04aef49a0ed5443a'),
(240,0,$m251$المادة 240$m251$,$m251$يجب الحكم برد الاعتبار إلى المفلس ولو لم ينقض الميعاد المنصوص عليه فى المادة (239) من هذا القانون ، إذا أوفى جميع ديونه من أصل ومصاريف وعوائد مدة لا تزيد على سنتين .
وإذا كان المفلس شريكا متضامنا فى شركة حكم بشهر إفلاسها فلا يرد إليه اعتباره وجوبا إلا إذا أوفى جميع ديون الشركة من أصل ومصاريف وعوائد مدة لا تزيد على سنتين .$m251$,'8e7705d5b2b30c1815d6934fe8c4dfb0'),
(241,0,$m251$المادة 241$m251$,$m251$يجوز الحكم برد الاعتبار إلى المفلس ولو لم ينقض الميعاد المنصوص عليه فى المادة (239) من هذا القانون فى الحالتين الآتيتين :
(أ) إذا حصل المفلس على صلح من دائنيه ونفذ شروطه ، ويسرى هذا الحكم على الشريك المتضامن فى شركة حكم بشهر إفلاسها إذا حصل هذا الشريك على صلح خاص به ونفذ شروطه .
(ب) إذا أثبت المفلس أن الدائنين قد أبرءوا ذمته من جميع الديون أو أنهم أجمعوا على الموافقة على رد اعتباره .$m251$,'d11f69c323271c5e70bfb4463ebbdaec'),
(242,0,$m251$المادة 242$m251$,$m251$إذا امتنع أحد الدائنين عن قبض دينه أو كان غائبا أو تعذر معرفة موطنه جاز ، إيداع الدين خزانة المحكمة . وتقوم شهادة الإيداع فيما يتعلق برد الاعتبار مقام التخالص .$m251$,'f71d35392658db3317c6fa19252a9638'),
(243,0,$m251$المادة 243$m251$,$m251$لا يرد الاعتبار إلى المفلس الذى صدر عليه حكم بالإدانة فى إحدى جرائم الإفلاس بالتقصير إلا بعد تنفيذ العقوبة المحكوم بها أو صدور عفو عنها أو انقضائها بمضى المدة .
ولا يرد الاعتبار إلى المفلس الذى صدر عليه حكم بالإدانة فى إحدى جرائم الإفلاس بالتدليس إلا بعد انقضاء مدة ست سنوات من تاريخ تنفيذ العقوبة المحكوم بها أو صدور عفو عنه .
وفى جميع الأحوال ، لا يجوز رد الاعتبار إلى المفلس إلا إذا كان قد أوفى جميع الديون المطلوبة منه من أصل ومصاريف وعوائد مدة لا تزيد على سنتين ، أو أجرى تسوية بشأنها مع الدائنين .$m251$,'41c50b956181781b1d7a5b0fbbb06f7c'),
(244,0,$m251$المادة 244$m251$,$m251$يرد الاعتبار إلى المفلس بعد وفاته بناء على طلب أحد الورثة ، وذلك طبقا للأحكام المنصوص عليها فى المواد السابقة .$m251$,'0fd4544b7acbf9ec3f4fa02bd494354e'),
(245,0,$m251$المادة 245$m251$,$m251$يقدم طلب رد الاعتبار مرفقا به المستندات المؤيدة له إلى قلم كتاب محكمة الإفلاس المختصة .
ويرسل قلم الكتاب فورا صورة من الطلب إلى النيابة العامة .
وينشر ملخص الطلب فى إحدى الصحف اليومية التى تصدر أو توزع فى دائرة المحكمة على نفقة المدين . ويجب أن يشتمل هذا الملخص على اسم المدين وتاريخ صدور حكم شهر الإفلاس وكيفية انتهاء التفليسة والتنبيه على الدائنين بتقديم اعتراضاتهم إن كان لها مقتض .$m251$,'801bb6cbbed80ff6fede740bfdc38330'),
(246,0,$m251$المادة 246$m251$,$m251$تودع النيابة العامة قلم كتاب المحكمة ، خلال ثلاثين يوما من تاريخ تسلمها صورة طلب رد الاعتبار ، تقريرا يشتمل على بيانات عن نوع الإفلاس والأحكام التى صدرت على المفلس فى جرائم الإفلاس أو المحاكمات أو التحقيقات الجارية معه فى هذا الشأن .$m251$,'ec19ca88e424b6b8336e3e789acd7088'),
(247,0,$m251$المادة 247$m251$,$m251$لكل دائن لم يستوف حقه أن يقدم اعتراضا على طلب رد الاعتبار خلال خمسة عشر يوما من تاريخ نشر الطلب فى الصحف . ويكون الاعتراض بتقرير كتابى يقدم إلى قلم كتاب المحكمة مرفقا به المستندات المؤيدة له .$m251$,'cae06540b6b6e25cb9bf5a65ccc79dba'),
(248,0,$m251$المادة 248$m251$,$m251$يقوم قلم كتاب المحكمة بعد انقضاء الميعاد المنصوص عليه فى المادة (247) من هذا القانون بإخطار الدائنين الذين قدموا معارضات فى طلب رد الاعتبار بتاريخ الجلسة المحددة لنظر الطلب .$m251$,'888dd1eead9345968f0aaa7b43bdaeb8'),
(249,0,$m251$المادة 249$m251$,$m251$تفصل المحكمة فى طلب رد الاعتبار بحكم انتهائى . وإذا قضت المحكمة برفض الطلب ، فلا يجوز تقديمه من جديد إلا بعد انقضاء سنة من تاريخ صدور الحكم .$m251$,'3d0611d3793cbdb42405fae359c0c643'),
(250,0,$m251$المادة 250$m251$,$m251$إذا أجريت قبل الفصل فى طلب رد الاعتبار تحقيقات مع المفلس بشأن إحدى جرائم الإفلاس أو أقيمت عليه الدعوى الجنائية بذلك ، وجب على النيابة العامة إخطار المحكمة فورا . وعلى المحكمة أن توقف الفصل فى طلب رد الاعتبار حتى انتهاء التحقيقات أو صدور الحكم النهائى فى الدعوى الجنائية .$m251$,'442649beb950e266225375744d676ddd'),
(251,0,$m251$المادة 251$m251$,$m251$إذا صدر على المدين حكم بالإدانة فى إحدى جرائم الإفلاس بعد صدور الحكم برد الاعتبار ، اعتبر هذا الحكم كأن لم يكن . ولا يجوز للمدين الحصول بعد ذلك على رد الاعتبار إلا بالشروط المنصوص عليها فى المادة (243) من هذا القانون .$m251$,'e2fa94d4b9b80f0cdbb9355b46d9f877'),
(252,0,$m251$المادة 252$m251$,$m251$يعد متفالسا بالتدليس كل تاجر توقف عن دفع ديونه فى الأحوال الآتية :
1 - إذا أخفى دفاتره أو أعدمها أو غيرها .
2 - إذا اختلس أو خبأ جزءا من ماله إضرارا بدائنيه .
3 - إذا اعترف أو جعل نفسه مدينا بطريق التدليس بمبالغ ليست فى ذمته حقيقة ، سواء كان ذلك ناشئا عن مكتوباته أو ميزانيته أو غيرهما من الأوراق أو عن إقراره الشفاهى أو عن امتناعه من تقديم أوراق أو إيضاحات مع علمه بما يترتب على ذلك الامتناع .$m251$,'95bac2fb35afc597f6b4e4e3e9cd98e9'),
(253,0,$m251$المادة 253$m251$,$m251$يعاقب المتفالس بالتدليس ومن شاركه فى ذلك بالسجن من ثلاث إلى خمس سنوات وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز خمسمائة ألف جنيه .$m251$,'8be11488e60ce3fc442dfdc2280697a1'),
(254,0,$m251$المادة 254$m251$,$m251$يعد متفالسا بالتقصير على وجه العموم كل تاجر أدى لخسارة دائنيه بسبب عدم حزمه أو تقصيره الجسيم ، وعلى الخصوص التاجر الذى يكون فى إحدى الأحوال الآتية :
1 - إذا رئى أن مصاريفه الشخصية أو مصاريف منزله باهظة .
2 - إذا حصل على الصلح بطريق التدليس .
3 - إذا استهلك مبالغ كبيرة فى القمار أو أعمال اليانصيب المحض أو فى أى أعمال وهمية .
4 - إذا اشترى بضائع ليبيعها بأقل من أسعارها حتى يؤخر إشهار إفلاسه ، أو اقترض مبالغ أو أصدر أوراقا مالية أو استعمل طرقا أخرى مما يؤدى لخسائر شديدة لحصوله على النقود حتى يؤخر إشهار إفلاسه .
5 - عدم تحريره الدفاتر الملزم قانونا بإمساكها أو عدم إجرائه الجرد المنصوص عليه فى القانون أو إذا كانت دفاتره غير كاملة أو غير منتظمة بحيث لا يعرف منها مركزه المالى .
6 - عدم إعلانه التوقف عن الدفع فى الميعاد أو عدم تقديمه الميزانية أو ثبوت عدم صحة البيانات الواجب تقديمها بمقتضى هذا القانون .
7 - عدم توجهه بشخصه إلى قاضى التفليسة عند عدم وجود الأعذار الشرعية أو عدم تقديمه البيانات التى يطلبها القاضى المذكور أو ظهور عدم صحة تلك البيانات .
8 - تأديته عمدا بعد توقفه عن الدفع مديونية أحد دائنيه أو تمييزه إضرارا بباقى الدائنين أو إذا سمح له بمزية خصوصية بقصد الحصول على قبوله الصلح .
9 - إذا حكم بإفلاسه قبل أن يقوم بالتعهدات المترتبة على صلح سابق .$m251$,'f588d8e2c2a6e285a6784f67fa270a26'),
(255,0,$m251$المادة 255$m251$,$m251$إذا أفلست شركة مساهمة أو شركة حصص ، يحكم على أعضاء مجلس إدارتها ومديريها بالعقوبات المقررة للتفالس بالتدليس إذا ثبت أنهم ارتكبوا أمرا من الأمور المنصوص عليها فى المادة (252) من هذا القانون أو إذا فعلوا ما يترتب عليه إفلاس الشركة بطريق الغش أو التدليس ، وعلى الخصوص إذا ساعدوا على توقف الشركة عن الدفع سواء بإعلانهم ما يخالف الحقيقة عن رأس المال المكتتب أو المدفوع أو بتوزيعهم أرباحا وهمية أو بأخذهم لأنفسهم بطريق الغش ما يزيد عن المرخص لهم به فى عقد الشركة .$m251$,'f2fe8215ad61163a289334f544126d01'),
(256,0,$m251$المادة 256$m251$,$m251$إذا أفلست شركة مساهمة أو شركة حصص يحكم على أعضاء مجلس إدارتها ومديريها بالعقوبة المقررة للتفالس بالتقصير فى الحالات الآتية :
1 - إذا ثبت أنهم ارتكبوا أمرا من الأمور المنصوص عليها فى البنود من الثالث إلى التاسع من المادة (254) من هذا القانون .
2 - إذا أهملوا بطريق الغش فى نشر عقد الشركة بالكيفية التى نص عليها القانون .
3 - إذا اشتركوا فى أعمال مغايرة لما هو منصوص عليه فى النظام الأساسى للشركة .$m251$,'e38172a6bfd22877c18fb4c90e7c5b16'),
(257,0,$m251$المادة 257$m251$,$m251$يعاقب المتفالس بالتقصير بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مائتى ألف جنيه .$m251$,'25eacfa8630a5e034ec71e8a75659e91'),
(258,0,$m251$المادة 258$m251$,$m251$فيما عدا أحوال الاشتراك المبينة قانونا ، يعاقب بالحبس وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز خمسمائة ألف جنيه أو بإحدى هاتين العقوبتين فى الحالات الآتية :
1 - كل شخص سرق أو أخفى أو خبأ كل أو بعض أموال المفلس من المنقولات أو العقارات ولو كان ذلك الشخص زوج المفلس أو من فروعه أو من أصوله أو أنسبائه الذين فى درجة الفروع والأصول .
2 - من لا يكونون من الدائنين ويشتركون فى مداولات الصلح بطريق الغش أو يقدمون ويثبتون بطريق الغش فى تفليسة سندات ديون صورية باسمهم أو باسم غيرهم .
3 - الدائنون الذين يزيدون قيمة ديونهم بطريق الغش أو يشترطون لأنفسهم مع المفلس أو غيره مزايا خصوصية فى نظير إعطاء صوتهم فى مداولات الصلح أو التفليسة أو الوعد بإعطائه أو يعقدون مشارطة خصوصية لنفعهم وإضرارا بباقى الدائنين .
4 - أمناء التفليسة الذين يختلسون شيئا أثناء تأدية عملهم .
ويحكم القاضى أيضا ومن تلقاء نفسه فيما يجب رده إلى جماعة الدائنين وفى التعويضات التى تطلب باسمهم إذا اقتضى الحال ذلك ولو فى حالة الحكم بالبراءة .$m251$,'83066c0c27c402de4e7fd00baa19fa04'),
(259,0,$m251$المادة 259$m251$,$m251$تسرى فى شأن جرائم الصلح الواقى من الإفلاس الأحكام الآتية :
1 - يعاقب المدين بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على خمسمائة ألف جنيه أو بإحدى هاتين العقوبتين إذا :
(أ) أخفى بسوء نية كل أمواله أو بعضها أو غالى فى تقديرها بقصد الحصول على الصلح .
(ب) ترك بسوء نية دائنا بدين وهمى أو ممنوعا أو مغالى فى دينه يشترك فى مداولات الصلح والتصويت عليها أو مكنه من ذلك .
(ج) أغفل بسوء نية ذكر دائن فى قائمة الدائنين .
2 - يعاقب الدائن بالعقوبة المنصوص عليها بالفقرة السابقة إذا اشترك بسوء نية فى مداولات الصلح والتصويت عليه وهو ممنوع من هذا الاشتراك ، أو كان دينه مغالى فيه ، أو قرر له المدين أو أى شخص آخر مزايا خاصة مقابل تصويته مع الصلح .
3 - يعاقب أمين الصلح بذات العقوبة إذا قدم أو أقر بسوء نية ببيانات غير صحيحة عن حالة المدين .$m251$,'522af5722952f7fd3291c283d64ba0b3'),
(260,0,$m251$المادة 260$m251$,$m251$لا يترتب على إقامة الدعوى الجنائية بالإفلاس بالتدليس أو بالتقصير أى تعديل فى الأحكام الخاصة بإجراءات التفليسة إلا إذا نص القانون على غير ذلك .$m251$,'3c007108cf5724009e2a8e0e9eed3a6d'),
(261,0,$m251$المادة 261$m251$,$m251$فى حالة إقامة الدعوى الجنائية على المفلس ، يجب على أمين التفليسة أن يقدم للنيابة العامة أو للمحكمة ، كل ما تطلبه من وثائق أو مستندات أو معلومات أو إيضاحات تتعلق بالتفليسة .
وتبقى الوثائق والمستندات المذكورة أثناء التحقيق أو المحاكمة لدى النيابة العامة أو المحكمة وترد بعد انتهاء التحقيق أو المحاكمة إلى أمين التفليسة أو إلى المدين أو ورثته على حسب الأحوال .$m251$,'267961c0d600813284563402d422c3d1'),
(262,0,$m251$المادة 262$m251$,$m251$إذا كانت الجريمة تتعلق باتفاق عقده المدين أو أى شخص مع أحد الدائنين لمنح هذا الدائن مزايا خاصة مقابل التصويت على الصلح ، جاز للمحكمة الجنائية أن تقضى من تلقاء ذاتها بإبطال هذا الاتفاق وبالإلزام الدائن برد ما استولى عليه بمقتضاه ولو صدر الحكم فى الجريمة بالبراءة . وللمحكمة أن تقضى أيضا بناء على طلب ذوى الشأن بالتعويض عند الاقتضاء .$m251$,'4e652a8be097dd0767ef528ed9b07fc9');

INSERT INTO m251_ver VALUES
(0,0,1,$m251$قانون رقم 11 لسنة 2018 بإصدار قانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس
باسم الشعب
رئيس الجمهورية
قرر مجلس النواب القانون الآتى نصه ، وقد أصدرناه :$m251$,'988bc67dab451d464bc80aae8776129e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(1,-1,1,$m251$يعمل بأحكام القانون المرافق فى شأن إعادة الهيكلة والإفلاس والصلح الواقى منه .
وتسرى أحكامه على التاجر وفقا للتعريف الوارد فى المادة ( 10 ) من قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 ، وذلك فيما عدا شركات المحاصة وشركات القطاع العام وشركات قطاع الأعمال العام .$m251$,'1180ab2277e6f9eb32a8122c48257493',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(2,-1,1,$m251$يصدر وزير العدل اللوائح والقرارات اللازمة لتطبيق أحكام القانون المرافق خلال ثلاثة أشهر من تاريخ العمل به .$m251$,'ab4b93a4c05ffa3e611ae97225033a65',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(3,-1,1,$m251$تسرى أحكام قانون المرافعات المدنية والتجارية ، وقانون الإثبات فى المواد المدنية والتجارية وذلك فيما لم يرد بشأنه نص خاص فى القانون المرافق .$m251$,'69d5acf7f9ecfca8b32646e50cad7627',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(4,-1,1,$m251$تحيل المحاكم من تلقاء نفسها ما قد يوجد لديها من إجراءات التفليسة والمنازعات والتظلمات فى تلك الإجراءات ، وكافة الدعاوى الناشئة عن الإفلاس إلى المحكمة الاقتصادية المختصة ، بالحالة التى تكون عليها دون رسوم ، وذلك فيما عدا المنازعات المحكوم فيها والمؤجلة للنطق بالحكم أو القرار .
وتخضع إجراءات التفليسة التى لم تكتمل قبل العمل بأحكام هذا القانون للإجراءات الواردة بأحكام القانون المرافق .$m251$,'65f78a61ed7385b21fa109bae65c9601',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(5,-1,1,$m251$يلغى الباب الخامس من قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 ، كما يلغى كل حكم يخالف أحكام القانون المرافق .$m251$,'67a3ea21056292ed00766a67aaf7ab2f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(6,-1,1,$m251$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد مرور ثلاثين يوما من تاريخ نشره .$m251$,'399226acd4241beafe1c48d0956ee7a2',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(1,0,1,$m251$فى تطبيق أحكام هذا القانون ، يقصد بالعبارات والكلمات التالية المعانى الموضحة قرين كل منها :
إدارة الإفلاس : الإدارة المنشأة بموجب هذا القانون داخل كل محكمة اقتصادية لتلقى طلبات إعادة الهيكلة ، والصلح الواقى من الإفلاس ، وشهر الإفلاس ، ومباشرة إجراءات الوساطة .
قاضى الإفلاس : أحد قضاة إدارة الإفلاس يختص بفحص الطلبات المعروضة على الإدارة .
المحكمة المختصة : الدائرة الابتدائية بالمحكمة الاقتصادية المختصة بنظر الدعاوى والمنازعات الناشئة عن تطبيق أحكام هذا القانون .
التدابير التحفظية : التدابير الضرورية التى تتخذها المحكمة أو القاضى وفقا لأحكام هذا القانون بهدف حفظ أو إدارة أصول المدين على نحو آمن ، أو منع المفلس من الهرب أو إخفاء أمواله .
الوساطة : وسيلة ودية لتسوية المنازعات التجارية عن طريق وسيط (قاضى الإفلاس) ، يتولى تقريب وجهات النظر بين الأطراف المتنازعة بمناسبة علاقة عقدية أو غير عقدية ، ويقترح عليهم الحلول الملائمة لها .
الصلح الواقى : طلب يتوقى به المدين سيئ الحظ إشهار إفلاسه .
أمين الصلح : المسئول عن مباشرة إجراءات الصلح بين طالب الصلح الواقى من الإفلاس والدائنين ومتابعتها .
قاضى الصلح : القاضى المعين لمباشرة إجراءات الصلح الواقى من الإفلاس .
الرقيب : الشخص المعين لمراقبة تنفيذ عقد الصلح الواقى من الإفلاس .
أمين التفليسة : الممثل القانونى للتفليسة الذى تعينه المحكمة لإدارتها .
المراقب : الشخص الذى يتم اختياره لمراقبة أعمال التفليسة .
قاضى التفليسة : القاضى المعين لمباشرة إجراءات التفليسة .
أمين اتحاد الدائنين : ممثل التفليسة الذى يتم اختياره من قبل الدائنين عند قيام حالة اتحاد الدائنين بإيداع قائمة الديون المقبولة .
الخبراء : الأشخاص والمكاتب والشركات المقيدون بجدول خبراء إدارة الإفلاس .
إعادة الهيكلة : الإجراءات التى تساعد التاجر على خروجه من مرحلة الاضطراب المالى والإدارى .
لجنة إعادة الهيكلة : اللجنة المشكلة من بين الخبراء المقيدين بالجدول المنصوص عليه فى المادة (13) من هذا القانون لإعداد خطة إعادة الهيكلة .
المعاون : الشخص المسئول عن معاونة التاجر على تقويم وضعه المالى والإدارى ، ومتابعة تنفيذ خطة إعادة الهيكلة ، وفقا لأحكام هذا القانون .$m251$,'7efcafd7b52fabb3bc97db2e7f509e84',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(2,0,1,$m251$تختص الدوائر الابتدائية بالمحاكم الاقتصادية التى يقع فى دائرتها موطن تجارى للمدين أو المركز الرئيسى للشركة بنظر الدعاوى التى تنشأ عن تطبيق أحكام هذا القانون ، فإذا كان هذا المركز خارج مصر اختصت المحكمة التى يقع فى دائرتها مركز الإدارة المحلى .
وإذا لم يكن للتاجر موطن تجارى كانت المحكمة المختصة هى التى يقع فى دائرتها محل إقامته المعتادة ، ويعد موطنا مختارا للتاجر آخر موطن مثبت بالسجل التجارى . ومع عدم الإخلال بالاتفاقات الدولية النافذة فى مصر ، يجوز شهر إفلاس التاجر الذى يكون له فى مصر فرع أو وكالة ولو لم يصدر حكم بشهر إفلاسه فى دولة أجنبية ، وفى هذه الحالة تكون المحكمة المختصة بشهر الإفلاس فى مصر هى التى يقع فى دائرتها الفرع أو الوكالة .$m251$,'4ceec535a33043f3ffb5464207c94e76',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(3,0,1,$m251$استثناء من حكم المادة (8) من قانون المحاكم الاقتصادية الصادر بالقانون رقم 120 لسنة 2008 تنشأ بكل محكمة اقتصادية إدارة تسمى (إدارة الإفلاس) ، تشكل برئاسة قاض بمحكمة الاستئناف على الأقل وعضوية عدد كاف من قضاتها بدرجة رئيس محكمة على الأقل يسمون (قضاة الإفلاس) ، تختارهم جمعيتها العامة فى بداية كل عام قضائى ، ويلحق بها عدد كاف من خبراء إدارة الإفلاس والإداريين والكتابيين .$m251$,'60c19a7931f8c9ca7f16e647f6bc0d15',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(4,0,1,$m251$تختص إدارة الإفلاس بالآتى :
(أ) مباشرة إجراءات الوساطة فى طلبات إعادة الهيكلة والصلح الواقى من الإفلاس وشهر الإفلاس .
(ب) استيفاء مستندات الطلبات التى تختص بها محكمة الإفلاس وتحضيرها وإعداد مذكرة بطلبات الخصوم وأسانيدهم ، وذلك خلال مدة لا تجاوز ستين يوما من تاريخ قيد الطلب .$m251$,'226c846d5730c0d2d4bc4f529c96fd10',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(5,0,1,$m251$تقدم الطلبات إلى رئيس إدارة الإفلاس بعد قيدها بقلم كتاب المحكمة المختصة ، ويقوم بعرض الطلبات على قضاة الإفلاس لاتخاذ إجراءات الوساطة فيها على أن ينتهى من ذلك خلال ثلاثين يوما من تاريخ تقديم الطلب . ولرئيس الإدارة مد هذه المدة لمدة مماثلة ، وذلك لمرة واحدة على الأكثر .$m251$,'02b9e96907a1bbae9425b0c53a942bb6',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(6,0,1,$m251$يتعين على قاضى الإفلاس الحفاظ على سرية كافة المعلومات المتعلقة بإجراءات الوساطة ، ما لم يكن إفشاؤها لازما بمقتضى القانون أو لأغراض إنفاذ التسوية .$m251$,'eaa01b783bae8d460b58ec5a90b22fab',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(7,0,1,$m251$يشترط لانعقاد جلسات الوساطة حضور أطراف النزاع أو وكيل عنهم بموجب توكيل خاص يبيح له تسوية النزاع .
ويجوز لقاضى الإفلاس أن يجرى الوساطة بالطريقة التى يراها مناسبة مع مراعاة طلبات الأطراف وظروف الوساطة ، وله فى ذلك الاجتماع مع أطراف النزاع أو وكلائهم أو الانفراد بكل طرف على حدة ، واتخاذ ما يراه مناسبا لتقريب وجهات النظر بهدف الوصول إلى اتفاق تسوية ملزم للطرفين .$m251$,'d2c8533a2129fe835794d2c89ff4db5e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(8,0,1,$m251$يجوز لقاضى الإفلاس الاستعانة بمن يراه لازما لاستكمال إجراءات الوساطة بما فى ذلك خبراء لجنة إعادة الهيكلة وله تكليف أى من طرفى النزاع بسداد أمانة الخبير .$m251$,'924d7a5ab2c1f602dc39d4c9e483ad65',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(9,0,1,$m251$إذا تم التوصل إلى تسوية النزاع ، يحرر اتفاق تسوية يوقع عليه كافة الأطراف ، ويبين فيه تفاصيل الاتفاق ، وما تم من إجراءات الوساطة . ويصدر قاضى الإفلاس قرارا باعتماد التسوية وإنهاء الطلب ، ويكون لهذا الاتفاق قوة السند التنفيذى .$m251$,'a411be63683bacdeb49ddc34b2ccb7c5',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(10,0,1,$m251$إذا لم يتم التوصل إلى التسوية ، يرفض قاضى الإفلاس الطلب ويحدد له جلسة أمام المحكمة المختصة ويكلف من قدمه بإعلان ذوى الشأن ، وذلك بصحيفة تودع قلم الكتاب .$m251$,'ad25919ee7fe805aa3f449cdc6d65dcb',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(11,0,1,$m251$فى حالة عدم حضور مقدم الطلب أمام قاضى الإفلاس جلستين ، يأمر القاضى بحفظ الطلب .$m251$,'382718dbdbe410d14398f7709a2fb1af',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(12,0,1,$m251$قرارات قاضى الإفلاس نهائية لا يجوز الطعن عليها ، ما لم ينص القانون على خلاف ذلك ، أو كان القرار مما يجاوز اختصاصه ويكون الطعن فى هذه الحالة أمام المحكمة المختصة خلال عشرة أيام من تاريخ صدور القرار .$m251$,'62a49ad6c62d58cf81f8e4262155cadf',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(13,0,1,$m251$ينشأ جدول يلحق بجداول خبراء المحاكم الاقتصادية يسمى (جدول خبراء إدارة الإفلاس) يقيد به عدد كاف من المكاتب والشركات المتخصصة فى مجال إعادة الهيكلة وإدارة الأصول وخبراء من وزارات المالية والاستثمار والتجارة والصناعة والقوى العاملة والبنك المركزى المصرى والهيئة العامة للاستثمار والهيئة العامة للرقابة المالية والبورصة المصرية والاتحاد العام للغرف التجارية المصرية واتحاد الصناعات المصرية وأمناء التفليسة والخبراء المثمنين وغيرهم عند الاقتضاء .
ويصدر الوزير المختص اللائحة المنظمة لاختيارهم ، وقيدهم ، وكيفية مباشرتهم لعملهم ، ومساءلتهم ، والحدين الأقصى والأدنى لمقابل ما يؤدونه من أعمال .$m251$,'55c94c7899cbcd2d0c4fa9f9c4ffe5cd',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(14,0,1,$m251$للقاضى المختص فى أى مرحلة يكون عليها النزاع تشكيل لجنة تسمى (لجنة إعادة الهيكلة) من الخبراء المقيدين بجدول خبراء إدارة الإفلاس ، وتختص هذه اللجنة بوضع خطة إعادة الهيكلة وإدارة أصول التاجر وتقييمها بالإضافة إلى ما تكلف به من أعمال أخرى .
ويتولى القاضى المختص تقدير أتعاب اللجنة .$m251$,'8fac33f77f594b59333fefcaa4a5ae9f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(15,0,1,$m251$لكل تاجر ، لا يقل رأسماله عن مليون جنيه ، وزاول التجارة بصفة مستمرة خلال السنتين السابقتين على تقديم الطلب ولم يرتكب غشا أن يطلب إعادة الهيكلة .
ولا تجوز إعادة هيكلة الشركة وهى فى دور التصفية .$m251$,'1b879af92ed1b57db2ce83a6162303a4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(16,0,1,$m251$تجوز إعادة هيكلة نشاط أو أموال التاجر بعد وفاته بناء على طلب ورثته خلال السنة التالية للوفاة ، شريطة موافقة جميع الورثة .$m251$,'d556b9ef62b0b2c79aee590d2b23195e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(17,0,1,$m251$لا يجوز التقدم بطلب إعادة الهيكلة فى حالة صدور حكم بشهر إفلاس التاجر أو الحكم بافتتاح إجراءات الصلح الواقى منه .
ويترتب على تقديم طلب إعادة الهيكلة وقف طلبى شهر الإفلاس والصلح الواقى منه إلى حين انتهاء البت فى طلب إعادة الهيكلة .
ولا يجوز تقديم طلب آخر بإعادة الهيكلة إلا بعد مرور ثلاثة أشهر من رفض أو حفظ الطلب السابق .$m251$,'8bc0ebcb9de0fd0706d944606134a72c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(18,0,1,$m251$تهدف إعادة الهيكلة إلى وضع خطة لإعادة تنظيم أعمال التاجر المالية والإدارية تتضمن كيفية خروجه من مرحلة الاضطراب المالى والإدارى وسداد ديونه مع بيان مصادر التمويل المقترحة ، ويكون ذلك بعدة طرق منها إعادة تقييم الأصول ، وإعادة هيكلة الديون ومنها ديون الدولة ، وزيادة رأس المال ، وزيادة التدفقات النقدية الداخلية وخفض التدفقات النقدية الخارجية ، وإعادة الهيكلة الإدارية .$m251$,'bbe49e0a35633c25188d56a39df5ae3c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(19,0,1,$m251$يقدم طلب إعادة الهيكلة مبينا فيه أسباب الاضطراب المالى وتاريخ نشأته وما اتخذ فى شأنه من إجراءات لتجنب حدوثه أو معالجة آثاره وما يراه من إجراءات لازمة للخروج منه .
ويجب أن يرفق بالطلب المستندات الآتية :
(أ) الوثائق المؤيدة للبيانات المذكورة فيه .
(ب) شهادة من مكتب السجل التجارى تثبت قيام التاجر بما تفرضه الأحكام الخاصة بالسجل التجارى خلال السنتين السابقتين على طلب إعادة الهيكلة .
(ج) شهادة من الغرفة التجارية تفيد مزاولة التجارة بصفة مستمرة خلال السنتين السابقتين على طلب إعادة الهيكلة .
(د) صورة من الميزانية وحساب الأرباح والخسائر عن السنتين السابقتين على طلب إعادة الهيكلة .
(هـ) بيان بإجمالى المصروفات الشخصية فى السنتين السابقتين على طلب إعادة الهيكلة عدا الطلب المقدم من إحدى شركات المساهمة .
(و) بيان تفصيلى بالأموال المنقولة وغير المنقولة وقيمتها التقريبية عند طلب إعادة الهيكلة .
(ز) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم والتأمينات الضامنة لها .
(ح) شهادة تفيد عدم تقدمه بطلب إعادة هيكلة من قبل ، أو تقدمه بطلب سبق حفظه ومرت فترة ثلاثة أشهر على ذلك .
(ط) شهادة بعدم شهر إفلاس التاجر أو عقد صلح واق منه .
وإذا كان الطلب خاصا بشركة وجب أن يرفق به فضلا عن الوثائق المذكورة فى الفقرة السابقة صورة من عقد الشركة ونظامها مصدقا عليها من مكتب السجل التجارى والوثائق المثبتة لصفة مقدم الطلب وقرار الشركاء أو الجمعية العامة بطلب إعادة الهيكلة ، وبيان بأسماء الشركاء المتضامنين وعناوينهم وجنسياتهم .
ويجب أن تكون تلك الوثائق مؤرخة وموقعة من الطالب ، وإذا تعذر تقديم بعضها أو استيفاء بياناتها وجب أن يتضمن الطلب أسباب ذلك .
وللقاضى إلزام مقدم الطلب خلال المدة التى يحددها بتقديم معلومات أو مستندات إضافية حول وضعه الاقتصادى والمالى .$m251$,'0dc2c9b5cf05ac2baff4fa4a9cf67dbe',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(20,0,1,$m251$ترفع لجنة إعادة الهيكلة تقريرا إلى قاضى الإفلاس ، خلال ثلاثة أشهر من تاريخ تقديم الطلب ، متضمنا رأيها عن سبب اضطراب أعمال التاجر وجدوى إعادة الهيكلة والخطة المقترحة لذلك ، ويجوز مدها بإذن قاضى الإفلاس ثلاثة أشهر أخرى ، على أن يتم تنفيذ خطة إعادة الهيكلة فى مدة لا تزيد على خمس سنوات .$m251$,'edf2c5fd7bf1cb27f94e9c3b237085bf',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(21,0,1,$m251$يعتمد قاضى الإفلاس خطة إعادة الهيكلة التى ترفعها لجنة إعادة الهيكلة بناء على موافقة الأطراف الموقعين عليها ، وتكون خطة إعادة الهيكلة فى هذه الحالة ملزمة لهم .
ويعين قاضى الإفلاس معاونا لمساعدة التاجر إذ رأى موجبا لذلك ، من بين الأمناء أو الخبراء المقيدين بجدول خبراء إدارة الإفلاس أو من غيرهم ممن يختاره الأطراف على أن يحدد أتعاب المعاون وفقا لما اتفق عليه الأطراف وفى حالة تعذر ذلك يحدد القاضى تلك الأتعاب .$m251$,'0b8c7d1a552e8c20bf390cb906fa4816',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(22,0,1,$m251$يقوم المعاون بجميع الأعمال التى يقتضيها الغرض من تعيينه ومنها :
(أ) معاونة التاجر على تقويم وضعه المالى والإدارى .
(ب) تقديم المشورة والدعم الفنى له .
(ج) وضع آلية تنفيذ إجراءات خطة إعادة الهيكلة .
(د) مساعدة التاجر فى التسوية الودية مع دائنيه .
(هـ) إعداد تقرير كل ثلاثة أشهر وعرضه على قاضى الإفلاس والأطراف لاطلاعهم على تقدم سير إجراءات خطة إعادة الهيكلة ومدى التزام التاجر بها .$m251$,'4adf16a03e3adda44a43f03fe06a05a4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(23,0,1,$m251$يجوز لقاضى الإفلاس استبدال المعاون بأجر من تلقاء نفسه أو بناء على طلب أى من أطراف خطة إعادة الهيكلة .$m251$,'c4bfb85598d73c95c64d4bd6d0c41301',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(24,0,1,$m251$يستمر التاجر فى إدارة أمواله طوال فترة إعادة الهيكلة ويظل مسئولا عما ينشأ عنها من التزامات أو تعاقدات سابقة أو لاحقة لتاريخ اعتماد خطة إعادة الهيكلة بما لا يخالف هذه الخطة .$m251$,'c8c09c90bcdaded51cecc7fbb964a22e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(25,0,1,$m251$لايجوز للتاجر القيام بأى من التصرفات التى تؤثر على مصالح الدائنين بما فى ذلك البيع الذى لا علاقة له بممارسة أعماله التجارية المعتادة والتبرع والهبة والاقتراض أو الإقراض أو أى من الأعمال المجانية والكفالات وأى رهن أو تأمين أو أى من الأعمال المماثلة ، بما يخالف خطة إعادة الهيكلة .$m251$,'efc9a1860894d43b031c3f488c30a233',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(26,0,1,$m251$يجوز لكل ذى مصلحة اللجوء إلى قاضى الإفلاس للنظر فى أى طلب يتعلق بخطة إعادة الهيكلة .$m251$,'296a46e271586d8525fd26133e1025a7',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(27,0,1,$m251$استثناء من حكم المادة ( 10 ) ، يأمر قاضى الإفلاس بحفظ طلب إعادة الهيكلة فى الأحوال التالية :
(أ) إذا تعذر الاتفاق على خطة إعادة الهيكلة .
(ب) إذا لم يرفق التاجر بطلبه المعلومات أو المستندات المبينة سلفا أو التى كلف بتقديمها خلال الأجل الذى حدد لذلك .
(ج) إذا لم يقم التاجر بسداد التكاليف والمصروفات اللازمة لإجراءات إعادة الهيكلة ومن بينها أتعاب المعاون أو إذا تبين أن موجوداته لا تكفى لسدادها .
(د) زوال الأسباب التى دعت التاجر إلى التقدم بطلب إعادة الهيكلة .
(هـ) إذا كانت إجراءات إعادة الهيكلة غير ملائمة للتاجر استنادا إلى البيانات والمستندات المقدمة مع الطلب أو استنادا إلى التقرير الذى تعده لجنة إعادة الهيكلة .
(و) إذا لم يتفق جميع الورثة على إعادة الهيكلة .$m251$,'2b93f078f9b2a0df00536fed6b64139c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(28,0,1,$m251$ينهى القاضى خطة إعادة الهيكلة بانتهاء تنفيذها أو تعذر ذلك أو الإخلال بها لأى سبب بناء على طلب أى من أطرافها .$m251$,'63bb3f6f28c2dc1d7716a5596e196a58',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(29,0,1,$m251$لايجوز بعد اعتماد خطة إعادة الهيكلة رفع دعوى بين التاجر وأى من الدائنين الموقعين ، تكون متعلقة بتلك الخطة أو السير فيها أو رفع الدعاوى الفردية أو اتخاذ الإجراءات القضائية ، وتوقف مدد التقادم المتعلقة بالدعاوى والمطالبات والديون الخاصة بهم ، وذلك كل لحين انتهاء خطة إعادة الهيكلة .$m251$,'ff303da6227b7e00a6fabdbcb4ea4413',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(30,0,1,$m251$لكل تاجر يجوز شهر إفلاسه ، ولم يرتكب غشا أو خطأ لايصدر عن التاجر العادى ، أن يطلب الصلح الواقى من الإفلاس إذا اضطربت أعماله المالية اضطرابا من شأنه أن يؤدى إلى توقفه عن الدفع .
وللتاجر الذى توقف عن دفع ديونه ولو طلب شهر إفلاسه ، أن يطلب الصلح الواقى من الإفلاس إذا توافرت فيه الشروط المذكورة فى الفقرة السابقة وقدم طلب الصلح خلال خمسة عشر يوما من تاريخ توقفه عن الدفع .
ويجوز إجراء الصلح الواقى من الإفلاس لكل شركة توافرت فيها الشروط المنصوص عليها فى الفقرتين السابقتين ، ومع ذلك لايجوز منح هذا الصلح لشركة فى دور التصفية .$m251$,'8697567486787e108c88494c26f55454',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(31,0,1,$m251$لا يقبل طلب الصلح الواقى من الإفلاس إلا إذا كان الطالب قد زاول التجارة بصفة مستمرة خلال السنتين السابقتين على تقديم الطلب وقام خلال هذه المدة بما تفرضه عليه الأحكام الخاصة بالسجل التجارى وبالدفاتر التجارية .
ولا يجوز للشركة طلب الصلح الواقى إلا بعد الحصول على إذن بذلك من أغلبية الشركاء أو من الجمعية العامة بحسب الأحوال .$m251$,'d806e859d7b6c3e0643a98342c41c11b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(32,0,1,$m251$لمن آل إليهم المتجر بطريق الإرث أو الوصية أن يطلبوا الصلح الواقى إذا قرروا الاستمرار فى التجارة وكان التاجر قبل وفاته ممن يجوز لهم طلب الصلح .
ويجب أن يطلب الورثة أو الموصى إليهم الصلح الواقى خلال ثلاثة أشهر من تاريخ الوفاة وإذا لم يتفق الورثة أو الموصى إليهم جميعا على طلب الصلح ، وجب على المحكمة أن تسمع أقوال من عارض منهم فى طلب الصلح ثم تفصل فيه وفقا لمصلحة ذوى الشأن .$m251$,'116b920cf76d1ad05010590af6c9c469',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(33,0,1,$m251$لايجوز للمدين أثناء تنفيذ الصلح الواقى أو إعادة الهيكلة أن يطلب صلحا آخر .$m251$,'41cab781ffceaeac90c18cee2faf6771',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(34,0,1,$m251$إذا قدم طلب إلى إدارة الإفلاس لشهر إفلاس المدين وطلب آخر بالصلح الواقى من الإفلاس ، فلا يجوز الفصل فى طلب شهر الإفلاس إلا بعد الفصل فى طلب الصلح .$m251$,'6a719117a0c405ec236493de30ebb2ef',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(35,0,1,$m251$يقدم طلب الصلح الواقى إلى رئيس إدارة الإفلاس بالمحكمة المختصة يبين فيه أسباب اضطراب الأعمال ومقترحات الصلح وضمانات تنفيذها .$m251$,'8ce9e0832cde5e4d0047d8af2d83bd0b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(36,0,1,$m251$يرفق بطلب الصلح الواقى المستندات الآتية :
(أ) الوثائق المؤيدة للبيانات المذكورة فيه .
(ب) شهادة من مكتب السجل التجارى تثبت قيام التاجر بما تفرضه الأحكام الخاصة بالسجل التجارى خلال السنتين السابقتين على طلب الصلح .
(ج) شهادة من الغرفة التجارية تفيد بمزاولة التجارة بصفة مستمرة خلال السنتين السابقتين على طلب الصلح .
(د) صورة من الميزانية وحساب الأرباح والخسائر عن السنتين السابقتين على طلب الصلح .
(هـ) بيان بإجمالى المصروفات الشخصية فى السنتين السابقتين على طلب الصلح عدا الطلب المقدم من إحدى شركات المساهمة .
(و) بيان تفصيلى بالأموال المنقولة وغير المنقولة وقيمتها التقريبية عند طلب الصلح .
(ز) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم والتأمينات الضامنة لها .
(ح) ما يفيد إيداع مبلغ عشرة آلاف جنيه خزينة المحكمة على ذمة مصروفات نشر ما يصدر من أحكام .
(ط) شهادة بعدم شهر إفلاس التاجر أو تقديم طلب إعادة الهيكلة .
وإذا كان الطلب خاصا بشركة وجب أن يرفق به فضلا عن الوثائق المذكورة فى الفقرة السابقة صورة من عقد الشركة ونظامها مصدقا عليها من مكتب السجل التجارى والوثائق المثبتة لصفة مقدم الطلب وصورة من قرار الشركاء أو الجمعية العامة بطلب الصلح وبيان بأسماء الشركاء المتضامنين وعناوينهم وجنسياتهم .
ويجب أن تكون تلك الوثائق مؤرخة وموقعة من طالب الصلح وإذا تعذر تقديم بعضها أو استيفاء بياناتها وجب أن يتضمن الطلب أسباب ذلك .
وللقاضى إلزام مقدم الطلب خلال المدة التى يحددها أن يقدم مستندات إضافية أو معلومات حول وضعه الاقتصادى والمالى .$m251$,'c9a836b2e0523326f2e7ad71b064b04a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(37,0,1,$m251$للمحكمة التى تنظر فى طلب الصلح أن تأمر باتخاذ التدابير اللازمة للمحافظة على أموال المدين إلى حين الفصل فى الطلب .
ويجوز للمحكمة أن تتخذ من الإجراءات ما يمكنها من الإحاطة بحالة المدين المالية وأسباب اضطرابها .
وتنظر المحكمة فى طلب الصلح فى غير علانية وعلى وجه الاستعجال وتفصل فى الطلب بحكم انتهائى .$m251$,'d7949d11886da8ab94887f26cdde3637',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(38,0,1,$m251$يجب أن تقضى المحكمة برفض طلب الصلح الواقى فى الأحوال الآتية :
(أ) إذا لم يقدم طالب الصلح الوثائق والبيانات المنصوص عليها فى المادة (36) من هذا القانون أو قدمها ناقصة دون مسوغ .
(ب) إذا سبق الحكم على التاجر بالإدانة فى إحدى جرائم الإفلاس بالتدليس أو فى جريمة التزوير أو السرقة أو النصب أو خيانة الأمانة أو إصدار شيك بدون مقابل وفاء أو اختلاس الأموال العامة ما لم يكن قد رد إليه اعتباره .
(ج) إذا اعتزل التجارة أو لجأ إلى الفرار .$m251$,'d72cb2292ad753d57f2a6fe40f7835a0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(39,0,1,$m251$إذا قضت المحكمة برفض طلب الصلح الواقى جاز أن تحكم على التاجر بغرامة لا تقل عن عشرين ألف جنيه ولا تجاوز مائة ألف جنيه إذا تبين لها أنه تعمد الإيهام باضطراب أعماله أو إحداث الاضطراب فيها .$m251$,'d2d1af23d101b8ff4563814c9c7e6895',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(40,0,1,$m251$إذا قضت المحكمة بقبول الصلح الواقى ، وجب أن تأمر بافتتاح الإجراءات ، ويجب أن يتضمن الحكم ما يأتى :
(أ) ندب أحد قضاة الصلح بالمحكمة للإشراف على إجراءاته .
(ب) تعيين أمين أو أكثر لمباشرة إجراءات الصلح ومتابعتها .
ويجوز للمحكمة أن تأمر فى حكم افتتاح إجراءات الصلح بأن يودع المدين خزينة المحكمة أمانة نقدية لمواجهة مصاريف الإجراءات ، ويجوز أن تقضى المحكمة بإلغاء إجراءات الصلح أو بوقفها إذا لم يودع المدين الأمانة فى الميعاد الذى عينته .$m251$,'0d060105a20cc52d3f0a41f3f0f17180',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(41,0,1,$m251$يعين أمين الصلح من بين الأشخاص أو الشركات المرخص لهم فى مزاولة مهنة أمين التفليسة ، ويدون أمين الصلح يوميا بيوم جميع الأعمال المتعلقة بالصلح فى دفتر خاص يضع قاضى الصلح توقيعه أو ختمه عليه ويؤشر بنهاية الدفتر بما يفيد انتهاءه ، ويجوز للمحكمة وأطراف الصلح الاطلاع عليه .$m251$,'d626b347e2a36d573aa9eb79e8175317',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(42,0,1,$m251$يجوز الطعن على قرارات قاضى الصلح بصحيفة تودع قلم كتاب المحكمة وتعلن لذوى الشأن خلال عشرة أيام من تاريخ إيداع القرار .
وتنظره المحكمة فى أول جلسة على ألا يشترك قاضى الصلح فى نظر الطعن .$m251$,'303c7d9a339d58a99f71abb00fa098a6',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(43,0,1,$m251$يترتب على الطعن وقف تنفيذ القرار حتى تفصل المحكمة فى أمره ، ما لم تأمر باستمرار تنفيذه .
وإذا رفضت المحكمة الطعن تحكم على الطاعن بغرامة لاتجاوز خمسين ألف جنيه ، إذا تبين لها أنها تعمد تعطيل تنفيذ قرار قاضى الصلح .$m251$,'ec573e39d994c18e2dd8b1ba48e2363a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(44,0,1,$m251$يخطر قلم الكتاب أمين الصلح بالحكم الصادر بتعيينه فور صدوره .
ويقوم أمين الصلح خلال خمسة أيام من تاريخ الإخطار بقيد الحكم بافتتاح إجراءات الصلح فى السجل التجارى ونشر ملخصه مصحوبا بدعوة الدائنين إلى الاجتماع فى صحيفة يومية يعينها قاضى الصلح .
وعلى أمين الصلح أن يرسل فى الميعاد المذكور فى الفقرة السابقة الدعوة إلى الاجتماع مرفقا بها مقترحات الصلح إلى الدائنين المعلومة عناوينهم .$m251$,'86cbcc13b86e38942dcc7a6c376fb711',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(45,0,1,$m251$يقوم قاضى الصلح فور صدور الحكم بافتتاح إجراءات الصلح بقفل دفاتر المدين ووضع توقيعه عليها .
ويباشر أمين الصلح خلال أربع وعشرين ساعة من وقت إخطاره بصدور الحكم إجراءات الجرد بحضور المدين وكاتب المحكمة .$m251$,'ad783f6e63160d036c396f612db4f939',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(46,0,1,$m251$يستمر المدين بعد صدور الحكم بافتتاح إجراءات الصلح قائما على إدارة أمواله بإشراف أمين الصلح ، وله أن يقوم بجميع التصرفات العادية التى تقتضيها أعماله التجارية ، ومع ذلك لايجوز الاحتجاج على الدائنين بالتبرعات التى يجريها المدين بعد صدور الحكم المذكور .
ولا يجوز للمدين بعد صدور الحكم بافتتاح إجراءات الصلح أن يعقد صلحا أو رهنا من أى نوع أو أن يجرى تصرفا ناقلا للملكية لا تستلزمه أعماله التجارية العادية إلا بعد الحصول على إذن من قاضى الصلح ، ومع عدم الإخلال بحقوق المتصرف إليه حسن النية ، لا يحتج على الدائنين بكل تصرف يتم على خلاف ذلك .$m251$,'bf9a3f1f84d47c5f82e2191e2a6f6bd8',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(47,0,1,$m251$توقف جميع الدعاوى وإجراءات التنفيذ الموجهة إلى المدين بمجرد الحكم بافتتاح إجراءات الصلح ، أما الدعاوى المرفوعة من المدين وإجراءات التنفيذ التى باشرها فتبقى سارية مع إدخال أمين الصلح فيها .
ولا يجوز بعد صدور الحكم بافتتاح إجراءات الصلح التمسك قبل الدائنين بقيد الرهون وحقوق الامتياز والاختصاص المقررة على أموال المدين .$m251$,'794dcc6b5e30e53521cdb734e2002842',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(48,0,1,$m251$لا يترتب على صدور الحكم بافتتاح إجراءات الصلح حلول آجال الديون التى على المدين أو وقف سريان عوائدها .$m251$,'9442bb3f42528a2b7288b4e299fc3038',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(49,0,1,$m251$إذا أخفى المدين بعد تقديم طلب الصلح جزءا من أمواله أو أتلفه أو أجرى بسوء نية تصرفات ضارة بالدائنين أو تصرفات مخالفة لأحكام المادة (46) من هذا القانون تقضى المحكمة من تلقاء ذاتها بإلغاء إجراءات الصلح .$m251$,'20171252067df0e847ee2bbc95d11ade',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(50,0,1,$m251$على جميع الدائنين ولو كانت ديونهم غير حالة أو مضمونة بتأمينات خاصة أو ثابتة بأحكام نهائية أن يسلموا أمين الصلح خلال خمسة عشر يوما من تاريخ نشر ملخص الحكم بافتتاح إجراءات الصلح فى الصحف أصول مستندات ديونهم مصحوبة ببيان هذه الديون وتأميناتها إن وجدت ومقدارها مقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزى بيعا أو إقفالا أو تحويلات أو بنكنوتا إذا لم يوجد سعر تحويلات يوم صدور الحكم ، ويرسل البيان والمستندات إلى أمين الصلح بكتاب مسجل مصحوبا بعلم الوصول .
ويكون الميعاد المذكور فى الفقرة السابقة ثلاثين يوما بالنسبة إلى الدائنين المقيمين خارج مصر .
ولا يضاف إلى الميعاد المذكور فى الفقرتين السابقتين ميعاد للمسافة .$m251$,'cfe935ef823e6fdc6f055338c5c2c6dc',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(51,0,1,$m251$يضع أمين الصلح بعد انتهاء الميعاد المنصوص عليه فى المادة ( 50 ) من هذا القانون قائمة بأسماء الدائنين الذين طلبوا الاشتراك فى إجراءات الصلح وبيانا بمقدار كل دين على حدة والمستندات التى تؤيده والتأمينات التى تضمنه إن وجدت وما يراه بشأن قبوله أو رفضه .
ولأمين الصلح أن يطلب من الدائن تقديم إيضاحات عن الدين أو تكملة مستنداته أو تعديل مقداره أو صفاته .$m251$,'2db128da914e5c246b32e6de2aa0ac69',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(52,0,1,$m251$على أمين الصلح إيداع قائمة الديون قلم كتاب المحكمة خلال أربعين يوما على الأكثر من تاريخ صدور حكم افتتاح إجراءات الصلح ، ويجوز عند الاقتضاء إطالة هذا الميعاد بقرار من قاضى الصلح .
ويقوم أمين الصلح فى اليوم التالى للإيداع بنشر بيان بحصول الإيداع فى صحيفة يومية واسعة الانتشار يحددها قاضى الصلح .
ولكل ذى مصلحة الاطلاع على القائمة المودعة قلم كتاب المحكمة .$m251$,'383f5995ec78b6aa1517ca40dd10bd20',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(53,0,1,$m251$للمدين ولكل دائن ورد اسمه بقائمة الديون أن ينازع فى الديون المدرجة بها خلال عشرة أيام من تاريخ النشر فى الصحف عن حصول الإيداع ، وتقدم المنازعة إلى قلم الكتاب ولا يضاف إلى هذا الميعاد ميعاد المسافة .$m251$,'59e24cd68e58de620916d812882fc041',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(54,0,1,$m251$يضع قاضى الصلح بعد انقضاء الميعاد المنصوص عليه فى المادة (53) من هذا القانون قائمة نهائية بالديون غير المتنازع عليها ويؤشر على البيان الخاص بالدين بما يفيد قبوله ومقدار المقبول منه .
ويجوز لقاضى الصلح اعتبار الدين متنازعا عليه ولو لم تقدم بشأنه أى منازعة .
ويفصل قاضى الصلح فى الديون المتنازع عليها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة .
ويخطر قلم كتاب المحكمة ذوى الشأن بميعاد الجلسة قبل انعقادها بثلاثة أيام على الأقل ، كما يبلغهم القرار الصادر فى المنازعة فور صدوره .$m251$,'dc812bb5caae751a6045165eda895f98',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(55,0,1,$m251$يجوز الطعن أمام المحكمة فى القرار الصادر من قاضى الصلح بقبول الدين أو رفضه خلال عشرة أيام من تاريخ إيداع القرار أو الإخطار به ، ولا يترتب على الطعن وقف إجراءات الصلح إلا إذا أمرت المحكمة بذلك .
ويجوز للمحكمة قبل الفصل فى الطعن أن تأمر بقبول الدين مؤقتا بمبلغ تقدره ولا يجوز قبول الدين مؤقتا إذا أقيمت بشأنه دعوى جنائية .
وإذا كانت المنازعة على الدين متعلقة بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا .$m251$,'b13a9c7dada2164d8171817518a2412d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(56,0,1,$m251$لا يجوز أن يشترك فى إجراءات الصلح الواقى الدائنون الذين لم يقدموا أصول مستندات ديونهم فى الميعاد المنصوص عليه فى المادة ( 50 ) من هذا القانون ولا الدائنون الذين لم تقبل ديونهم نهائيا أو مؤقتا .$m251$,'0cb85f540185836142743dada36de693',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(57,0,1,$m251$يعين قاضى الصلح بعد الانتهاء من تحقيق الديون ميعادا لاجتماع الدائنين للمداولة فى مقترحات الصلح ، وترسل الدعوة إلى حضور هذا الاجتماع إلى كل دائن قبل دينه نهائيا أو مؤقتا ، ويجوز لقاضى الصلح أن يأمر بنشر الدعوة فى صحيفة يومية يعينها .$m251$,'8fbcc8ea5b8c29eb9e2be16697e32d10',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(58,0,1,$m251$يودع أمين الصلح قلم كتاب المحكمة قبل الميعاد المعين لاجتماع الدائنين بخمسة أيام على الأقل تقريرا عن حالة المدين المالية وأسباب اضطرابها وبيانا بأسماء الدائنين الذين لهم الحق فى الاشتراك فى إجراءات الصلح ، ويجب أن يتضمن التقرير رأى أمين الصلح فى الشروط التى اقترحها المدين للصلح .
ويجوز لكل ذى مصلحة أن يطلب من قاضى الصلح الإذن له بالاطلاع على التقرير المذكور .$m251$,'97da89bf51d3a1c42dd8c5424efbab6e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(59,0,1,$m251$يتولى قاضى الصلح رئاسة اجتماع الدائنين .
ويجوز للدائن أن ينيب عنه وكيلا فى حضور الاجتماع ، ويجب أن يحضر المدين بنفسه أو ممثل الشركة المدينة بحسب الأحوال ، ولا يجوز أن يقيم عنه وكيلا فى الحضور بدلا منه إلا لعذر يقبله قاضى الصلح .
ولا تجوز المداولة فى شروط الصلح إلا بعد تلاوة تقرير أمين الصلح المشار إليه فى المادة (58) من هذا القانون ، ويجوز للمدين تعديل شروطه للصلح أثناء المداولة .$m251$,'cfdb2b2420677ba7f0df68280e1cbf07',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(60,0,1,$m251$لا يقع الصلح إلا بموافقة أغلبية الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا بشرط أن يكونوا حائزين لثلثى قيمة هذه الديون ، ولا يحسب فى هاتين الأغلبيتين الدائنون الذين لم يشتركوا فى التصويت كما لا تحسب ديونهم .
وإذا كان الصلح خاصا بشركة أصدرت سندات قرض أو صكوك تمويل تجاوز قيمتها ثلث مجموع ديونها فلا يجوز إجراء الصلح إلا إذا وافقت على ذلك الجمعية العامة لجماعة مالكى هذه السندات أو الصكوك .$m251$,'0c132e656f83d94d29d49695177609fb',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(61,0,1,$m251$لا يجوز لزوج طالب الصلح ولأقاربه حتى الدرجة الثانية الاشتراك فى مداولات الصلح أو التصويت على شروطه .
وإذا نزل أحد هؤلاء الدائنين المقبول دينهم نهائيا أو مؤقتا عن دينه إلى الغير بعد صدور الحكم بافتتاح إجراءات الصلح فلا يجوز للمتنازل إليه الاشتراك فى مداولات الصلح أو التصويت عليه .$m251$,'a585365631df66d5474e4cd81cf1b382',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(62,0,1,$m251$لا يجوز للدائنين أصحاب التأمينات العينية أو المنقولة المسجلة المقررة على أموال طالب الصلح الاشتراك فى التصويت على الصلح بديونهم المضمونة بالتأمينات المذكورة إلا إذا نزلوا عن هذه التأمينات مقدما ، ويجوز أن يكون التنازل مقصورا على جزء من التأمين بشرط ألا يقل عما يقابل ثلث الدين ، ويتم إثبات التنازل فى محضر الجلسة .
إذا اشترك أحد الدائنين المذكورين فى الفقرة السابقة فى التصويت على الصلح دون أن يصرح بالتنازل عن تأمينه كله أو بعضه اعتبر ذلك تنازلا عن التأمين بأجمعه .
وفى جميع الأحوال لا يكون التنازل عن التأمين نهائيا إلا إذا تم الصلح وصدقت عليه المحكمة .
وإذا أبطل الصلح عاد التأمين الذى شمله التنازل .$m251$,'e7ecd10edaa10a92cc5af65297e10e90',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(63,0,1,$m251$يوقع الصلح الواقى فى الجلسة التى تم فيها التصويت عليه وإلا كان لاغيا .
وإذا لم تتحقق إحدى الأغلبيتين المنصوص عليهما فى المادة ( 60 ) من هذا القانون تأجلت المداولة عشرة أيام لا مهلة بعدها .
ويجوز للدائنين الذين حضروا الاجتماع الأول أو كانوا ممثلين فيه ووقعوا محضر الصلح ألا يحضروا الاجتماع الثانى ، وفى هذه الحالة تبقى موافقتهم على الصلح فى الاجتماع الأول قائمة ونافذة فى الاجتماع الثانى إلا إذا حضروا هذا الاجتماع وعدلوا عن موافقتهم السابقة أو عدلوها أو إذا أدخل المدين تعديلا جوهريا فى مقترحاته بشأن الصلح فى الفترة بين الاجتماعين .$m251$,'7217aaed28879c71f2328dbb0182dee5',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(64,0,1,$m251$يحرر محضر بما تم فى جلسة الصلح يوقعه قاضى الصلح وأمين الصلح والمدين والدائنون الحاضرون .
ويجوز لكل دائن له حق الاشتراك فى مداولات الصلح أن يبلغ قاضى الصلح كتابة بما لديه من اعتراض على الصلح وأسبابه وذلك خلال عشرة أيام من تاريخ التوقيع على محضر الصلح .
وعلى قاضى الصلح خلال سبعة أيام من انقضاء الميعاد المنصوص عليه فى الفقرة السابقة أن يرسل محضر الصلح إلى المحكمة التى أصدرت الأمر بافتتاح إجراءات الصلح للتصديق عليه ، وذلك مع تقرير من القاضى عن حالة المدين المالية وأسباب اضطراب أعماله وشروط الصلح وبيان بالاعتراضات التى قدمت على الصلح وأسبابها .$m251$,'08ef5325042c9f0f0f3681be9b6edb01',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(65,0,1,$m251$يبلغ قلم كتاب المحكمة المدين والدائنين الذين قدموا اعتراضات على الصلح بميعاد الجلسة التى حددت لنظر هذه الاعتراضات وطلب التصديق على الصلح ، ويجوز لكل ذى مصلحة حضور هذه الجلسة .
وتفصل المحكمة فى الاعتراضات وفى طلب التصديق على الصلح بحكم واحد يكون نهائيا سواء أكان بقبول التصديق على الصلح أم برفض التصديق عليه .
ويجوز للمحكمة أن ترفض التصديق على الصلح ولو لم يقدم بشأنه أى اعتراض إذا وجدت أسباب تتصل بالمصلحة العامة أو بمصلحة الدائنين تبرر ذلك .
وإذا رفضت المحكمة الاعتراض على الصلح جاز لها الحكم على المعترض بغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرين ألف جنيه إذا تبين أنه تعمد تأخير الصلح .$m251$,'24e5f3e1c45371500e7c8007a887e707',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(66,0,1,$m251$يجوز أن يتضمن الصلح الواقى منح المدين آجالا لوفاء الديون أو الفوائد ، كما يجوز أن يتضمن إبراء المدين من جزء من الدين أو الفوائد .
ويجوز أن يعقد الصلح بشرط الوفاء إذا أيسر المدين خلال مدة تعين فى شروط الصلح على ألا تجاوز خمس سنوات من تاريخ التصديق على الصلح ، ولا يعتبر المدين قد أيسر إلا إذا زادت موجوداته على الديون المترتبة عليه بما يعادل عشرة فى المائة على الأقل ، وللدائنين أن يشترطوا تقديم ضمان عينى أو شخصى لتنفيذ شروط الصلح .$m251$,'775bd9638562db0d5cd3d609a1205e1f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(67,0,1,$m251$يشهر الحكم الصادر بالتصديق على الصلح الواقى وفقا للأحكام المقررة لشهر حكم الإفلاس .
ويجب أن يشتمل ملخص الحكم الذى ينشر فى الصحف على اسم المدين وموطنه ورقم قيده فى السجل التجارى والمحكمة التى صدقت على الصلح وتاريخ حكم التصديق .$m251$,'6f21bdcf4d31616062ce38239ffa664d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(68,0,1,$m251$يسرى الصلح الواقى من الإفلاس بمجرد صدور الحكم بالتصديق عليه على جميع الدائنين الذين تعتبر ديونهم عادية وفقا لأحكام الإفلاس ولو لم يشتركوا فى إجراءاته أو لم يوافقوا على شروطه .
ولا يفيد من الصلح الواقى المدينون المتضامنون مع المدين أو كفلاؤه فى الدين ومع ذلك إذا وقع الصلح مع شركة استفاد من شروطه الشركاء المسئولون فى جميع أموالهم عن ديون الشركة إلا إذا نص فى عقد الصلح على غير ذلك .
ولا يسرى الصلح على دين النفقة ولا على الديون التى نشأت بعد صدور الحكم بافتتاح إجراءات الصلح .$m251$,'e5934670c1df8406a64c519a6ca7c402',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(69,0,1,$m251$يجوز للمحكمة التى صدقت على الصلح أن تمنح المدين بناء على طلبه آجالا للوفاء بالديون التى لا يسرى عليها الصلح بشرط ألا تجاوز الآجال التى تمنحها المحكمة الأجل المقرر فى الصلح .
ولا يترتب على التصديق على الصلح حرمان المدين من الآجال التى تكون أبعد مدى من الأجل المقرر فى الصلح .$m251$,'c9d8fde259ae15a35d0e93c5a609ffb3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(70,0,1,$m251$تأمر المحكمة فى حكم التصديق على الصلح بناء على تقرير من قاضى الصلح باستبقاء أمين الصلح أو بتعيين رقيب من بين الدائنين أو من غيرهم لمراقبة تنفيذ شروط الصلح وإبلاغ المحكمة بما يقع من مخالفات لهذه الشروط .
ويؤشر أمين الصلح أو الرقيب بحسب الأحوال على سند الدين بالمبالغ المدفوعة ، وفى جميع الأحوال يجب أن يسلم الدائن مخالصة للمدين بما تم قبضه توقع من أمين الصلح أو الرقيب بحسب الأحوال ، تحت إشراف قاضى الصلح .
ويطلب الرقيب من المحكمة التى صدقت على الصلح خلال عشرة أيام من الانتهاء من تنفيذ شروط الصلح ، الحكم بقفل الإجراءات ، ويشهر هذا الطلب بالكيفية المنصوص عليها فى المادة (44) من هذا القانون .
ويصدر الحكم بقفل الإجراءات خلال ثلاثين يوما من تاريخ النشر فى الصحف ، ويقيد ملخصه فى السجل التجارى .$m251$,'fd8a4596a4a5e7c6734ef3f084988497',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(71,0,1,$m251$يبطل الصلح الواقى من الإفلاس إذا ظهر بعد التصديق عليه تدليس من جانب المدين ، ويعتبر تدليسا على وجه الخصوص إخفاء الأموال أو إخفاء الديون أو اصطناعها أو تعمد المبالغة فى مقدارها .
ويجب أن يطلب إبطال الصلح خلال ستة أشهر من اليوم الذى يظهر فيه التدليس وإلا كان الطلب غير مقبول ، وفى جميع الأحوال لا يكون الطلب مقبولا إذا قدم بعد انقضاء سنة من تاريخ صدور الحكم بالتصديق على الصلح .
ولا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بإبطال الصلح ، وتبرأ ذمة المدين بقدر ما تم سداده .
ويترتب على إبطال الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروط الصلح .
وتختص المحكمة التى أصدرت الحكم بالتصديق على الصلح بنظر دعوى إبطال الصلح .$m251$,'3e106a94cfceedd3ffc17111d3b5c71e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(72,0,1,$m251$للمحكمة بناء على طلب كل دائن تسرى عليه شروط الصلح أن تقضى بفسخ الصلح فى الأحوال الآتية :
(أ) إذا لم ينفذ المدين شروط الصلح كما اتفق عليها .
(ب) إذا تصرف المدين بعد التصديق على الصلح تصرفا ناقلا لملكية متجره دون مسوغ مقبول .
(ج) إذا توفى المدين وتبين أنه لا ينتظر تنفيذ الصلح أو إتمام تنفيذه .
ولا يلزم الدائنون برد ما قبضوه من ديونهم قبل الحكم بفسخ الصلح .
ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروطه ، ويجب تكليف الكفيل بحضور الجلسة التى ينظر فيها طلب فسخ الصلح .$m251$,'d184663d4b8eb0d4bbf2b2215f50e1b7',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(73,0,1,$m251$يقدر قاضى الصلح أجر كل من أمين الصلح والرقيب إذا كانا من غير الدائنين ، ويودع قرار القاضى فى هذا الشأن قلم كتاب المحكمة فى اليوم التالى لصدوره ، ويجوز لكل ذى مصلحة الاعتراض على القرار أمام المحكمة خلال خمسة عشر يوما من تاريخ الإيداع ، ويكون الحكم الصادر فى الاعتراض نهائيا .$m251$,'9c49b1a088f85135bd81e271f92d065a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(74,0,1,$m251$يجوز للمحكمة من تلقاء ذاتها أو بناء على تقرير من قاضى الصلح أن تأمر فى الحكم بقفل إجراءات الصلح بصرف مكافأة إجمالية للرقيب إذا كان من الدائنين وتبين أنه بذل فى عمله جهدا غير عادى وكانت حالة المدين المالية تسمح بذلك .$m251$,'8ef2f9fe0aae994dc73af4bb20fbfe04',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(75,0,1,$m251$يعد فى حالة إفلاس كل تاجر ملتزم بموجب أحكام قانون التجارة الصادر بالقانون رقم 17 لسنة 1999 بإمساك دفاتر تجارية إذا توقف عن دفع ديونه التجارية إثر اضطراب أعماله المالية .
ولا يترتب على التوقف عن الدفع أثر قبل صدور حكم شهر الإفلاس ، ما لم ينص القانون على غير ذلك .$m251$,'16d9e24676097c609f80fa6df89e4559',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(76,0,1,$m251$يشهر إفلاس التاجر بناء على طلبه أو طلب أحد الدائنين أو النيابة العامة ، ويجوز للمحكمة أن تقضى بشهر الإفلاس من تلقاء ذاتها .
ويجوز شهر إفلاس التاجر بعد وفاته أو اعتزاله التجارة إذا توفى أو اعتزل التجارة وهو فى حالة توقف عن الدفع . ويجب تقديم طلب شهر الإفلاس خلال السنة التالية للوفاة أو اعتزال التجارة . ولا يسرى هذا الميعاد فى حالة اعتزال التجارة إلا من تاريخ شطب اسم التاجر من السجل التجارى .
ويجوز لورثة التاجر طلب شهر إفلاسه بعد وفاته مع مراعاة الميعاد المذكور فى الفقرة السابقة . فإذا اعترض بعض الورثة على شهر الإفلاس وجب أن تسمع المحكمة أقوالهم ثم تفصل فى الطلب وفقا لمصلحة ذوى الشأن .
وتعلن صحيفة دعوى شهر الإفلاس فى حالة وفاة التاجر إلى الورثة جملة فى آخر موطن للمتوفى .
ولا تقبل دعوى الدائن بشهر إفلاس مدينه التاجر بموجب دين مضمون بالكامل بتأمين عينى أو منقول مسجل ما لم تكن قيمة الدين تزيد على قيمة الضمان .$m251$,'e6c5e4a1aa4331b53edf76a5b856be4d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(77,0,1,$m251$يجب على التاجر أن يطلب شهر إفلاسه خلال خمسة عشر يوما من تاريخ توقفه عن الدفع وذلك بطلب يقدم إلى إدارة الإفلاس يذكر فيه أسباب التوقف عن الدفع وترفق به الوثائق الآتية :
(أ) الدفاتر التجارية الرئيسية .
(ب) صورة من آخر ميزانية وحساب الأرباح والخسائر .
(ج) بيان بإجمالى المصروفات الشخصية عن السنتين السابقتين على تقديم طلب شهر الإفلاس أو عن مدة اشتغاله بالتجارة إذا كانت أقل من ذلك عدا الطلب المقدم من إحدى شركات المساهمة .
(د) بيان تفصيلى بما يملكه من عقارات ومنقولات وقيمتها التقريبية فى تاريخ التوقف عن الدفع ، وكذلك المبالغ النقدية المودعة باسمه لدى البنوك سواء فى مصر أو خارجها .
(هـ) بيان بأسماء الدائنين والمدينين وعناوينهم ومقدار حقوقهم أو ديونهم والتأمينات الضامنة لها .
(و) بيان بالاحتجاجات التى حررت ضد التاجر خلال السنتين السابقتين على تقديم طلب شهر الإفلاس .
(ز) شهادة بعدم صدور حكم بافتتاح صلح واق من الإفلاس ، أو ما يفيد عدم تقدمه بطلب إعادة هيكلة من قبل .
ويجب أن تكون الوثائق المشار إليها فى الفقرة السابقة مؤرخة وموقعة من التاجر ، وإذا تعذر تقديم بعض هذه الوثائق أو استيفاء بياناتها وجب عليه إيضاح أسباب ذلك .
وللقاضى إلزام مقدم الطلب خلال المدة التى يحددها بتقديم مستندات إضافية أو معلومات حول وضعه الاقتصادى أو المالى .$m251$,'82821a911b56a473705018593787c4d0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(78,0,1,$m251$لكل دائن بدين تجارى خال من النزاع حال الأداء أن يطلب الحكم بشهر إفلاس مدينه التاجر ويكون للدائن بدين مدنى حال هذا الحق إذا أثبت أن التاجر قد توقف عن دفع ديونه التجارية الحالة فضلا عن دينه المدنى .
ويكون للدائن بدين آجل الحق فى طلب شهر الإفلاس إذا لم يكن لمدينه التاجر موطن معروف فى مصر أو إذا لجأ إلى الفرار أو أغلق متجره أو شرع فى تصفيته أو أجرى تصرفات ضارة بدائنيه بشرط أن يقدم الدائن ما يثبت أن المدين توقف عن دفع ديونه التجارية الحالة .
ويطلب الدائن شهر إفلاس مدينه بطلب يقدم إلى إدارة الإفلاس التابعة للمحكمة المختصة مصحوبا بما يفيد إيداع مبلغ عشرة آلاف جنيه خزانة المحكمة على سبيل الأمانة لحساب مصروفات نشر الحكم الصادر بشهر الإفلاس ، يطلب فيه اتخاذ الإجراءات التحفظية اللازمة ويبين فيه الظروف التى يستدل منها على توقف المدين عن دفع ديونه .$m251$,'d6eb931492363c4a3388df2925834f8b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(79,0,1,$m251$لا يجوز شهر إفلاس التاجر بسبب توقفه عن دفع ما يستحق عليه من غرامات جنائية أو ضرائب أو رسوم أو تأمينات اجتماعية .$m251$,'cdda89e4c040e4846a082ff02d618fe4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(80,0,1,$m251$استثناء من أحكام المواد (4 ، 5 ، 9 ، 10 ، 11) من هذا القانون إذا طلبت النيابة العامة شهر إفلاس التاجر ، أو إذا رأت المحكمة شهر إفلاسه من تلقاء ذاتها ، وجب على قلم الكتاب أن يعلنه بيوم الجلسة .
وفى حالة وفاة التاجر أو اعتزاله التجارة لا يجوز للمحكمة أن تنظر فى شهر الإفلاس بناء على طلب النيابة العامة بعد انقضاء السنة التالية لوفاته أو اعتزاله التجارة .$m251$,'49792b1d540150ad9811a4064825d07a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(81,0,1,$m251$يخطر قلم كتاب المحكمة المختصة النيابة العامة بطلب شهر الإفلاس ، ولا يحول عدم حضورها أو عدم إبداء الرأى دون الحكم فى دعوى الإفلاس .$m251$,'a961467a6a79d5263424c02e3467aa4a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(82,0,1,$m251$يجوز للمحكمة المختصة بنظر دعوى الإفلاس أن تأمر باتخاذ التدابير اللازمة للمحافظة على أموال المدين أو إدارتها لمدة ثلاثة أشهر تجدد لمدد أخرى إلى أن يتم الفصل فى الدعوى ، كما يجوز أن تتخذ من الإجراءات ما يمكنها من الإحاطة بحالة المدين المالية وأسباب توقفه عن الدفع .$m251$,'09b642c413fa97c5fb5eeaeaf1a2676a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(83,0,1,$m251$تختص محكمة الإفلاس بنظر جميع الدعاوى الناشئة عن التفليسة والدعاوى التى للتفليسة على الغير أو للغير عليها .
وتعتبر الدعوى ناشئة عن التفليسة على وجه الخصوص إذا كانت متعلقة بأموالها أو بإدارتها أو بموجوداتها أو كان الفصل فيها يقتضى تطبيق أحكام هذا القانون .$m251$,'22e37c7507caaaaa2ade7a502585b1d8',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(84,0,1,$m251$تحدد المحكمة فى حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع ، وتعين أمينا للتفليسة وتختار أحد قضاة المحكمة ليكون قاضيا للتفليسة ، وتأمر بوضع الأختام على محل تجارة المدين لحين الانتهاء من الجرد .
ويرسل قلم كتاب المحكمة إلى النيابة العامة ملخصا من حكم شهر الإفلاس فور صدوره .$m251$,'c2e3d8feb7ffb722dc93b162f41ed06c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(85,0,1,$m251$تستعين المحكمة فى تعيين تاريخ التوقف عن الدفع بكل فعل أو قول أو تصرف يصدر من المدين ويكشف عن اضطراب أعماله أو سعيه إلى الاستمرار فى نشاطه التجارى بوسائل غير مشروعة أو ضارة بدائنيه ، ويدخل فى ذلك على وجه الخصوص شروع المدين فى الهرب أو الانتحار ، أو إخفاء أمواله أو بيعها بخسارة أو عقد قروض بشروط باهظة أو الدخول فى مضاربات طائشة .
وإذا لم يعين فى حكم شهر الإفلاس التاريخ الذى توقف فيه المدين عن الدفع اعتبر تاريخ صدور حكم شهر الإفلاس تاريخا مؤقتا للتوقف عن الدفع .
وإذا صدر حكم شهر الإفلاس بعد وفاة المدين أو بعد اعتزاله التجارة ولم يعين فيه تاريخ التوقف عن الدفع اعتبر تاريخ الوفاة أو اعتزال التجارة تاريخا مؤقتا للتوقف عن الدفع .$m251$,'9466a377fbe6a595b7edd1cea3765198',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(86,0,1,$m251$يجوز للمحكمة من تلقاء ذاتها ، أو بناء على طلب النيابة العامة أو المدين أو أحد الدائنين أو أمين التفليسة أو غيرهم من ذوى المصلحة ، تعديل التاريخ المؤقت للتوقف عن الدفع وذلك حتى تاريخ إيداع قائمة الديون المحققة قلم كتاب المحكمة ، وبعد انقضاء هذا الميعاد يصير التاريخ المعين للتوقف عن الدفع نهائيا .
وفى جميع الأحوال لا يجوز إرجاع تاريخ التوقف عن الدفع إلى أكثر من سنتين سابقتين على تاريخ صدور الحكم بشهر الإفلاس .$m251$,'9bdcf26fccdf337c611861373724cc5f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(87,0,1,$m251$يقوم قلم كتاب المحكمة التى أصدرت الحكم بشهر الإفلاس بإخطار أمين التفليسة فور صدور الحكم بكتاب مسجل مصحوبا بعلم الوصول لمباشرة أعمال التفليسة .
وعلى أمين التفليسة شهر الحكم وكذلك الحكم بتعديل تاريخ التوقف عن الدفع فى السجل التجارى .
ويتولى أمين التفليسة نشر ملخص الحكم فى صحيفة يومية تعينها المحكمة فى حكم شهر الإفلاس ، ويجب أن يتم النشر خلال عشرة أيام من تاريخ إخطاره بالحكم ، ويشتمل الملخص المذكور فيما يتعلق بحكم شهر الإفلاس على اسم المفلس وموطنه ورقم قيده فى السجل التجارى والمحكمة التى أصدرت الحكم وتاريخ صدوره والتاريخ المؤقت للتوقف عن الدفع واسم قاضى التفليسة واسم أمينها وعنوانه ، كما يتضمن النشر دعوة الدائنين لتقديم ديونهم فى التفليسة ، وفى حالة تعديل تاريخ التوقف عن الدفع يشتمل النشر فضلا عن البيانات المذكورة على التاريخ الجديد الذى عينته المحكمة .
وعلى أمين التفليسة ، خلال خمسة عشر يوما من تاريخ إخطاره بحكم شهر الإفلاس ، أن يخطر به البنك المركزى المصرى لإخطار البنوك العاملة فى مصر ، والهيئة العامة للرقابة المالية والبورصة المصرية وشركة مصر للمقاصة والتأشير بملخصه باسم جماعة الدائنين فى كل مكتب للشهر العقارى يوجد فى دائرته عقار للمفلس ، ولا يترتب على هذا التأشير أى حق آخر لجماعة الدائنين ، والتأشير بالحكم بسجل الضمانات المنقولة .$m251$,'ae069b138bedcf0a2eb3b3e61e5a32ca',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(88,0,1,$m251$يجوز لكل ذى مصلحة من غير الخصوم أن يعترض على حكم شهر الإفلاس أمام المحكمة التى أصدرته خلال ثلاثين يوما من تاريخ نشره فى الصحف ، ما لم يكن قد طعن عليه بالاستئناف فيرفع الاعتراض إلى المحكمة التى تنظر الاستئناف .
ويسرى على ميعاد استئناف الحكم الصادر فى دعوى شهر الإفلاس وغيره من الأحكام الصادرة فى الدعاوى الناشئة عن التفليسة وطريقة رفعها أحكام قانون المرافعات المدنية والتجارية .$m251$,'6ea70aad7de92a47226d461419c706c5',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(89,0,1,$m251$تكون الأحكام الصادرة فى دعاوى الإفلاس واجبة النفاذ المعجل بلا كفالة بمسودتها ما لم ينص على غير ذلك .$m251$,'bfa08bd9240609c1b87d3bb24cd9f798',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(90,0,1,$m251$لا يجوز الطعن بأى طريق فى :
(أ) الأحكام أو القرارات الخاصة بتعيين أو استبدال قاضى التفليسة أو أمينها أو مراقبها .
(ب) الأحكام الصادرة فى الطعن فى قرارات قاضى التفليسة .
(ج) الأحكام الصادرة بوقف إجراءات التفليسة إلى حين الفصل فى الطعن فى قرار قاضى التفليسة بشأن قبول الديون أو رفضها
(د) الأحكام الصادرة بشان قبول الديون المتنازع فيها مؤقتا .$m251$,'4afa2f6422da3cd14972590688b0991c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(91,0,1,$m251$إذا أوفى المدين جميع ما هو مستحق عليه من ديون تجارية قبل أن يحوز حكم شهر الإفلاس قوة الشىء المقضى به وجب على المحكمة أن تقضى بإلغاء حكم شهر الإفلاس على أن يتحمل المدين كافة مصاريف الدعوى .$m251$,'2117b27be3d7d75efa89b9d96676f97f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(92,0,1,$m251$إذا لم توجد فى التفليسة ، وقت شهرها ، نقود حاضرة لمواجهة شهر حكم الإفلاس ونشره أو وضع الأختام على أموال المفلس أو رفعها وجب دفع هذه المصاريف من مبلغ الأمانة التى أودعها طالب شهر الإفلاس ويسترد طالب شهر الإفلاس المبالغ التى دفعها بالامتياز على جميع الدائنين من أول نقود تدخل التفليسة ، كما يجوز لقاضى التفليسة أن يأمر بالمبادرة ببيع بعض أموال التفليسة لمواجهة هذه المصاريف .$m251$,'1ddc9eedb02fb2b1a97e1e97d9125b48',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(93,0,1,$m251$إذا طلب المدين شهر إفلاسه وقضت المحكمة برفض الطلب جاز لها أن تحكم عليه بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز خمسين ألف جنيه إذا تبين لها أنه تعمد اصطناع الإفلاس .
وإذا طلب أحد الدائنين شهر الإفلاس وقضت المحكمة برفض الطلب يحكم على الدائن بالغرامة المنصوص عليها فى الفقرة السابقة وينشر الحكم على نفقته فى الصحف التى تعينها ، إذا تبين لها أنه تعمد الإساءة إلى سمعة المدين التجارية ، وذلك مع عدم الإخلال بحق المدين فى طلب التعويض .$m251$,'5bb35b083268db40f6148eb51b68f6ee',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(94,0,1,$m251$تعين المحكمة فى حكم الإفلاس من جدول خبراء إدارة الإفلاس ممثلا قانونيا لإدارة التفليسة يسمى (أمين التفليسة) .
ويجوز فى كل وقت لقاضى التفليسة من تلقاء نفسه أو بناء على طلب المفلس أو المراقب الأمر بإضافة أمين أو أكثر بشرط ألا يزيد عددهم على ثلاثة .
ويصدر بتنظيم مهنة أمناء التفليسات قرار من الوزير المختص .$m251$,'1255c3b1b1cd7bc15843cfcd31ad14ca',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(95,0,1,$m251$لا يجوز أن يعين أمينا للتفليسة من كان زوجا للمفلس أو قريبا له حتى الدرجة الرابعة أو من كان خلال السنتين السابقتين على شهر الإفلاس شريكا له أو مستخدما عنده أو محاسبا له أو وكيلا عنه ، وكذلك من سبق الحكم عليه بالإدانة فى جناية أو فى جنحة ماسة بالشرف والأمانة .$m251$,'df8391f4fbb30942632ce09700f04fa5',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(96,0,1,$m251$يقوم أمين التفليسة بإدارة أموال التفليسة والمحافظة عليها وينوب عن المفلس فى جميع الدعاوى والأعمال التى تقتضيها هذه الإدارة .
ويدون أمين التفليسة ، يوما بيوم ، جميع الأعمال المتعلقة بإدارة التفليسة فى دفتر خاص ترقم صفحاته ويضع عليها قاضى التفليسة توقيعه أو ختمه ويؤشر فى نهاية الدفتر بما يفيد انتهاءه .
ويجوز للمحكمة ولقاضى التفليسة وللمراقب الاطلاع على هذا الدفتر فى كل وقت ، وللمفلس أيضا الاطلاع عليه بإذن من قاضى التفليسة .$m251$,'d39d32927bacc47f28788f81fccf69da',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(97,0,1,$m251$إذا تعدد أمناء التفليسة وجب أن يعملوا مجتمعين ويسألون بالتضامن عن إدارتهم .
ويجوز لقاضى التفليسة أن يقسم العمل بينهم أو أن يعهد إلى أحدهم بعمل معين ، وفى هذه الحالة لا يكون أمين التفليسة مسئولا إلا عن العمل الذى يكلف به .
ويجوز لأمناء التفليسة أن ينيبوا بعضهم البعض فى القيام بالأعمال المعهود بها إليهم ، ولا يجوز لهم إنابة الغير إلا بإذن من قاضى التفليسة ، وفى هذه الحالة يكون أمين التفليسة ونائبه مسئولين بالتضامن عن الأعمال المذكورة .$m251$,'1dc09008805d2465ed9f4e626cad527c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(98,0,1,$m251$يجوز للمفلس وللمراقب الاعتراض لدى قاضى التفليسة على أعمال أمينها قبل إتمامها ، ويترتب على الاعتراض وقف إجراء العمل . ويجب أن يفصل قاضى التفليسة فى الاعتراض خلال سبعة أيام من تاريخ تقديمه ، ويكون قرار قاضى التفليسة واجب النفاذ فورا .$m251$,'add09d39a4b69eb028086cb6321c381b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(99,0,1,$m251$يجوز للمحكمة ، من تلقاء ذاتها أو بناء على طلب قاضى التفليسة أو المفلس أو المراقب ، أن تحكم بعزل أمين التفليسة وتعيين غيره أو بإنقاص عدد الأمناء إذا تعددوا .$m251$,'499dc685b5d88a8883549ddffb03be3e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(100,0,1,$m251$تقدر أتعاب ومصاريف أمين التفليسة بقرار من قاضى التفليسة بعد أن يقدم الأمين تقريرا عن إدارته .
ويجوز لقاضى التفليسة أن يأمر بصرف مبالغ لأمين التفليسة قبل تقديم التقرير المذكور فى الفقرة السابقة خصما من أتعابه .
ويجوز لكل ذى شأن الطعن أمام المحكمة فى قرار قاضى التفليسة الخاص بتقدير أتعاب أمين التفليسة ومصاريفه .$m251$,'b3891e3fcc1d35349ed52a7f794947e4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(101,0,1,$m251$يتولى قاضى التفليسة بالإضافة إلى السلطات المقررة له ما يأتى :
1 - مراقبة إدارة التفليسة وملاحظة سير إجراءاتها والأمر باتخاذ التدابير اللازمة للمحافظة على أموالها ، بما فى ذلك تكليف أمين التفليسة بإقامة دعاوى أو مباشرة إجراءات معينة .
2 - دعوة الدائنين إلى الاجتماع فى الأحوال المبينة فى القانون ويتولى رئاسة الاجتماعات .
3 - يقدم للمحكمة كل ثلاثة أشهر تقريرا عن حالة التفليسة ، كما يقدم لها تقريرا عن كل نزاع يتعلق بالتفليسة ويكون من اختصاصها الفصل فيه .
4 - استدعاء المفلس أو ورثته أو وكلائه أو مستخدميه أو أى شخص آخر لسماع أقوالهم فى شئون التفليسة .$m251$,'1f4cd436f741a946b6378d2131cc3966',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(102,0,1,$m251$تودع القرارات التى يصدرها قاضى التفليسة قلم كتاب المحكمة فى اليوم التالى لصدورها ، وللقاضى أن يأمر قلم الكتاب بإخطارها لكل ذى مصلحة ، ويكون الإخطار بكتاب مسجل مصحوبا بعلم الوصول ، إلا إذا أمر قاضى التفليسة بإخطارها بطريقة أخرى .$m251$,'3c4efc7ee5162a69dda79bd253c74eb9',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(103,0,1,$m251$لا يجوز الطعن فى القرارات التى يصدرها قاضى التفليسة ما لم ينص القانون على غير ذلك أو كان القرار مما يجاوز اختصاصه ، ويقدم الطعن خلال عشرة أيام من تاريخ إيداع القرار . بصحيفة تودع قلم كتاب المحكمة وتعلن لذوى الشأن وتنظره المحكمة فى أول جلسة ، على ألا يشترك قاضى التفليسة المطعون فى قراره فى نظر هذا الطعن ، ويوقف الطعن تنفيذ القرار حتى تفصل المحكمة فى أمره ما لم تر المحكمة الأمر باستمرار تنفيذه .
وإذا رفضت المحكمة الطعن جاز لها أن تحكم على الطاعن بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه ، إذا تبين لها أنه تعمد تعطيل تنفيذ قرار قاضى التفليسة .$m251$,'536afd302b25eada428ccb4699c81bd2',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(104,0,1,$m251$للمحكمة فى كل وقت ، أن تأمر باستبدال قاضى التفليسة بغيره من قضاة المحكمة ، أو تندب غيره فى حالة غيابه المؤقت .$m251$,'32deac252ade1c80c5eae8c70e15c820',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(105,0,1,$m251$يجوز لقاضى التفليسة تعيين مراقب أو أكثر من بين الدائنين الذين يرشحون أنفسهم لذلك .
ويجوز للمفلس ولكل دائن الاعتراض على قرار قاضى التفليسة الخاص بتعيين المراقب دون أن يترتب على الاعتراض وقف تنفيذ القرار ، ويقدم الاعتراض إلى قاضى التفليسة نفسه ، ويجب أن يفصل فيه على وجه السرعة .$m251$,'db584ecdef9289fc35f50972b9333a06',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(106,0,1,$m251$لا يجوز أن يكون المراقب أو النائب عن الشخص الاعتبارى المعين مراقبا ، زوجا للمفلس أو قريبا له حتى الدرجة الرابعة .$m251$,'efa9ed923f9cef2b400cea5d91b15f07',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(107,0,1,$m251$يقوم المراقب ، بالإضافة إلى السلطات المقررة له بنصوص خاصة ، بفحص الميزانية والتقرير المقدمين من المدين وغير ذلك من المهام التى يكلفه بها قاضى التفليسة فى شأن الرقابة على أعمال أمينها ، ومعاونة قاضى التفليسة فى ذلك .
وللمراقب أن يطلب من أمين التفليسة إيضاحات عن سير إجراءاتها وإيراداتها ومصروفاتها وحالة الدعاوى المتعلقة بها .$m251$,'22782079c5673a8934f90744fc146786',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(108,0,1,$m251$لا يتقاضى المراقب أجرا نظير عمله ، ومع ذلك يجوز للمحكمة أن تقرر له مكافأة إجمالية عن عمله إذا بذل جهدا غير عادى وكانت الحالة المالية للتفليسة تسمح بذلك .
ويجوز عزل المراقب بقرار من قاضى التفليسة .
ولا يسأل المراقب إلا عن خطئه الجسيم .$m251$,'295aa8dfd8485d0bf8378e8e45a5dc98',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(109,0,1,$m251$يجوز للمحكمة بناء على طلب قاضى التفليسة أو النيابة العامة أو أمين التفليسة أو المراقب أن تأمر عند الاقتضاء بمنع المفلس من مغادرة البلاد لمدة لا تجاوز ستة أشهر قابلة للتجديد إذا قام بعمل من شأنه الإضرار بحقوق الدائنين . وللمفلس أن يتظلم من هذا الأمر أمام المحكمة المختصة دون أن يترتب على التظلم وقف تنفيذه .
وللمحكمة أن تقرر فى كل وقت إلغاء أمر المنع من مغادرة البلاد ،$m251$,'e0b69ffef5a76a0c63f2ec514cda5f84',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(110,0,1,$m251$لا يجوز للمفلس أن يتغيب عن موطنه دون أن يخطر أمين التفليسة كتابة بمحل وجوده ، ولا يجوز له أن يغير موطنه إلا بإذن من قاضى التفليسة .$m251$,'ba274afb61db07db35cc35a8789a88fb',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(111,0,1,$m251$مع عدم الإخلال بأحكام القانون رقم 45 لسنة 2014 بإصدار قانون بتنظيم مباشرة الحقوق السياسية ، والقانون رقم 46 لسنة 2014 بإصدار قانون مجلس النواب ، يحرم مؤقتا من مباشرة الحقوق السياسية ومن العضوية فى المجلس النيابى أو المجالس المحلية ، كل من صدر ضده حكم نهائى لارتكابه إحدى جرائم التفالس بالتدليس أو التقصير ، ويكون الحرمان لمدة ست سنوات من تاريخ تنفيذ العقوبة ، ولا يسرى ذلك الحرمان إذا رد إليه اعتباره أو أوقف تنفيذ العقوبة بحكم قضائى .
ولا يجوز لمن أشهر إفلاسه أن يكون عضوا بالغرف التجارية أو الصناعية أو النقابات أو الاتحادات المهنية أو الرياضية أو مديرا أو عضوا بمجلس إدارة أى شركة أو الاشتغال بأعمال البنوك أو الوكالة التجارية أو التصدير والاستيراد أو السمسرة فى بيع أو شراء الأوراق المالية أو البيع بالمزاد العلنى . كل ذلك ما لم يرد إليه اعتباره .
ولا يجوز لمن أشهر إفلاسه أن ينوب عن غيره فى إدارة أمواله أو التصرف فيها . ومع ذلك يجوز للمحكمة المختصة أن تقضى بناء على طلب من قاضى التفليسة بحلول أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال محل المفلس فى تنفيذ هذه الإنابة بصفة دائمة أو مؤقتة مع التأشير بذلك القضاء على هامش التوكيل الصادر للمفلس من الغير ويسرى ذلك القضاء من تاريخ التأشير ، وللمحكمة أن تأذن للمفلس فى إدارة أموال أولاده القصر إذا لم يترتب على ذلك ضرر لهم .$m251$,'93833b13d5bc012d4fc15f1e08769d00',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(112,0,1,$m251$تغل يد المفلس بمجرد صدور حكم شهر الإفلاس عن إدارة أمواله والتصرف فيها ، وتعتبر التصرفات التى يجريها المفلس فى يوم صدور حكم شهر الإفلاس حاصلة بعد صدوره .
وإذا كان التصرف مما لا يحتج به على الغير إلا بالقيد أو التسجيل أو غير ذلك من الإجراءات فلا يسرى على جماعة الدائنين إلا إذا كان التصرف ثابت التاريخ قبل تاريخ التوقف عن الدفع .
ولا يحول غل يد المفلس عن إدارة أمواله والتصرف فيها دون قيامه بالإجراءات اللازمة للمحافظة على حقوقه .$m251$,'08c69d0fac3d754f70f3dad1d39bd69b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(113,0,1,$m251$لا يجوز للمفلس بعد صدور حكم شهر الإفلاس الوفاء بما عليه من ديون أو استيفاء ما له من حقوق .
ومع ذلك إذا كان المفلس حاملا لورقة تجارية جاز الوفاء له بقيمتها عند حلول معياد استحقاقها إلا إذا عارض أمين التفليسة فى هذا الوفاء طبقا للمادة (431) من قانون التجارة رقم 17 لسنة 1999 ، على أن يتم إيداع قيمة الورقة التجارية حساب التفليسة .$m251$,'918dc66286eca2fedc48da61645325e3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(114,0,1,$m251$لا تقع المقاصة بعد صدور حكم شهر الإفلاس بين ما للمفلس من حقوق وما عليه من التزامات إلا إذا وجد ارتباط بينهما ، ويوجد الارتباط على وجه الخصوص إذا نشأت الحقوق والالتزامات عن سبب واحد أو شملها حساب جار .$m251$,'2719270a169625710a77140ec307df76',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(115,0,1,$m251$يشمل غل اليد جميع الأموال التى تكون ملكا للمفلس فى يوم صدور حكم شهر الإفلاس والأموال التى تئول إليه ملكيتها وهو فى حالة إفلاس .
ومع ذلك لا يشمل غل اليد ما يأتى :
(أ) الأموال التى لا يجوز الحجز عليها قانونا والإعانة التى تقرر للمفلس .
(ب) الأموال المملوكة لغير المفلس .
(ج) الحقوق المتصلة بشخص المفلس أو بأحواله الشخصية .
(د) التعويضات التى تستحق للمستفيد فى عقد تأمين صحيح أبرمه المفلس قبل صدور حكم شهر الإفلاس ومع ذلك يلتزم المستفيد بأن يرد إلى التفليسة جميع أقساط التأمين التى دفعها المفلس ابتداء من التاريخ الذى عينته المحكمة للتوقف عن الدفع ما لم ينص القانون على غير ذلك .$m251$,'aa0d5bddb10ccfa02fca1affb920734f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(116,0,1,$m251$إذا آلت إلى المفلس تركة فلا يكون لدائنيه حق على أموالها إلا بعد أن يستوفى دائنو المورث حقوقهم من هذه الأموال .
ولا يكون لدائنى المورث أى حق على أموال التفليسة .$m251$,'1f5ce27900d7bd5c22510eb9cf20b3eb',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(117,0,1,$m251$لا يجوز بعد صدور حكم شهر الإفلاس رفع دعوى من المفلس أو عليه أو السير فيها مع استثناء ما يأتى :
(أ) الدعاوى المتعلقة بالأموال والتصرفات التى لا يشملها غل اليد .
(ب) الدعاوى المتعلقة بأعمال التفليسة التى يجيز القانون للمفلس القيام بها .
(ج) الدعاوى الجنائية .
ويجوز للمحكمة أن تأذن بإدخال المفلس فى الدعاوى المتعلقة بالتفليسة ، كما يجوز لها أن تأذن بإدخال الدائن فى هذه الدعاوى إذا كانت له مصلحة خاصة فيها .
وإذا رفع المفلس أو رفعت عليه دعوى جنائية أو دعوى متعلقة بشخصه أو بأحواله الشخصية وجب إدخال أمين التفليسة فيها إذا اشتملت على طلبات مالية .$m251$,'0bff4501a3ef1930c96af51ccde06fc3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(118,0,1,$m251$استثناء من حكم المادة (121) من هذا القانون ، إذا حكم على المفلس بعد شهر إفلاسه بالتعويض عن ضرر أحدثه للغير قبل تقديم طلب شهر الإفلاس جاز للمحكوم له الدخول فى التفليسة بالتعويض المقضى به ما لم يثبت تواطؤه مع المفلس .$m251$,'a656e3c0ddc9b1bbff2096c7abde5aff',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(119,0,1,$m251$يجوز لقاضى التفليسة بعد سماع أقوال أمينها أن يقرر إعانة للمفلس تصرف من أموال التفليسة بناء على طلبه أو طلب من يعولهم .
ولمن طلب الإعانة ولأمين التفليسة التظلم من تقديرها أمام قاضى التفليسة دون أن يترتب على ذلك وقف صرف الإعانة .
ويجوز فى كل وقت لقاضى التفليسة من تلقاء نفسه أو بناء على طلب أمين التفليسة أن يعدل مقدار الإعانة أو أن يأمر بإلغائها ، ويجوز التظلم من هذا القرار أمام قاضى التفليسة نفسه .
ويوقف صرف الإعانة متى حاز حكم التصديق على الصلح قوة الشىء المقضى ، وإذا لم يقع الصلح يوقف صرف الإعانة بمجرد قيام حالة الاتحاد .$m251$,'7fd29e648973035073a38cf5f1a75939',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(120,0,1,$m251$مع مراعاة حكم المادة (111) من هذا القانون يجوز للمفلس بعد إذن قاضى التفليسة ، أن يمارس تجارة جديدة بغير أموال التفليسة ويكون للدائنين الذين تنشأ ديونهم بمناسبة هذه التجارة الأولوية فى استيفاء حقوقهم من أموالها .$m251$,'49c96448944dbf644dae02ab684d3445',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(121,0,1,$m251$لا يجوز التمسك فى مواجهة جماعة الدائنين بالديون المقضى بها بموجب أحكام صدرت بعد القضاء بشهر الإفلاس ، مع مراعاة تطبيق نص المادة (118) من هذا القانون ، كما لا يجوز التمسك فى مواجهتهم بالتصرفات التالية إذا قام بها المدين بعد تاريخ التوقف عن الدفع ، وقبل الحكم بشهر الإفلاس :
(أ) منح التبرعات أيا كان نوعها ما عدا الهدايا الصغيرة التى يجرى عليها العرف .
(ب) وفاء الديون قبل حلول الأجل أيا كانت كيفية الوفاء ، ويعتبر إنشاء مقابل وفاء ورقة تجارية لم يحل ميعاد استحقاقها فى حكم الوفاء قبل حلول الأجل .
(ج) وفاء الديون الحالة بغير الشىء المتفق عليه ، ويعتبر الوفاء بطريق الأوراق التجارية أو النقل المصرفى فى حكم الوفاء بالنقود .
(د) كل رهن أو تأمين اتفاقى آخر وكذلك كل اختصاص يتقرر على أموال المدين ضمانا لدين سابق على التأمين .$m251$,'9ef92c930c54080763bb3af6d401e196',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(122,0,1,$m251$كل ما أجراه المفلس من تصرفات غير ما ذكر فى المادة (121) من هذا القانون وخلال الفترة المشار إليها فيها يجوز الحكم بعدم نفاذه فى مواجهة جماعة الدائنين إذا كان التصرف ضارا بهم وكان المتصرف إليه يعلم وقت وقوع التصرف بتوقف المفلس عن الدفع .$m251$,'3bc9e12194e8caacf771b6abff2205c3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(123,0,1,$m251$إذا دفعت قيمة ورقة تجارية بعد تاريخ التوقف عن الدفع وقبل الحكم بشهر الإفلاس فلا يجوز أن يسترد من الحامل ما دفع له ، وإنما يلزم الساحب أو من سحبت الورقة التجارية لحسابه برد القيمة المدفوعة إذا كان يعلم وقت إنشاء الورقة التجارية بتوقف المفلس عن الدفع ، ويقع الالتزام بالرد فى حالة السند لأمر على المظهر الأول إذا كان يعلم وقت حصوله على السند بتوقف المفلس عن الدفع .$m251$,'336862169d95c1e3f486c5701dce3256',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(124,0,1,$m251$يجوز الحكم بعدم نفاذ حقوق الرهن أو الامتياز أو الاختصاص المقررة على أموال المدين فى مواجهة جماعة الدائنين إذا قيدت بعد تاريخ التوقف عن الدفع وبعد انقضاء ثلاثين يوما من تاريخ تقرير الرهن أو الامتياز أو الاختصاص .
ويأخذ الدائن صاحب الرهن أو الاختصاص التالى للرهن أو الاختصاص الذى حكم بعدم نفاذه فى مواجهة جماعة الدائنين مرتبة هذا التأمين ، ومع ذلك لا يعطى الدائن المذكور من الثمن الناتج من بيع المال المقرر عليه التأمين إلا ما كان يحصل عليه بغرض نفاذ الرهن أو الاختصاص السابق ويئول الفرق إلى جماعة الدائنين .$m251$,'404ee0cffaeb3b49e8fc9a9ba6e60ba9',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(125,0,1,$m251$يجوز لأمين التفليسة وحده أو بناء على طلب قاضى التفليسة أن يطلب عدم نفاذ تصرفات المدين فى حق جماعة الدائنين إذا وقع التصرف قبل صدور حكم شهر الإفلاس وذلك وفقا لأحكام القانون المدنى ، ويسرى الحكم الصادر بعدم نفاذ التصرف فى حق جميع الدائنين سواء نشأت حقوقهم قبل حصول التصرف أو بعد حصوله .$m251$,'f9255eb29861fcd4288ead9b5e2dda0e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(126,0,1,$m251$إذا حكم بعدم نفاذ أى تصرف فى حق جماعة الدائنين التزم المتصرف إليه بأن يرد إلى التفليسة ما حصل عليه من المفلس بمقتضى هذا التصرف أو قيمة الشىء وقت قبضه ، كما يلزم بدفع عوائد ما قبضه أو ثماره من تاريخ القبض .
ويكون للمتصرف إليه الحق فى استرداد العوض الذى قدمه للمفلس إذا وجد هذا العوض بعينه فى التفليسة ، فإذا لم يوجد كان من حق المتصرف إليه أن يطالب جماعة الدائنين بالمنفعة التى عادت عليهم من التصرف وأن يشترك فى التفليسة بوصفه دائنا عاديا بما يزيد على قيمة هذه المنفعة .$m251$,'242964c077443dd51f6e349446ad5a7b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(127,0,1,$m251$تسقط الدعاوى الناشئة عن تطبيق الأحكام المنصوص عليها فى المواد من ( 121 ) إلى ( 125 ) من هذا القانون بمضى سنتين من تاريخ صدور الحكم بشهر الإفلاس .$m251$,'b257d883228272f2efb2e6f3d973354f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(128,0,1,$m251$لا يجوز للدائنين العاديين أو الدائنين أصحاب حقوق الامتياز العامة بعد صدور حكم شهر الإفلاس إقامة دعاوى فردية على التفليسة أو اتخاذ أى إجراءات قضائية أخرى ضدها .
وكذلك يترتب على صدور حكم شهر الإفلاس وقف الدعاوى الفردية المقامة من الدائنين المذكورين فى الفقرة السابقة ووقف إجراءات التنفيذ التى بدأها هؤلاء الدائنون قبل صدور حكم شهر الإفلاس ، ومع ذلك إذا تحدد يوم لبيع عقار المفلس جاز الاستمرار فى إجراءات التنفيذ بإذن من قاضى التفليسة .
وأما الدائنون المرتهنون وأصحاب حقوق الامتياز الخاصة والحاصلون على اختصاص على أموال المدين فيجوز لهم إقامة الدعاوى الفردية أو الاستمرار فيها فى مواجهة أمين التفليسة . كما يجوز لهم التنفيذ أو الاستمرار فيه على الأموال التى تقع عليها تأميناتهم بشرط إخطار قاضى التفليسة بالتنفيذ ، ويكون التنفيذ فى مواجهة أمين التفليسة .$m251$,'961644cd38df62700a1322d12f3a4549',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(129,0,1,$m251$الحكم بشهر الإفلاس يسقط آجال جميع الديون النقدية التى على المفلس سواء أكانت عادية أم مضمونة بامتياز عام أو خاص .$m251$,'c434b0f2f7418360766a4084a2e9689f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(130,0,1,$m251$الحكم بشهر الإفلاس يوقف سريان عوائد الديون العادية بالنسبة إلى جماعة الدائنين فقط ولا تجوز المطالبة بعوائد الديون المضمونة برهن أو امتياز أو اختصاص إلا من المبالغ الناتجة من بيع الأموال التى يقع عليها التأمين ، ويستنزل أصل الدين أولا ثم العوائد المستحقة قبل صدور الحكم بشهر الإفلاس ثم العوائد المستحقة بعد صدوره .$m251$,'7f78826084ca5bf85bc3a1a4838f2520',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(131,0,1,$m251$لقاضى التفليسة أن يستنزل من الدين الآجل الذى لم يشترط فيه عائد مبلغا يعادل العائد المستحق عن المدة من تاريخ الحكم بشهر الإفلاس إلى تاريخ استحقاق الدين .$m251$,'300eedea781e80ef7ce0e475c93ca2dc',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(132,0,1,$m251$يجوز الاشتراك فى التفليسة بالديون المعلقة على شرط فاسخ ، مع تقديم كفيل ، أما الديون المعلقة على شرط واقف فيجنب نصيبها فى التوزيعات إلى أن تتبين نتيجة الشرط .$m251$,'047affc45ea5378c8d0a792cd5593f38',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(133,0,1,$m251$إذا وجد جملة ملتزمين بدين واحد شهر إفلاس أحدهم فلا يترتب على هذا الإفلاس أثر بالنسبة إلى الملتزمين الآخرين ما لم ينص القانون على غير ذلك .
وإذا تم الصلح مع الملتزم الذى أفلس فلا تسرى شروطه على الملتزمين الآخرين .$m251$,'1276206373459b162d11071224b91430',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(134,0,1,$m251$إذا استوفى الدائن من أحد الملتزمين بدين واحد جزءا من الدين ثم أفلس باقى الملتزمين أو أفلس أحدهم فلا يجوز للدائن أن يشترك فى التفليسات إلا بالباقى من دينه ويبقى محتفظا بحقه فى مطالبة الملتزم غير المفلس بهذا الباقى ، ويجوز لهذا الملتزم أن يشترك فى كل تفليسة بما وفاه عنها .$m251$,'33cac39135723161b9e3fdb8d7a6191b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(135,0,1,$m251$إذا أفلس جميع الملتزمين بدين واحد دفعة واحدة ، جاز للدائن أن يشترك فى كل تفليسة بكل دينه إلى أن يستوفيه بتمامه ، من أصل وعوائد ومصاريف .
ولا يجوز لتفليسة الرجوع على تفليسة أخرى بما أوفته عنها .
وإذا كان مجموع ما حصل عليه الدائن يزيد على دينه وتوابعه عادت الزيادة إلى تفليسة من يكون مكفولا من الآخرين بحسب ترتيب التزاماتهم بالدين ، فإذا لم يوجد هذا الترتيب عادت الزيادة إلى التفليسات التى دفعت أكثر من حصتها فى الدين .$m251$,'e2b2297235776aeb40161f234e60cf48',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(136,0,1,$m251$لا تدرج أسماء دائنى المفلس الحائزين بوجه قانونى على رهن أو امتياز خاص على منقول أو عقار فى جماعة الدائنين إلا على سبيل التذكرة .$m251$,'6de1274267438d4c050c85791f3bb1d5',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(137,0,1,$m251$يجوز لأمين التفليسة فى كل وقت وبعد الحصول على إذن من قاضى التفليسة ، دفع الدين المضمون برهن واسترداد الأشياء المرهونة لحساب جماعة الدائنين .$m251$,'413124fce459a944eb17646acf7602dc',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(138,0,1,$m251$على أمين التفليسة بعد استئذان قاضى التفليسة أن يدفع خلال الأيام العشرة التالية لصدور الحكم بشهر الإفلاس مما يكون تحت يده من نقود التفليسة وبالرغم من وجود أى دين آخر ، الأجور والمرتبات والمبالغ المستحقة قبل صدور الحكم بشهر الإفلاس عن مدة ثلاثين يوما للعاملين لدى المفلس ، فإذا لم يكن لدى أمين التفليسة النقود اللازمة لوفاء هذه الديون وجب الوفاء من أول نقود تدخل التفليسة ولو وجدت ديون أخرى تسبقها فى مرتبة الامتياز .
ويكون للمبالغ المستحقة للطوائف المذكورة والزائدة على ما تقدم مرتبة الامتياز المقررة قانونا .$m251$,'a4c0771b46412b245bd2c68056e1f54a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(139,0,1,$m251$يكون للمؤجر فى حالة إنهاء إيجار العقار الذى يمارس فيه المفلس التجارة طبقا للمادة (143) من هذا القانون امتياز لضمان الأجرة المستحقة له عن السنة السابقة على صدور حكم شهر الإفلاس وعن السنة الجارية ، وإذا بيعت المنقولات الموجودة فى العين المؤجرة أو نقلت ظل المؤجر محتفظا بحقه فى الامتياز .$m251$,'9608c7e0cea0a9ecd9941ee6278ec4c0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(140,0,1,$m251$لا يشمل الامتياز المقرر للحكومة بسبب الضرائب على اختلاف أنواعها إلا دين الضريبة المستحقة على المفلس عن السنتين السابقتين على صدور الحكم بشهر الإفلاس ، وتدخل الضرائب الأخرى المستحقة فى التوزيعات بوصفها ديونا عادية .$m251$,'a7105ad5053ba5a71ed992dee838015a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(141,0,1,$m251$يجوز لقاضى التفليسة بناء على اقتراح أمينها أن يأمر عند الاقتضاء باستخدام أول نقود تدخل التفليسة فى الوفاء بحقوق الدائنين الذين لهم امتياز على منقولات المفلس بشرط أن تكون أسماؤهم قد وردت بالقائمة النهائية للديون غير المتنازع فيها المشار إليها فى الفقرة الأولى من المادة (171) من هذا القانون ، وإذا حصلت منازعة فى الامتياز فلا يجوز الوفاء إلا بعد الفصل فيها بحكم نهائى .$m251$,'e2a12715fd4e764e22cffd7010ea180d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(142,0,1,$m251$لا يترتب على الحكم بشهر الإفلاس فسخ العقود الملزمة للجانبين التى يكون المفلس طرفا فيها إلا إذا كانت قائمة على اعتبارات شخصية .
وإذا لم ينفذ أمين التفليسة العقد أو لم يستمر فى تنفيذه جاز للطرف الآخر أن يطلب الفسخ ، وكل قرار يتخذه أمين التفليسة بشأن العقد يجب أن يعرض على قاضى التفليسة ليأذن به ، ويجوز للطرف الآخر أن يعين لأمين التفليسة مهلة مناسبة لإيضاح موقفه من العقد .
وللمتعاقد الاشتراك فى التفليسة كدائن عادى بالتعويض المترتب على الفسخ إلا إذا نص على احتفاظ التعويض بالامتياز المقرر له قانونا .$m251$,'29aca5e65deb10c94650d2b996a14ae4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(143,0,1,$m251$إذا كان المفلس مستأجرا للعقار الذى يمارس فيه التجارة فلا يترتب على صدور الحكم بشهر الإفلاس إنهاء الإجارة أو حلول الأجرة عن المدة المتبقية لانقضائها ، وكل شرط على خلاف ذلك يعتبر كأن لم يكن .
وإذا كان المؤجر قد بدأ فى التنفيذ على المنقولات الموجودة فى العقار ولم يكن التنفيذ قد تم عند صدور الحكم بشهر الإفلاس وجب التنفيذ لمدة تسعين يوما من تاريخ هذا الحكم مع عدم الإخلال بحق المؤجر فى اتخاذ الإجراءات التحفظية وفى طلب إخلاء العقار وفقا للقواعد العامة . ويجوز لقاضى التفليسة أن يأمر باستمرار وقف التنفيذ لمدة ثلاثين يوما أخرى لمرة واحدة إذا رأى ضرورة لذلك وعلى أمين التفليسة إخطار مؤجر العقار خلال مدة وقف التنفيذ برغبته فى إنهاء الإجارة أو الاستمرار فيها .
وإذا قرر أمين التفليسة الاستمرار فى الإجارة وجب أن يدفع الأجرة المتأخرة وأن يقدم ضمانا كافيا للوفاء بالأجرة المستقبلة . ويجوز للمؤجر أن يطلب من قاضى التفليسة إنهاء الإجارة إذا كان الضمان غير كاف ، وذلك خلال خمسة عشر يوما من تاريخ إخطاره برغبة أمين التفليسة فى الاستمرار فى الإجارة .
ولأمين التفليسة بعد الحصول على إذن من قاضى التفليسة وبعد موافقة المؤجر تأجير العقار من الباطن أو التنازل عن الإيجار وفقا للأحكام المنظمة للعلاقة بين المالك والمستأجر .$m251$,'91128684e50a9c69e6cac72dc49b3194',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(144,0,1,$m251$إذا أفلس رب العمل وكان عقد العمل غير محدد المدة جاز للعامل ولأمين التفليسة إنهاء العقد مع مراعاة الأحكام المنصوص عليها فى قوانين العمل . ولا يجوز للعامل فى هذه الحالة مطالبة التفليسة بالتعويض إلا إذا كان الإنهاء تعسفيا أو بغير مراعاة مواعيد الإخطار .
وإذا كان عقد العمل محدد المدة فلا يجوز إنهاؤه إلا إذا تقرر عدم الاستمرار فى التجارة ، ويجوز للعامل فى هذه الحالة مطالبة التفليسة بالتعويض .
ويكون للتعويض المستحق للعامل وفقا للفقرتين السابقتين الامتياز المقرر له قانونا .$m251$,'c4a61f1306a4156b5c83b9355e77dff7',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(145,0,1,$m251$لكل شخص أن يسترد من التفليسة الأشياء التى تثبت له ملكيتها أو حق استردادها وقت شهر الإفلاس .
ويكون لأمين التفليسة ، بعد أخذ رأى المراقب والحصول على إذن من قاضى التفليسة رد الشىء إلى مالكه أو صاحب الحق فى استرداده ، وإذا رفض طلب الاسترداد جاز لطالبه عرض النزاع على المحكمة .$m251$,'567147b8e0f61723b0b70f1ff5433b59',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(146,0,1,$m251$يجوز استرداد الأشياء الموجودة فى حيازة المفلس ، على سبيل الوديعة أو لأجل بيعها لحساب مالكها أو لأجل تسليمها إليه ، بشرط أن توجد فى التفليسة عينا . كما يجوز استرداد ثمن البضائع إذا لم يكن قد تم الوفاء به نقدا أو بورقة تجارية أو بطريق قيده فى حساب جار بين المفلس والمشترى .
وعلى المسترد أن يدفع لأمين التفليسة الحقوق المستحقة للمفلس .
وإذا كان المفلس قد أودع البضائع لدى الغير جاز استردادها منه .
وإذا اقترض المفلس برهن البضائع وكان الدائن المرتهن لا يعلم وقت إنشاء الرهن بعدم ملكية المفلس لها فلا يجوز استردادها إلا بعد وفاء الدين المضمون بالرهن .$m251$,'2fe6d9c46d08b7ed4a2f2c4cffd37d8b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(147,0,1,$m251$يجوز استرداد الأوراق التجارية وغيرها من الأوراق ذات القيمة ، المسلمة إلى المفلس لتحصيلها أو لتخصيصها لوفاء معين إذا وجدت عينا فى التفليسة ولم تكن قيمتها قد دفعت ، ولا يجوز استرداد أوراق النقد المودعة لدى المفلس إلا إذا أثبت طالب الاسترداد ذاتيتها .$m251$,'c3da5c8de996cd6d83c93d1ad87ed10b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(148,0,1,$m251$إذا فسخ عقد البيع بحكم أو بمقتضى شرط فى العقد قبل صدور الحكم بشهر إفلاس المشترى ، جاز للبائع استرداد البضائع كلها أو بعضها فى التفليسة بشرط أن توجد عينا .
ويجوز الاسترداد ولو وقع الفسخ بعد صدور حكم شهر الإفلاس بشرط أن تكون دعوى الاسترداد أو دعوى الفسخ قد رفعت قبل صدور هذا الحكم .$m251$,'6a4826259eba25cc7f2e654bf70c5ec3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(149,0,1,$m251$إذا أفلس المشترى قبل دفع الثمن وكانت البضائع لا تزال لدى البائع ، جاز له حبسها .
وإذا أفلس المشترى بعد إرسال البضائع إليه وقبل دخولها مخازنه أو مخزن وكيله المكلف ببيعها ، جاز للبائع استرداد حيازتها ، ومع ذلك لا يجوز الاسترداد إذا فقدت البضائع ذاتيتها ، أو تصرف فيها المفلس قبل وصولها ، بغير تدليس ، بموجب وثائق الملكية أو النقل .
وفى جميع الأحوال يجوز لأمين التفليسة ، بعد استئذان قاضى التفليسة أن يطلب تسليم البضائع بشرط أن يدفع للبائع الثمن المتفق عليه ، فإذا لم يطلب أمين التفليسة ذلك جاز للبائع أن يتمسك بحقه فى الفسخ وطلب التعويض والاشتراك به فى التفليسة .$m251$,'b19dac1a4603c79cde25527eb6f7fbf6',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(150,0,1,$m251$مع عدم الإخلال بأحكام قانون تنظيم الضمانات المنقولة الصادر بالقانون رقم (115) لسنة 2015 ، إذا أفلس المشترى قبل دفع الثمن وبعد دخول البضائع مخازنه أو مخازن وكيله المكلف ببيعها ، فلا يجوز للبائع أن يطلب فسخ البيع أو استرداد البضائع ، كما يسقط حقه فى الامتياز ، وكل شرط يكون من شأنه تمكين البائع من استرداد البضائع أو الاحتفاظ بامتيازه عليها لا يحتج به على جماعة الدائنين .$m251$,'d47ec979b71a3816a82a3c6bda1a57c3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(151,0,1,$m251$تتقادم دعاوى الاسترداد التى توجه إلى أمين التفليسة فى الحالات المذكورة فى المواد من (145) إلى (149) من هذا القانون بمضى سنة من تاريخ نشر حكم شهر الإفلاس .$m251$,'7d43901e661c3f65b37c6d0a20b1d8dc',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(152,0,1,$m251$توضع الأختام على محال المفلس ومكاتبه وخزائنه ودفاتره وأوراقه ومنقولاته .
ويقوم قاضى التفليسة بوضع الأختام فور صدور الحكم بشهر الإفلاس ، وله أن يندب أحد موظفى المحكمة لذلك ، كما يقوم بإخطار رئيس كل محكمة يوجد فى دائرتها مال للمفلس ليأمر بندب من يقوم بوضع الأختام على هذا المال .
وإذا تبين لقاضى التفليسة إمكان جرد أموال المفلس فى يوم واحد جاز له أو لمن يندبه ، البدء فى الجرد فورا دون حاجة إلى وضع الأختام .
ويحرر محضر بوضع الأختام أو بالجرد يوقعه من قام بهذا الإجراء ، ويسلم المحضر لقاضى التفليسة .$m251$,'18d7b9d9eeda7317dcc4dec158112cf0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(153,0,1,$m251$لا يجوز وضع الأختام على الملابس والمنقولات الضرورية للمفلس ولمن يعولهم ، ويعين قاضى التفليسة هذه الأشياء وتسلم إلى المفلس بقائمة يوقعها كل من قاضى التفليسة والمفلس .$m251$,'dd78b11662aad51aed9db6294ac001ca',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(154,0,1,$m251$يجوز لقاضى التفليسة أن يأمر ، من تلقاء نفسه أو بناء على طلب أمين التفليسة ، بعدم وضع الأختام أو برفعها عن الأشياء الآتية :
(أ) الدفاتر التجارية .
(ب) الأوراق التجارية وغيرها من الأوراق التى تستحق الوفاء فى ميعاد قريب أو التى تحتاج إلى إجراءات للمحافظة على الحقوق الثابتة فيها .
(ج) النقود اللازمة للصرف على الشئون العاجلة للتفليسة .
(د) الأشياء القابلة لتلف سريع أو لنقص عاجل فى القيمة أو التى تقتضى صيانتها مصاريف باهظة .
(هـ) الأشياء اللازمة لتشغيل المتجر إذا تقرر الاستمرار فى تشغيله .
وتجرد الأشياء المذكورة فى الفقرة السابقة بحضور قاضى التفليسة أو من يندبه لذلك ، وتسلم لأمين التفليسة بقائمة يوقعها .$m251$,'be2c9a0411131c9f1d45001af4ad22e4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(155,0,1,$m251$يأمر قاضى التفليسة ، بناء على طلب أمينها ، برفع الأختام للبدء فى جرد أموال المفلس .
ويجب أن يبدأ رفع الأختام والجرد خلال ثلاثين يوما من تاريخ صدور حكم شهر الإفلاس .$m251$,'0ca8148eed3f1cd7aa148404420cb3a4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(156,0,1,$m251$يحصل الجرد بحضور قاضى التفليسة أو من يندبه لذلك وأمين التفليسة وكاتب المحكمة ، ويجب أن يخطر به المفلس ويجوز له الحضور .
وتحرر قائمة جرد من نسختين يوقعهما قاضى التفليسة أو من ندبه لذلك وأمين التفليسة ، وكاتب المحكمة وتودع إحداهما قلم كتاب المحكمة ، وتبقى الأخرى لدى أمين التفليسة .
وتذكر فى القائمة الأموال التى لم توضع عليها الأختام أو التى رفعت عنها .
وتجوز الاستعانة بخبير فى إجراء الجرد وتقويم الأموال .$m251$,'517d835c3bb6914bcb1d8dc556959144',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(157,0,1,$m251$إذا شهر الإفلاس بعد وفاة التاجر ولم تحرر قائمة جرد بمناسبة الوفاة ، أو إذا توفى التاجر بعد شهر إفلاسه وقبل البدء فى تحرير قائمة الجرد أو قبل إتمامها ، وجب تحرير القائمة فورا أو الاستمرار فى تحريرها بالكيفية المبينة فى المادة (156) من هذا القانون ، ويجب أن يخطر به الورثة ويجوز لهم الحضور .$m251$,'d0cd5172314d82e4b6e2cc62882424b5',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(158,0,1,$m251$يتسلم أمين التفليسة ، بعد الجرد ، أموال المفلس ، ودفاتره وأوراقه ويوقع فى نهاية قائمة الجرد بما يفيد ذلك .$m251$,'fe49406e08559be5b7f159c570ee4ec4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(159,0,1,$m251$لا يجوز تسليم الدفاتر التجارية إلى أمين التفليسة إلا بعد أن يقوم قاضى التفليسة بإقفالها .
ويدعى المفلس إلى حضور جلسة إقفال الدفاتر التجارية ، فإذا لم يحضر أقفلت الدفاتر بغير حضوره .
ولا يجوز للمفلس أن ينيب عنه غيره لحضور جلسة إقفال الدفاتر إلا لأسباب يقبلها قاضى التفليسة .$m251$,'e2c96eb6cb60c78cd484a0567a7b350f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(160,0,1,$m251$إذا لم يكن المفلس قد قدم الميزانية ، وجب على أمين التفليسة أن يقوم بإعدادها ، وإيداعها قلم كتاب المحكمة .
ويتسلم أمين التفليسة الرسائل الواردة باسم المفلس والمتعلقة بأشغاله ، ولأمين التفليسة فضها والاحتفاظ بها ، وللمفلس الاطلاع عليها .$m251$,'fab48d1010f8a4ae84c06d141107745e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(161,0,1,$m251$يقوم أمين التفليسة بجميع الأعمال اللازمة للمحافظة على حقوق المفلس لدى الغير ، ويطالب بهذه الحقوق ويستوفيها ، وعليه أن يقيد ما للمفلس من حقوق عينية على عقارات مدينه ، إذا لم يكن المفلس قد أجرى القيد .$m251$,'856fc9b2a2ed3dba3e3977fc1de3738e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(162,0,1,$m251$يجوز لقاضى التفليسة بعد أخذ رأى المراقب وسماع أقوال المفلس أو إخطاره ، أن يأذن لأمين التفليسة بالصلح أو بقبول التحكيم فى كل نزاع يتعلق بالتفليسة ، ولو كان خاصا بحقوق أو دعاوى عقارية .
فإذا كان النزاع غير معين القيمة ، أو كانت قيمته تزيد على عشرين ألف جنيه ، فلا يكون الصلح أو قبول التحكيم نافذا إلا بعد تصديق قاضى التفليسة على شروطه ، ويدعى المفلس إلى الحضور عند التصديق ويسمع قاضى التفليسة أقواله إذا حضر ، ولا يكون لاعتراضه أى أثر ، ويجوز الطعن أمام المحكمة فى قرار قاضى التفليسة إذا صدر برفض التصديق على شروط الصلح أو التحكيم .
ولا يجوز لأمين التفليسة النزول عن حق للمفلس ، أو الإقرار بحق للغير عليه إلا بالإجراءات المبينة فى هذه المادة .$m251$,'118dfecf1459c979e83b097e1757fb1a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(163,0,1,$m251$لقاضى التفليسة من تلقاء نفسه أو بناء على طلب أمينها أو طلب المفلس أن يندب لجنة إعادة الهيكلة ، لوضع خطة لاستمرار تجارة المفلس بما يشمل تشغيل المتجر إذا اقتضت ذلك المصلحة العامة أو مصلحة المفلس أو الدائنين .
ويعين قاضى التفليسة بناء على اقتراح اللجنة المشار إليها وبعد أخذ رأى أمين التفليسة من يتولى إدارة المتجر بناء على خطة إعادة الهيكلة ويحدد أجره ، ويجوز تعيين المفلس للإدارة ويعتبر الأجر الذى يحصل عليه بديلا عن الإعانة .
ويشرف أمين التفليسة أو أمين اتحاد الدائنين على من يعين للإدارة ، وعليه أن يقدم تقريرا شهريا إلى قاضى التفليسة عن سير التجارة .
ويجوز للمفلس ولأى من أمينيها ولأى من الدائنين الطعن أمام المحكمة فى قرار قاضى التفليسة برفض الإذن بالاستمرار فى خطة إعادة الهيكلة بما فيها تشغيل المتجر .$m251$,'7e576d002cb155ec18e2e15bd3a89ccb',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(164,0,1,$m251$فى حالة وفاة المفلس يقوم ورثته مقامه فى إجراءات الإفلاس ، ولهم أن ينيبوا أحدهم ليمثلهم فى ذلك ، فإذا لم يتفقوا جاز لقاضى التفليسة بناء على طلب أمينها إنابة من يمثلهم ، وللقاضى فى كل وقت عزل من أنيب وتعيين غيره .$m251$,'68fb6bb40a3ad4f64a2402c476db1c90',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(165,0,1,$m251$على أمين التفليسة أن يقدم إلى قاضى التفليسة خلال ثلاثين يوما من تاريخ إخطاره بالتعيين تقريرا عن أسباب الإفلاس وحالة التفليسة الظاهرة وظروفها ، ويجوز لقاضى التفليسة مد الميعاد المحدد لتقديم هذا التقرير ، وعلى القاضى إحالة التقرير مع ملاحظاته إلى النيابة العامة .
كما يجب على أمين التفليسة أن يقدم إلى قاضى التفليسة تقارير عن حالة التفليسة فى مواعيد دورية يحددها القاضى .$m251$,'34e8b1f6edbd0df293388a4a259373aa',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(166,0,1,$m251$على جميع الدائنين ولو كانت ديونهم مصحوبة بتأمينات خاصة أو كانت ثابتة بأحكام نهائية أن يسلموا أمين التفليسة عقب صدور الحكم بشهر الإفلاس أصول مستندات ديونهم مصحوبة ببيان بهذه الديون وتأميناتها إن وجدت ومقدارها مقومة بالعملة الوطنية على أساس سعر الصرف المعلن لدى البنك المركزى بيعا أو إقفالا وتحويلات أو بنكنوتا إذا لم يوجد سعر تحويلات يوم صدور الحكم بشهر الإفلاس ، ويحرر أمين التفليسة إيصالا بتسلمه البيان ومستندات الدين .
ويجب أن يتضمن البيان تعيين محل مختار لأمين التفليسة فى دائرة المحكمة .
ويكون أمين التفليسة مسئولا عن المستندات لمدة سنة من تاريخ انتهاء التفليسة ، ويعيدها إلى الدائنين بعد قفل التفليسة .$m251$,'f9a71f6577b16bbb110de1acb14edd36',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(167,0,1,$m251$إذا لم يقدم جميع الدائنين المقيدة أسماؤهم فى الميزانية أصول مستندات ديونهم مصحوبة بالبيان المشار إليه فى المادة (166) من هذا القانون خلال الثلاثين يوما التالية لنشر الحكم بشهر الإفلاس ودعوة الدائنين للتقدم بديونهم ، وجب على أمين التفليسة إعادة النشر فورا فى الصحيفة اليومية التى نشر فيها حكم الإفلاس وللقاضى تحديد وسيلة نشر أخرى يقوم بها أمين التفليسة بالإضافة إلى النشر فى الصحف .
وعلى أمين التفليسة خلال الميعاد المنصوص عليه بالفقرة السابقة إخطار الدائنين الواردة أسماؤهم بالميزانية المعتمدة للمفلس فى حالة وجودها بالحكم والتقدم فى التفليسة ، وكذا إخطار كافة الجهات الحكومية ويعد النشر دليلا على علم الكافة .
وعلى الدائنين تقديم أصول مستندات ديونهم مصحوبة بالبيان المشار إليه خلال ثلاثين يوما من تاريخ النشر الثانى فى الصحف وإلا سقط حقهم فى الدخول فى التفليسة .$m251$,'4944ff44d31d5a0fd65a2ce069212691',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(168,0,1,$m251$يحقق أمين التفليسة الديون بمعاونة المراقب وبحضور المفلس أو بعد إخطاره بالحضور .
وإذا نازع أمين التفليسة أو المراقب أو المفلس فى صحة أحد الديون أو فى مقداره أو فى ضماناته وجب على أمين التفليسة إخطار الدائن فورا بذلك وللدائن تقديم إيضاحات كتابية أو شفوية خلال عشرة أيام من تاريخ تسلم الإخطار .
ولا تخضع الديون واجبة السداد المستحقة للحكومة بسبب الرسوم والضرائب على اختلاف أنواعها لإجراءات التحقيق .$m251$,'16bd923a98f136beae51d8e40d06236d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(169,0,1,$m251$يودع أمين التفليسة قلم كتاب المحكمة بعد الانتهاء من تحقيق الديون قائمة بها تشتمل على بيان بمستنداتها ، وأسباب المنازعة فيها إن وجدت ، وما يراه بشأن قبولها أو رفضها ، كما يودع كشفا بأسماء الدائنين الذين يدعون أن لهم تأمينات خاصة على أموال المفلس مبينا مقدار ديونهم ونوع تأميناتهم والأموال المقررة عليها .
ويجب أن يتم هذا الإيداع خلال أربعين يوما على الأكثر من تاريخ النشر الثانى لدعوة الدائنين للتقدم بديونهم .
وعلى أمين التفليسة خلال ستة أيام من تاريخ الإيداع أن ينشر فى صحيفة يومية بيانا بحصوله .
ولكل ذى مصلحة الاطلاع على القائمة والكشف المودعين بقلم كتاب المحكمة .$m251$,'be0a62edcc5673c7f9ce9eb720b1cadd',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(170,0,1,$m251$للمفلس ولكل دائن ورد اسمه بقائمة الديون أن ينازع فى الديون المدرجة بها خلال عشرة أيام من تاريخ النشر فى الصحف عن حصول الإيداع ، وتسلم المنازعة إلى قلم كتاب المحكمة أو ترسل إليه بكتاب مسجل مصحوبا بعلم الوصول ، وعلى قلم الكتاب عرضها فورا على قاضى التفليسة ولا يضاف إلى هذا الميعاد ميعاد للمسافة .$m251$,'be337585166fce15dfc0c15923674ba8',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(171,0,1,$m251$يضع قاضى التفليسة بعد انقضاء الميعاد المنصوص عليه فى المادة ( 170 ) من هذا القانون قائمة نهائية بالديون غير المتنازع فيها خلال ثلاثين يوما على الأكثر ، ويؤشر أمين التفليسة على البيان الذى يصحب مستندات هذه الديون بما يفيد قبولها ومقدار ما قبل من كل دين منها .
ويجوز لقاضى التفليسة اعتبار الدين متنازعا فيه ولو لم تقدم بشأنه أى منازعة .
ويفصل قاضى التفليسة فى الديون المتنازع فيها خلال ثلاثين يوما من تاريخ انقضاء ميعاد المنازعة ، ويخطر قلم كتاب المحكمة ذوى الشأن بميعاد الجلسة قبل انعقادها بثلاثة أيام على الأقل .
يصير الدائنون فى حالة اتحاد بحكم القانون بعد إيداع القائمة النهائية الديون غير المتنازع فيها .$m251$,'63fdb9aa6a590d612b3ba28abad8d4b0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(172,0,1,$m251$يجوز الطعن أمام المحكمة فى القرار الصادر من قاضى التفليسة بقبول الدين أو رفضه ، وذلك خلال عشرة أيام من تاريخ صدور القرار ، ولا يترتب على الطعن وقف إجراءات التفليسة إلا إذا أمرت المحكمة بوقفها ، ويجوز للمحكمة قبل الفصل فى الطعن أن تقضى بقبول الدين مؤقتا بمبلغ تقدره ، ولا يجوز الطعن فى حكم المحكمة برفض الدين نهائيا أو بقبوله ، وإذا كان الطعن فى الدين متعلقا بتأميناته وجب قبوله مؤقتا بوصفه دينا عاديا ، ولايشترك الدائن الذى لم يقبل دينه نهائيا أو مؤقتا فى إجراءات التفليسة .$m251$,'d3c5d6add13a50da4b02bb59acb3ce30',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(173,0,1,$m251$إذا توقفت أعمال التفليسة لعدم كفاية الأموال اللازمة لإدارتها ومواجهة أعمالها ، جاز لقاضى التفليسة من تلقاء نفسه أو بناء على تقرير من أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال أن يأمر بقفلها بقرار مسبب .
ويجوز للمفلس ولكل ذى مصلحة ولأمينها أن يطلبوا من قاضى التفليسة إلغاء قرار القفل خلال ثلاثة أشهر من تاريخ صدور القرار بقفلها إذا أثبت وجود مال كاف لمواجهة مصاريف استكمال أعمال التفليسة أو إذا أودع مبلغا كافيا لذلك يقدره قاضى التفليسة .
فإذا انقضت المدة المنصوص عليها فى الفقرة السابقة دون أن يتقدم أحد بطلب لقاضى التفليسة لإلغاء قرار القفل اعتبرت التفليسة منتهية بقوة القانون .$m251$,'fdfe565379a06d2e28a08ec4993373d0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(174,0,1,$m251$يجوز التظلم من قرارى قفل التفليسة ورفض إلغائه خلال عشرة أيام من تاريخ صدوره على ألا يترتب على التظلم وقف تنفيذ القرار أو قطع المدة المشار إليها بالفقرة الثانية من المادة (173) من هذا القانون .$m251$,'f45af7628f4dc9b06985996ef6a3373b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(175,0,1,$m251$يترتب على نهائية قرار قفل التفليسة لعدم كفاية أموالها أن يعود إلى كل دائن الحق فى اتخاذ الإجراءات ومباشرة الدعاوى الفردية ضد المفلس .
وإذا كان دين الدائن قد ثبت نهائيا فى التفليسة جاز له التنفيذ على أموال المفلس بناء على شهادة من قاضى التفليسة بمقدار دينه ، تعتبر بمثابة حكم نهائى فيما يتعلق بهذا التنفيذ ، ويؤشر على سند الدين بما يفيد استلام الدائن للشهادة .
وفى جميع الأحوال يجب أن تدفع بالأولوية مصاريف الإجراءات التى تمت فى أعمال التفليسة .$m251$,'dca520d1030a0de4aa9462c2a4abd45d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(176,0,1,$m251$يصدر قاضى التفليسة قرارا بانتهاء التفليسة فى الحالات الآتية :
(أ) إذا تم تحقيق الديون وأسفرت عن عدم وجود ديون مقبولة فى التفليسة أو وجود ديون متمثلة فى غرامات جنائية أو ضرائب ورسوم على اختلاف أنواعها أو تأمينات اجتماعية أو وجود دائن واحد فقط ، أو اجتمعت الديون فى يد دائن واحد .
(ب) سداد جميع الديون المقبولة فى التفليسة .
(ج) الصلح مع المدين المفلس .
(د) عدم وجود أموال للمفلس صالحة للتنفيذ عليها .
(هـ) تصفية جميع أموال المفلس والتصديق على الحساب الختامى .$m251$,'a4452f210a3ebbd3d6347cc141de26fb',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(177,0,1,$m251$لا يجوز لقاضى التفليسة أن يأمر بإنهائها إلا بعد الاطلاع على تقرير من أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال يبين فيه تحقق إحدى الحالات المشار إليها فى المادة (176) من هذا القانون .
وتنتهى التفليسة بمجرد صدور قرار قاضى التفليسة بإنهائها ويستعيد المفلس جميع حقوقه .$m251$,'16abfb23759761b1d2d598955720c00f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(178,0,1,$m251$لقاضى التفليسة بناء على طلب كل ذى مصلحة وفى أى مرحلة كانت عليها الإجراءات أن يباشر إجراءات الوساطة للوصول إلى الصلح وله فى سبيل ذلك أن يأمر قلم الكتاب بدعوة الدائنين الذين قبلت ديونهم نهائيا أو مؤقتا لحضور المداولة فى طلب الصلح .
يقدم أمين التفليسة أو أمين الاتحاد حسب الأحوال تقريرا إلى جماعة الدائنين مشتملا على حالة التفليسة وما تم بشأنها من إجراءات ، ومقترحات المفلس فى الصلح ورأيه فيها .$m251$,'1399bf817731035cb38d6eaa0c1009b3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(179,0,1,$m251$لا يقع الصلح إلا بموافقة جميع الدائنين ، ولا يجوز للدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك فى التصويت على الصلح بديونهم المضمونة بالتأمينات المذكورة إلا إذا نزلوا عن هذه التأمينات مقدما .$m251$,'266f0644bfa48b64a64aae77127c8d30',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(180,0,1,$m251$يوقع محضر الصلح فى الجلسة التى تم فيها التصويت عليه ويقوم القاضى بالتصديق عليه ، ويتم نشره بإحدى الصحف اليومية .$m251$,'8923abac154230a578c19cb04e1e0977',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(181,0,1,$m251$لا يجوز عقد الصلح مع مفلس حكم عليه بعقوبة الإفلاس بالتدليس ، وإذا بدأ التحقيق مع المفلس فى جريمة الإفلاس بالتدليس وجب تأجيل النظر فى الصلح .$m251$,'3a12a2e97fbe443ed54440c6ee75b349',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(182,0,1,$m251$تزول جميع آثار الإفلاس بصدور قرار التصديق على الصلح ، ويكون على الأمين أن يقدم إلى المفلس حسابا ختاميا ويناقش الحساب بحضور قاضى التفليسة .
وتنتهى مهمة الأمين ويستلم المفلس أمواله ودفاتره وأوراقه منه بموجب إيصال ، ولا يكون الأمين مسئولا عن هذه الأشياء إذا لم يستلمها المفلس خلال سنة من تاريخ إقرار الحساب الختامى .
ويحرر قاضى التفليسة محضرا بجميع ما تقدم .$m251$,'0880c24d140a10caed665c2e0b4fc4bd',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(183,0,1,$m251$يبطل الصلح إذا صدر بعد التصديق عليه حكم بإدانة المفلس فى إحدى جرائم الإفلاس بالتدليس .
وكذلك يبطل الصلح إذا ظهر بعد التصديق عليه تدليس ناشئ عن إخفاء موجودات المفلس أو المبالغة فى ديونه ، وفى هذه الحالة يجب أن يكون طلب إبطال الصلح خلال ستة أشهر من اليوم الذى يظهر فيه التدليس وإلا كان الطلب غير مقبول ، وفى جميع الأحوال لا يكون طلب إبطال الصلح مقبولا إذا قدم بعد انقضاء سنتين من تاريخ التصديق على الصلح .
ويترتب على إبطال الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروطه .
وتختص المحكمة التى أصدرت حكم شهر الإفلاس بنظر دعوى إبطال الصلح .$m251$,'88ed8ad402f07c464120fcb8804fb504',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(184,0,1,$m251$إذا بدأ التحقيق مع المفلس فى جريمة الإفلاس بالتدليس بعد التصديق على الصلح أو إذا أقيمت عليه الدعوى الجنائية فى هذه الجريمة بعد التصديق على الصلح ، جاز للمحكمة التى أصدرت حكم شهر الإفلاس ، بناء على طلب النيابة العامة أو كل ذى مصلحة أن تأمر باتخاذ ما تراه من تدابير للمحافظة على أموال المدين ، وتلغى هذه التدابير بحكم القانون ، إذا تقرر حفظ التحقيق أو صدر قرار بأن لا وجه لإقامة الدعوى أو حكم ببراءة المفلس .$m251$,'55fe091b23ce72ae3fd2a3ff3d112c61',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(185,0,1,$m251$إذا لم يقم المفلس بتنفيذ شروط الصلح جاز طلب فسخه من المحكمة التى أصدرت حكم شهر الإفلاس .
ولا يترتب على فسخ الصلح براءة ذمة الكفيل الذى يضمن تنفيذ شروطه ، ويجب تكليف هذا الكفيل بحضور الجلسة التى نظر فيها طلب فسخ الصلح .$m251$,'eccaa0fcff04a9300f783aa820370bfe',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(186,0,1,$m251$التصرفات الحاصلة من المدين بعد التصديق على الصلح وقبل إبطاله أو فسخه تكون نافذة فى حق الدائنين ، ولا يجوز لهم طلب عدم نفاذها فى حقهم إلا طبقا للأحكام المنصوص عليها فى المادة (237) من القانون المدنى .
وتسقط دعوى عدم نفاذ التصرف المنصوص عليها فى الفقرة السابقة بمضى سنتين من تاريخ إبطال الصلح أو فسخه .$m251$,'2532f5104746a4845f715efc59be839c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(187,0,1,$m251$تعود إلى الدائنين بعد إبطال الصلح أو فسخه ديونهم كاملة وذلك بالنسبة إلى المفلس فقط .
ويشترك هؤلاء الدائنون فى جماعة الدائنين بديونهم الأصلية كاملة إذا لم يكونوا قد قبضوا شيئا من القدر الذى تقرر لهم فى الصلح وإلا وجب تخفيض ديونهم الأصلية بنسبة ما حصلوا عليه من القدر المذكور .
وتسرى الأحكام المذكورة فى الفقرتين السابقتين فى حالة شهر إفلاس المدين مرة أخرى قبل أن يصدر حكم بإبطال الصلح أو بفسخه .$m251$,'3030da41c783ac952f1e7e7b2a8a2b70',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(188,0,1,$m251$يجوز أن يعقد الصلح على أن يتخلى المدين عن أمواله كلها أو بعضها لبيعها وتوزيع ثمنها على الدائنين ، وتسرى على هذا الصلح أحكام الصلح القضائى ويظل المدين ممنوعا عن التصرف والإدارة فى الأموال التى تخلى عنها .
وتباع الأموال التى يتخلى عنها المدين ويوزع ثمنها طبقا للقواعد المقررة لبيع وتوزيع أموال المفلس فى حالة الاتحاد .
وإذا كان الثمن الناتج عن بيع الأموال التى تخلى عنها المدين يجاوز الديون المطلوبة منه وجب رد المقدار الزائد إليه .$m251$,'fff37b5423a284ca230b942e8c5bd56b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(189,0,1,$m251$يدعو قاضى التفليسة الدائنين إثر قيام حالة الاتحاد للمداولة فى شئون التفليسة والنظر فى إبقاء أمين التفليسة أو تغييره ، ويسمى فى هذه المرحلة أمين الاتحاد ، وللدائنين أصحاب التأمينات العينية المقررة على أموال المفلس الاشتراك فى هذه المداولات والتصويت دون أن يترتب على ذلك سقوط تأميناتهم .
وإذا قررت أغلبية الدائنين الحاضرين تغيير أمين التفليسة وجب على قاضى التفليسة تعيين غيره فورا ، فإن أجمع الدائنون على تسمية أمين ، بخلاف صاحب الدور ، يستجيب قاضى التفليسة لاختيارهم .
وعلى أمين التفليسة السابق أن يقدم إلى أمين الاتحاد فى الميعاد الذى يعينه قاضى التفليسة وبحضوره حسابا عن إدارته ويخطر المدين بميعاد تقديم الحساب .
ويجوز للمحكمة المختصة بناء على طلب قاضى التفليسة تغيير أمين اتحاد الدائنين إذا أخل بواجباته .$m251$,'078f5e51f31e7598f55b38cad25e0e46',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(190,0,1,$m251$يؤخذ رأى الدائنين خلال الاجتماع المنصوص عليه فى المادة (189) من هذا القانون فى أمر تقرير إعانة من أموال التفليسة للمفلس أو لمن يعولهم .
وإذا وافقت أغلبية الدائنين الحاضرين على تقرير الإعانة للمفلس أو لمن يعولهم وجب على قاضى التفليسة ، بعد أخذ رأى أمين الاتحاد ورأى المراقب ، تعيين مقدار الإعانة .
ويجوز لأمين الاتحاد وكذا المفلس أو من يعولهم ، الطعن أمام المحكمة فى قرار قاضى التفليسة بتعيين مقدار الإعانة ، وفى هذه الحالة يصرف نصف الإعانة لمن تقررت له إلى حين الفصل فى الطعن .$m251$,'a59c237f3945efe1c76e983537763945',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(191,0,1,$m251$لا يجوز لأمين الاتحاد الاستمرار فى خطة إعادة الهيكلة المنصوص عليها فى المادة (163) من هذا القانون إلا بعد الحصول على تفويض يصدر بأغلبية تمثل ثلثى الدائنين عددا ومبلغا ، ويجوز لهم تعديل خطة إعادة التشغيل بعد أخذ رأى لجنة إعادة الهيكلة وتصديق قاضى التفليسة .
وإذا نشأت عن تنفيذ خطة إعادة الهيكلة التزامات تزيد على أموال الاتحاد كان الدائنون الذين وافقوا على الاستمرار فى التجارة مسئولين فى أموالهم الخاصة ودون تضامن بينهم عن الزيادة بشرط أن تكون ناشئة عن أعمال تدخل فى حدود التفويض الصادر منهم ، وتكون مسئولية كل دائن بنسبة دينه .$m251$,'948758d66fc2a74642f46eb64593f126',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(192,0,1,$m251$تسرى على إفلاس الشركات الأحكام المذكورة فى هذا الفصل والقواعد التالية :$m251$,'dd6d6ef4fceda3ce926533573d0c5df9',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(193,0,1,$m251$تعد فى حالة إفلاس كل شركة توقفت عن دفع ديونها إثر اضطراب أعمالها المالية ، ويلزم شهر إفلاسها بحكم يصدر بذلك .
ويجوز شهر إفلاس الشركة ولو كانت فى دور التصفية .$m251$,'b47b778fc487eefed7d142db4b60f1ee',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(194,0,1,$m251$لا يجوز للممثل القانونى للشركة أن يطلب شهر إفلاسها إلا بعد الحصول على إذن بذلك من أغلبية الشركاء أو من الجمعية العامة حسب الأحوال .
ويجب أن يشتمل طلب شهر الإفلاس على أسماء الشركاء المتضامنين الحاليين والذين خرجوا من الشركة بعد توقفها عن الدفع مع بيان موطن كل شريك متضامن وجنسيته وتاريخ شهر خروجه من الشركة فى السجل التجارى .$m251$,'c30c08461d6b6d43ca3c353c49ebaefd',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(195,0,1,$m251$يجوز لدائن الشركة طلب شهر إفلاسها ولو كان شريكا فيها ، أما الشركاء غير الدائنين فلا يجوز لهم بصفتهم الفردية طلب شهر إفلاس الشركة .
وإذا طلب الدائن شهر إفلاس الشركة ، وجب اختصام كافة الشركاء المتضامنين .$m251$,'13ffaca6c865b6a66fbf5002ee40da70',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(196,0,1,$m251$يجوز للمحكمة من تلقاء ذاتها أو بناء على طلب الشركة أن تؤجل النظر فى شهر إفلاسها لمدة لا تجاوز ثلاثة أشهر إذا كان من المحتمل دعم مركزها المالى أو إذا اقتضت مصلحة الاقتصاد القومى ذلك ، وللمحكمة أن تأمر باتخاذ ما تراه من تدابير للمحافظة على موجودات الشركة .$m251$,'8416e7b3331e6c66d02ee4c3e047884f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(197,0,1,$m251$إذا شهر إفلاس الشركة وجب شهر إفلاس جميع الشركاء المتضامنين فيها ، ويشمل شهر الإفلاس الشريك المتضامن الذى خرج من الشركة بعد توقفها عن الدفع إذا طلب شهر إفلاس الشركة قبل انقضاء سنة من تاريخ شهر خروج الشريك فى السجل التجارى .
وتقضى المحكمة بحكم واحد بشهر إفلاس الشركة والشركاء المتضامنين ولو لم تكن مختصة بشهر إفلاس هؤلاء الشركاء .
وتعين المحكمة لتفليسة الشركة وتفليسات الشركاء المتضامنين قاضيا واحدا وأمينا واحدا أو أكثر ، ومع ذلك تكون كل تفليسة مستقلة عن غيرها من التفليسات من حيث موجوداتها وخصومها وإدارتها وتحقيق ديونها وكيفية انتهائها .$m251$,'2174ccd8d58e3b59f467c484f12eee69',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(198,0,1,$m251$للمحكمة من تلقاء ذاتها أو بناء على طلب قاضى التفليسة أن تقضى بإسقاط الحقوق المنصوص عليها فى المادة (111) من هذا القانون عن أعضاء مجلس إدارة الشركة أو مديريها الذين ارتكبوا أخطاء جسيمة أدت إلى اضطراب أعمال الشركة وتوقفها عن الدفع .
إذا طلب شهر إفلاس الشركة جاز للمحكمة أن تقضى أيضا بشهر إفلاس كل شخص قام تحت ستار هذه الشركة بأعمال تجارية لحسابه الخاص وتصرف فى أموال الشركة كما لو كانت أمواله الخاصة .
وإذا تبين أن موجودات الشركة لا تكفى لوفاء (20٪) على الأقل من ديونها ، جاز للمحكمة بناء على طلب قاضى التفليسة أن تقضى بإلزام أعضاء مجلس الإدارة أو المديرين كلهم أو بعضهم بالتضامن بينهم أو بغير تضامن بدفع ديون الشركة كلها أو بعضها إلا إذا أثبتوا أنهم بذلوا فى تدبير شئون الشركة عناية الرجل الحريص .$m251$,'0d13ae80c7511985a74fefb2ee2cf6ca',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(199,0,1,$m251$يقوم الممثل القانونى عن الشركة التى أشهر إفلاسها مقامها فى كل أمر يستلزم فيه القانون أخذ رأى المفلس أو حضوره وعليه الحضور أمام قاضى التفليسة أو أمينها متى طلب منه ذلك والإدلاء بما يطلب من معلومات أو إيضاحات .$m251$,'69868390c976c9246b10fdde26d3a459',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(200,0,1,$m251$يجوز لأمين التفليسة بعد استئذان قاضى التفليسة أن يطالب الشركاء أو المساهمين بدفع الباقى من حصصهم أو باقى قيمة أسهمهم فى رأس المال ولو لم يحل ميعاد استحقاقه ، ولقاضى التفليسة أن يأمر بقصر هذه المطالبة على القدر اللازم لوفاء ديون الشركة .$m251$,'97aebea639def0db60b064b778acfa4b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(201,0,1,$m251$لا تخضع سندات القرض أو صكوك التمويل التى أصدرتها الشركة لإجراءات تحقيق الديون ، وتقبل هذه السندات أو الصكوك بقيمتها الاسمية بعد استنزال ما تكون الشركة قد دفعته منها ، وإذا اشترط أداء مكافأة عند الوفاء بسند القرض وجب قبول السند بقيمته الاسمية مضافا إليها الجزء الذى استحق من المكافأة حتى صدور الحكم بشهر الإفلاس .$m251$,'7dd7d345401263a19258e53adbd12e40',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(202,0,1,$m251$توضع مقترحات الصلح بموافقة أغلبية الشركاء أو الجمعية العامة بحسب الأحوال .
ويتولى الممثل القانونى عن الشركة تقديم مقترحات الصلح إلى جماعة الدائنين .$m251$,'23ec27724fda7de2003b517359064615',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(203,0,1,$m251$إذا كان الصلح خاصا بشركة أصدرت سندات قرض أو صكوك تمويل تجاوز قيمتها ثلث مجموع ديونها ، فلا يجوز منحها الصلح إلا إذا وافقت على شروطه الجمعية العامة لجماعة مالكى هذه السندات أو الصكوك ، وتؤجل دعوة الدائنين إلى الاجتماع للمداولة فى الصلح إلى أن تصدر تلك الموافقة .$m251$,'826630389ebb64fce058fcb5806dfb5b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(204,0,1,$m251$إذا انتهت تفليسة الشركة بالاتحاد وتم الصلح مع واحد أو أكثر من الشركاء المتضامنين فلا يجوز تخصيص أموال الشركة للوفاء بشروط هذا الصلح أو لضمان تنفيذها ، ويبرأ الشريك الذى حصل على الصلح من التضامن .
وإذا تم الصلح مع الشركة وانتهت تفليسات الشركاء المتضامنين بالاتحاد ، استمرت الشركة قائمة إلا إذا كان موضوع الصلح هو التخلى عن جميع أموالها .
وإذا انتهت تفليسة الشركة وتفليسات الشركاء بالصلح ، اعتبر كل صلح مستقلا عن غيره ولا تسرى شروطه إلا على دائنى التفليسة الخاصة به .$m251$,'0611bbda285ff5c43c5c6182f9878a7b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(205,0,1,$m251$لا تحل الشركة بانتهاء تفليستها بالاتحاد ، ومع ذلك يجوز حل هذه الشركة إذا تبين أن ما بقى من موجوداتها بعد تصفية الاتحاد لا يكفى لمتابعة أعمالها على وجه مجد .$m251$,'946b043f307528b960ca1513261005cf',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(206,0,1,$m251$إذا انقضت ستة أشهر من تاريخ قيام حالة الاتحاد دون إنجاز التصفية ، وجب على أمين الاتحاد أن يقدم إلى قاضى التفليسة تقريرا عن حالة التصفية وأسباب التأخير فى إنجازها ، ويرسل القاضى هذا التقرير إلى الدائنين مع دعوتهم للاجتماع لمناقشته ، ويتكرر ذلك الإجراء كلما انقضت ستة أشهر دون أن ينجز أمين الاتحاد أعمال التصفية .$m251$,'271d98a59b14963bcacc4d10a94fe4b0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(207,0,1,$m251$يقدم أمين الاتحاد بعد الانتهاء من أعمال التصفية حسابا ختاميا إلى قاضى التفليسة ، ويرسل القاضى هذا الحساب إلى الدائنين مع دعوتهم للاجتماع لمناقشته ، ويخطر المفلس بهذا الاجتماع وله حضوره .
وينحل الاتحاد وتعتبر التفليسة منتهية بحكم القانون بعد المصادقة على الحساب المشار إليه فى الفقرة السابقة .
ويكون أمين الاتحاد مسئولا لمدة سنة من تاريخ انتهاء التفليسة عن الدفاتر والمستندات والأوراق المسلمة إليه .$m251$,'5ed79f6ad09a9f83b05b5ae26fca45dd',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(208,0,1,$m251$يعود إلى كل دائن بعد انتهاء حالة الاتحاد الحق فى التنفيذ على المدين للحصول على الباقى من دينه بناء على شهادة من قاضى التفليسة بالمتبقى من دينه ، ويعتبر قبول الدين فى التفليسة بمثابة حكم نهائى فيما يتعلق بهذا التنفيذ ، على أن يؤشر على سند الدين بما يفيد استلام الدائن للشهادة .$m251$,'ece81d988e13dbf0f4d0b55a58141d9d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(209,0,1,$m251$إذا تبين بعد جرد أموال المفلس أن قيمتها لا تزيد على خمسمائة ألف جنيه ، جاز لقاضى التفليسة من تلقاء نفسه أو بناء على طلب من أمين التفليسة أو أحد الدائنين أن يأمر بالسير فى إجراءات التفليسة وفقا للأحكام الآتية :
(أ) تخفض إلى النصف المواعيد المنصوص عليها فى الفقرة الأولى من المادة (165) والمادة (167) والفقرة الثانية من المادة (168) والفقرة الثانية من المادة (169) والمادة (170) والفقرة الثالثة من المادة (171) من هذا القانون .
(ب) تكون جميع قرارات قاضى التفليسة غير قابلة للطعن فيها ، ما لم ينص القانون على خلاف ذلك ، أو كان القرار مما يجاوز اختصاصه .
(ج) لا يعين مراقب للتفليسة .
(د) لا يغير أمين التفليسة عند قيام حالة الاتحاد .
(هـ) لا يجرى إلا توزيع واحد على الدائنين بعد الانتهاء من بيع أموال التفليسة .$m251$,'c3878b86b8bb17dcd7018b3bf5a158f8',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(210,0,1,$m251$مع عدم الإخلال بأحكام قيد الرهن الرسمى للعقارات والطائرات والسفن والرهن التجارى للمحال التجارية والضمانات المنقولة والتمويل العقارى والتأجير التمويلى والرهن الحيازى والملكية الفكرية المنصوص عليها فى القوانين المنظمة لها ، تسرى على بيع موجودات التفليسة الأحكام المنظمة فى هذا الباب .$m251$,'983cb2911df5e3855e0e739b79757053',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(211,0,1,$m251$لا يجوز بيع أموال التفليسة خلال فترة الإجراءات التمهيدية التى يجرى فيها وضع الأختام والنشر ورفع الأختام والجرد ، ومع ذلك يجوز لقاضى التفليسة بناء على طلب أمينها أن يأذن ببيع الأشياء القابلة لتلف سريع أو نقص عاجل فى القيمة ، أو التى تقتضى صيانتها مصاريف باهظة ، كما يجوز الإذن ببيع أموال التفليسة إذا كان البيع لازما للحصول على نقود للصرف على شئونها ، أو كان البيع يحقق نفعا مؤكدا للدائنين أو للمفلس ولا يجوز الإذن بالبيع فى الحالة الأخيرة إلا بعد إخطار المفلس بالبيع وسماع أقواله .$m251$,'4683070fc757fe23b9dba9d0b65fa019',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(212,0,1,$m251$يجوز الطعن أمام المحكمة فى القرار الصادر من قاضى التفليسة ببيع أموال المفلس أثناء فترة التمهيدية خلال عشرة أيام من تاريخ صدور قرار البدء فى اتخاذ إجراءات البيع .$m251$,'906ea4e1d6b155f1c3aa933539a393e2',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(213,0,1,$m251$يجب على الدائنين المرتهنين اتخاذ إجراءات بيع المنقولات أو العقارات التى يقع عليها رهنهم وفقا للطريقة المحددة بعقود الضمان واستيفاء حقوقهم المضمونة بهذه المنقولات أو العقارات ، وذلك خلال عام على الأكثر من تاريخ شهر الإفلاس ، على أن يتم ذلك البيع فى مواجهة أمين التفليسة ، وإلا كان لأمين التفليسة أو أمين الاتحاد بحسب الأحوال دون غيره بعد إخطار الدائن حق التنفيذ عليها وفقا للأحكام الواردة بهذا القانون .
وفى حالة بيع المنقولات أو العقارات المرهونة بناء على طلب الدائن المرتهن بثمن يجاوز الدين ، وجب على أمين التفليسة أو أمين اتحاد الدائنين قبض المقدار الزائد لحساب جماعة الدائنين وإيداعه حساب التفليسة .
ولأمين اتحاد الدائنين بيع المنقولات أو العقارات المرهونة بعد الحصول على موافقة الدائن المرتهن بالبيع قبل انقضاء المدة المنصوص عليها بالفقرة الأولى من هذه المادة .
وتسرى الأحكام الواردة فى هذه المادة على أصحاب حقوق الامتياز الخاصة ، والحاصلين على اختصاص على أموال المدين .$m251$,'c33ccb774fe43545d800b9f183c212d8',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(214,0,1,$m251$يجرى بيع موجودات التفليسة بإذن أو قرار من قاضى التفليسة بمباشرة إجراءات البيع بطريق المزايدة العلنية بناء على قائمة شروط البيع التى يودعها أمين التفليسة أو أمين اتحاد الدائنين - بحسب الأحوال - قلم كتاب المحكمة المختصة .$m251$,'75939e2063c7d0e5d88339bcf655caca',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(215,0,1,$m251$فى حالة كون عقار المفلس مسجلا ، يقوم أمين اتحاد الدائنين بإعلان القرار الصادر من قاضى التفليسة باتخاذ إجراءات البيع إلى مكتب الشهر العقارى أو إلى مكتب السجل العينى المختص للتأشير به بغير رسوم خلال مدة لا تجاوز أسبوعا من تاريخ إعلانهما على هامش سند ملكية المدين المفلس للعقار ، أو بصحيفة الوحدة العقارية مباشرة بحسب الأحوال ، وإعلان ذلك إلى جميع الدائنين المقيدة حقوقهم على العقار وإلى حائزه الفعلى .$m251$,'68c3de4f86b9d272069aaa08014c4108',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(216,0,1,$m251$يقوم التأشير بالقرار الصادر من قاضى التفليسة فى مكتب الشهر العقارى أو مكتب السجل العينى مقام تسجيل تنبيه نزع الملكية .$m251$,'1dd04f4c6f8941e57cfd5818451c87a9',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(217,0,1,$m251$يصدر قاضى التفليسة قرارا بتعيين خبير من خبراء التقييم المقيدة أسماؤهم بجدول خبراء إدارة الإفلاس وله عند الاقتضاء تعيين خبير آخر ، وذلك لتقييم المبيع وفقا للمعايير الآتية :
(أ) قيمة المبيع عند شرائه .
(ب) التعديلات التى طرأت على المبيع .
(ج) أثر معدلات التضخم على المبيع .
(د) القيمة السوقية وقت التقييم .
(هـ) القيمة الإيجارية للمبيع وقت التقييم .$m251$,'a1dabdddd46190d27ced6bc91db522ba',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(218,0,1,$m251$يضع أمين التفليسة أو أمين اتحاد الدائنين ، بحسب الأحوال ، قائمة شروط البيع بالمزاد العلنى ، ويقوم بإيداعها قلم كتاب المحكمة المختصة بعد اعتمادها من قاضى التفليسة خلال ثلاثين يوما من تاريخ صدور قرار قاضى التفليسة بمباشرة إجراءات البيع ، على أن تتضمن ما يأتى :
1 - تعيين الشىء المبيع مع تحديد البيانات التى تفيد فى بيان أوصافه ، وتحديد مساحته وموقعه وحدوده فى حالة بيع العقار .
2 - تاريخ إذن أو قرار قاضى التفليسة بمباشرة إجراءات البيع .
3 - تاريخ وساعة ومكان إجراءات البيع .
4 - شروط البيع والثمن الأساسى لبدء المزايدة وتحديد مقادير التدرج فى العروض .
5 - تجزئة المبيع إلى صفقات إذا كان لذلك محل ، مع ذكر الثمن الأساسى لكل صفقة .
6 - مقدار تأمين الاشتراك فى المزاد ، على ألا يقل عن واحد فى المائة ولا يجاوز خمسة فى المائة من الثمن الأساسى للمبيع وذلك نقدا أو بموجب شيك مقبول الدفع .
7 - قيمة إيجار القاعة التى ستتم فيها إجراءات البيع سواء بالمحكمة أو خارجها .
8 - تحديد النسبة المئوية التى يتحملها الراسى عليه المزاد والتى تحصل لحساب إجراءات التفليسة ، ليخصم منها النسبة المقررة لأمين التفليسة أو أمين اتحاد الدائنين - بحسب الأحوال - وخبراء التقييم وفقا لقرار قاضى التفليسة وبما لا يجاوز ثلاثة فى المائة من قيمة مبلغ رسو المزاد .
9 - إلزام الراسى عليه المزاد بسداد كافة الرسوم القضائية المقررة على بيع العقارات والمنقولات قبل استلام المبيع .
10 - تحديد تاريخ الجلسة المحددة للنظر فيما يحتمل تقديمه من الاعتراضات على القائمة أو الملاحظات عليها قبل الجلسة المحددة للبيع بأسبوعين على الأكثر .
وتتولى المحكمة المختصة وفقا للتعريف المنصوص عليه بالمادة (1) من هذا القانون نظر جميع الدعاوى التى تنشأ عن عقد البيع فى هذه الحالة .$m251$,'572643ccff904310126ce4c5b86edf61',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(219,0,1,$m251$يقوم أمين التفليسة أو أمين اتحاد الدائنين - بحسب الأحوال - بالنشر عن إيداع قائمة شروط البيع فى إحدى الصحف اليومية واسعة الانتشار أو بأية وسيلة أخرى يحددها قاضى التفليسة ، وفى حالة بيع عقار المفلس يتم لصق الإعلانات على العقار .$m251$,'ca7951ccb526a3e2869e8fa0011c16e7',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(220,0,1,$m251$يجوز لكل ذى مصلحة الاعتراض على قائمة شروط البيع وذلك بالتقرير به فى قلم كتاب المحكمة المختصة قبل الجلسة المحددة لنظر الاعتراضات بثلاثة أيام على الأقل ، وإلا سقط حقه فى التمسك بالاعتراض ، وتقضى المحكمة فى الاعتراض بموجب حكم لا يجوز الطعن عليه ، وذلك قبل الجلسة المحددة للبيع .$m251$,'4fe59c50287d15f879ef8f51c10f7c82',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(221,0,1,$m251$يتحمل أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال مصاريف إعادة إجراءات المزاد والبيع إذا كان ذلك راجعا إلى خطئه . ولا يجوز الطعن على قرار قاضى التفليسة الصادر فى هذا الشأن .$m251$,'5a93e6dc284a7fd36820256dee845037',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(222,0,1,$m251$يتولى أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال ، فى حضور قاضى التفليسة ، إجراء المزايدة فى اليوم المحدد للبيع . وتبدأ المزايدة بالنداء على الثمن الأساسى وتنتهى باعتماد قاضى التفليسة البيع على من تقدم بأكبر عرض ، ويعتبر العرض الذى لم يزايد عليه خلال ثلاث دقائق منهيا للمزايدة .$m251$,'8e2d8bdb58349ee9ef3c70cb94006f1e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(223,0,1,$m251$إذا كان العرض المقدم أقل من الثمن الأساسى أو لم يتقدم أحد الدائنين أو المتزايدين للمزاد ، جاز لقاضى التفليسة تأجيل المزاد إلى يوم آخر خلال الستين يوما التالية ، وله أن ينقص عشر الثمن الأساسى مرة بعد مرة كلما اقتضى الحال ذلك بما لا يجاوز مرتين ، يقوم بعدها قاضى التفليسة بإيقاف إجراءات البيع لحين تسويق المبيع بالكيفية التى يحددها وعرض الأمر على جماعة الدائنين . وعلى أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال الإعلان عن الجلسة المؤجل لها المزاد بالإجراءات المنصوص عليها بالمادة (219) من هذا القانون .$m251$,'d2ed5b82a456cb4cbfcf2d4287338a4d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(224,0,1,$m251$يجب على من يعتمد قاضى التفليسة عطاءه أن يودع ، حال انعقاد جلسة المزاد ، كامل الثمن الذى اعتمد والمصاريف ورسوم إجراء المزاد . ولقاضى التفليسة إعطاؤه مهلة لاستكمال السداد بعد استقطاع مبلغ التأمين بما لا يجاوز ثلاثة أشهر من تاريخ جلسة المزاد . فإذا لم يودع الراسى عليه المزاد الثمن كاملا خلال المدة المحددة ، يسقط حقه فى استرداد مبلغ التأمين ، وتعاد إجراءات المزاد بالشروط السابقة وفقا لآخر ثمن محدد .$m251$,'b058f0fa95af4cdc10e1611c247fa73b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(225,0,1,$m251$إذا كان المتزايد الراسى عليه المزاد دائنا وكان مقدار دينه ومرتبته يبرران إعفاءه من إيداع باقى الثمن ، أعفاه القاضى مع استنزال تلك القيمة من مقدار دينه المقبول عند إجراء التوزيعات .$m251$,'1ae834f69dc29e359c0ad77b828835e3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(226,0,1,$m251$يصدر قاضى التفليسة قرارا بتسليم المنقولات والعقارات غير المسجلة المبيعة للراسى عليه المزاد ، بعد سداد كامل الثمن وتقديمه ما يفيد سداد الرسوم المستحقة على المزاد . ويترتب على صدور القرار تطهير العقارات والمنقولات من كافة الديون والحقوق المترتبة عليها .$m251$,'b1905fa7b18cb85d25fb34b472608a5f',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(227,0,1,$m251$يصدر قاضى التفليسة حكما بإيقاع البيع فى حالة بيع العقارات المسجلة دون غيرها بناء على ما تم من إجراءات وبعد سداد كامل الثمن ، على أن يتضمن الحكم قائمة شروط البيع وما اتبع من إجراءات يوم البيع ، ويجب أن يتضمن منطوق الحكم الأمر بتسليم العقار لمن حكم بإيقاع البيع عليه ، وذلك بعد تقديمه ما يفيد سداد الرسوم القضائية المستحقة على المزاد .$m251$,'af14bda82cb2dfc971d7104ce6da211e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(228,0,1,$m251$لا يجوز الطعن فى حكم إيقاع البيع إلا لعيب فى إجراءات المزايدة أو فى شكل الحكم ، ويرفع الطعن بالإجراءات المعتادة خلال خمسة عشر يوما من تاريخ صدور الحكم .$m251$,'0234759eca82370a7bcea721741567a7',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(229,0,1,$m251$لمن حكم بإيقاع البيع عليه أن يشهر الحكم ما لم يطعن عليه ، على أن يتحمل مصاريف شهر الحكم ، ويترتب على هذا الشهر تطهير العقار من حقوق الامتياز والاختصاص والرهون الرسمية والحيازية وجميع الحقوق العينية التبعية . ويكون الحكم المشهر سندا بملكية من أوقع البيع عليه ، على ألا ينقل سوى ما كان للمدين المفلس من حقوق على العقار المبيع .$m251$,'b7df472101f4131dad2e056cd9f3ebf6',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(230,0,1,$m251$لا يعلن قرار تسليم المنقولات المبيعة والعقارات غير المسجلة أو حكم إيقاع البيع ويجرى تنفيذه جبرا بمعرفة أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال ، بأن يكلف المدين أو الحائز أو الكفيل العينى أو الحارس بحسب الأحوال بالحضور فى مكان التسليم فى اليوم والساعة المحددين لإجرائه ، على أن يتم ذلك التكليف قبل اليوم المعين للتسليم بأسبوع على الأقل . وإذا كان فى العقار منقولات تعلق بها حق لغير المدين المفلس ، وجب على أمين اتحاد الدائنين أن يطلب من قاضى التفليسة اتخاذ التدابير اللازمة للمحافظة على حقوق أصحاب الشأن .$m251$,'dc254354d33b62c9eb779272e4ead506',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(231,0,1,$m251$لا يترتب على رفع دعوى الاستحقاق ودعوى الاسترداد وقف إجراءات التنفيذ على العقار أو المنقول بحسب الأحوال ما لم تقض المحكمة المختصة بغير ذلك .$m251$,'05044433574be742d5e43a61d761bc27',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(232,0,1,$m251$فى حالة وجود عقار للمدين المفلس بموجب عقد أو قرار تخصيص يتم اتخاذ إجراءات البيع أو التنازل عن حق التخصيص وفقا لأحكام وإجراءات بيع المنقولات والعقارات غير المسجلة الواردة فى هذا الباب . ويخطر أمين الاتحاد الجهة المانحة بقرار قاضى التفليسة بمباشرة إجراءات البيع للوقوف على الشروط الخاصة بالتنازل عن حق التخصيص وإدراجها بقائمة شروط البيع ، وعلى أمين اتحاد الدائنين اتخاذ إجراءات نقل التخصيص للراسى عليه المزاد بالجهة المانحة .$m251$,'e681db6ea661edaed579dc5891914688',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(233,0,1,$m251$فى حالة بيع العقار المملوك على الشيوع لعدم إمكان القسمة بغير ضرر يجرى بيعه بذات الطرق الواردة بهذا الباب ، على أن تشتمل قائمة شروط البيع فضلا عن البيانات المذكورة فى المادة (218) من هذا القانون على بيان جميع الشركاء وموطن كل منهم . ويعلن أمين اتحاد الدائنين جميع الشركاء بإيداع قائمة شروط البيع ، ويكون لهم إبداء ما لديهم من اعتراضات وملاحظات على شروط البيع بطريق الاعتراض على القائمة .$m251$,'7b90429834dc87a116e79ce9384f3fd4',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(234,0,1,$m251$يودع أمين التفليسة أو أمين اتحاد الدائنين بحسب الأحوال المبالغ الناتجة عن بيع أموال المفلس خزينة المحكمة أو بنكا يعينه قاضى التفليسة وذلك فى يوم العمل التالى للتحصيل على الأكثر ، ويلزم بتعويض يقدره قاضى التفليسة إذا تأخر فى الإيداع ، وعليه أن يقدم إلى قاضى التفليسة بيانا بالمبالغ المذكورة خلال أسبوع من تاريخ الإيداع . ولا يجوز سحب تلك المبالغ أو غيرها مما يــودعه الغير حساب التفليسة إلا بأمر من قاضى التفليسة .$m251$,'8f70884575eef8522b38d68466f4cc7a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(235,0,1,$m251$تستنزل من المبالغ الناتجة عن بيع أموال المفلس الرسوم ومصاريف إدارة التفليسة والديون المستحقة على التفليسة والإعانات المقررة للمفلس ولمن يعولهم ، والمبالغ المستحقة للدائنين الممتازين ، ويوزع الباقى بين الدائنين بنسبة ديونهم المحققة قسمة غرماء .
وتجنب حصة الديون المتنازع فيها والديون التى قبلت مؤقتا وتحفظ حتى يتم الفصل فيها .$m251$,'6c0efe7f8e26dd13efb5720c4c02ed3b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(236,0,1,$m251$يجوز لقاضى التفليسة فى أية مرحلة كانت عليها التفليسة أن يأمر بإجراء توزيعات على الدائنين الذين حققت ديونهم ويعين مقدار المبلغ الذى يوزع . ويكون التوزيع بمقتضى قائمة يعدها أمين التفليسة أو أمين اتحاد الدائنين حسب الأحوال وتعتمد من قاضى التفليسة بإجراء التوزيع ، وله عند الاقتضاء أن يأمر بنشر قرار التوزيع فى صحيفة يومية .
ويجوز للمفلس ولكل ذى مصلحة الطعن أمام المحكمة المختصة فى قرار قاضى التفليسة الخاص بإجراء توزيعات على الدائنين ، وذلك خلال عشرة أيام تبدأ من تاريخ إيداع القائمة قلم الكتاب .$m251$,'e2eac0704f6c6b9ce0aa49b96711352b',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(237,0,1,$m251$يؤشر أمين اتحاد الدائنين على سند الدين بالمبالغ المدفوعة . وفى جميع الأحوال ، يجب أن يعطى الدائن مخالصة على قائمة التوزيع .$m251$,'bc6656727ec8afd19a0c02fbd6fd9911',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(238,0,1,$m251$إذا حصل توزيع ثمن العقارات أو المنقولات ، كان للدائنين المرتهنين أو الممتازين أو الحاصلين على اختصاص الذين لم يستوفوا حقوقهم كلها أو بعضها من ثمن العقارات والمنقولات المحملة بالتأمين أن يشتركوا فى قسمة الغرماء بالباقى لهم مع الدائنين العاديين فى توزيع الأموال التى يتعلق بها حق جماعة الدائنين بشرط أن تكون ديونهم قد حققت طبقا لأحكام هذا القانون . وإذا تبين عند التسوية النهائية أن ما حصل عليه أحدهم يزيد على مقدار دينه ، وجب استنزال الجزء الزائد ورده إلى جماعة الدائنين .$m251$,'53c582b2262a338f27db0863f4b1cc45',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(239,0,1,$m251$فيما عدا حالة الإفلاس بالتدليس ، تعود بحكم القانون جميع الحقوق التى سقطت عن المفلس طبقا للمادة (111) من هذا القانون بعد انقضاء ثلاث سنوات من تاريخ انتهاء التفليسة .$m251$,'9ed50698bdc4126b04aef49a0ed5443a',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(240,0,1,$m251$يجب الحكم برد الاعتبار إلى المفلس ولو لم ينقض الميعاد المنصوص عليه فى المادة (239) من هذا القانون ، إذا أوفى جميع ديونه من أصل ومصاريف وعوائد مدة لا تزيد على سنتين .
وإذا كان المفلس شريكا متضامنا فى شركة حكم بشهر إفلاسها فلا يرد إليه اعتباره وجوبا إلا إذا أوفى جميع ديون الشركة من أصل ومصاريف وعوائد مدة لا تزيد على سنتين .$m251$,'8e7705d5b2b30c1815d6934fe8c4dfb0',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(241,0,1,$m251$يجوز الحكم برد الاعتبار إلى المفلس ولو لم ينقض الميعاد المنصوص عليه فى المادة (239) من هذا القانون فى الحالتين الآتيتين :
(أ) إذا حصل المفلس على صلح من دائنيه ونفذ شروطه ، ويسرى هذا الحكم على الشريك المتضامن فى شركة حكم بشهر إفلاسها إذا حصل هذا الشريك على صلح خاص به ونفذ شروطه .
(ب) إذا أثبت المفلس أن الدائنين قد أبرءوا ذمته من جميع الديون أو أنهم أجمعوا على الموافقة على رد اعتباره .$m251$,'d11f69c323271c5e70bfb4463ebbdaec',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(242,0,1,$m251$إذا امتنع أحد الدائنين عن قبض دينه أو كان غائبا أو تعذر معرفة موطنه جاز ، إيداع الدين خزانة المحكمة . وتقوم شهادة الإيداع فيما يتعلق برد الاعتبار مقام التخالص .$m251$,'f71d35392658db3317c6fa19252a9638',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(243,0,1,$m251$لا يرد الاعتبار إلى المفلس الذى صدر عليه حكم بالإدانة فى إحدى جرائم الإفلاس بالتقصير إلا بعد تنفيذ العقوبة المحكوم بها أو صدور عفو عنها أو انقضائها بمضى المدة .
ولا يرد الاعتبار إلى المفلس الذى صدر عليه حكم بالإدانة فى إحدى جرائم الإفلاس بالتدليس إلا بعد انقضاء مدة ست سنوات من تاريخ تنفيذ العقوبة المحكوم بها أو صدور عفو عنه .
وفى جميع الأحوال ، لا يجوز رد الاعتبار إلى المفلس إلا إذا كان قد أوفى جميع الديون المطلوبة منه من أصل ومصاريف وعوائد مدة لا تزيد على سنتين ، أو أجرى تسوية بشأنها مع الدائنين .$m251$,'41c50b956181781b1d7a5b0fbbb06f7c',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(244,0,1,$m251$يرد الاعتبار إلى المفلس بعد وفاته بناء على طلب أحد الورثة ، وذلك طبقا للأحكام المنصوص عليها فى المواد السابقة .$m251$,'0fd4544b7acbf9ec3f4fa02bd494354e',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(245,0,1,$m251$يقدم طلب رد الاعتبار مرفقا به المستندات المؤيدة له إلى قلم كتاب محكمة الإفلاس المختصة .
ويرسل قلم الكتاب فورا صورة من الطلب إلى النيابة العامة .
وينشر ملخص الطلب فى إحدى الصحف اليومية التى تصدر أو توزع فى دائرة المحكمة على نفقة المدين . ويجب أن يشتمل هذا الملخص على اسم المدين وتاريخ صدور حكم شهر الإفلاس وكيفية انتهاء التفليسة والتنبيه على الدائنين بتقديم اعتراضاتهم إن كان لها مقتض .$m251$,'801bb6cbbed80ff6fede740bfdc38330',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(246,0,1,$m251$تودع النيابة العامة قلم كتاب المحكمة ، خلال ثلاثين يوما من تاريخ تسلمها صورة طلب رد الاعتبار ، تقريرا يشتمل على بيانات عن نوع الإفلاس والأحكام التى صدرت على المفلس فى جرائم الإفلاس أو المحاكمات أو التحقيقات الجارية معه فى هذا الشأن .$m251$,'ec19ca88e424b6b8336e3e789acd7088',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(247,0,1,$m251$لكل دائن لم يستوف حقه أن يقدم اعتراضا على طلب رد الاعتبار خلال خمسة عشر يوما من تاريخ نشر الطلب فى الصحف . ويكون الاعتراض بتقرير كتابى يقدم إلى قلم كتاب المحكمة مرفقا به المستندات المؤيدة له .$m251$,'cae06540b6b6e25cb9bf5a65ccc79dba',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(248,0,1,$m251$يقوم قلم كتاب المحكمة بعد انقضاء الميعاد المنصوص عليه فى المادة (247) من هذا القانون بإخطار الدائنين الذين قدموا معارضات فى طلب رد الاعتبار بتاريخ الجلسة المحددة لنظر الطلب .$m251$,'888dd1eead9345968f0aaa7b43bdaeb8',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(249,0,1,$m251$تفصل المحكمة فى طلب رد الاعتبار بحكم انتهائى . وإذا قضت المحكمة برفض الطلب ، فلا يجوز تقديمه من جديد إلا بعد انقضاء سنة من تاريخ صدور الحكم .$m251$,'3d0611d3793cbdb42405fae359c0c643',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(250,0,1,$m251$إذا أجريت قبل الفصل فى طلب رد الاعتبار تحقيقات مع المفلس بشأن إحدى جرائم الإفلاس أو أقيمت عليه الدعوى الجنائية بذلك ، وجب على النيابة العامة إخطار المحكمة فورا . وعلى المحكمة أن توقف الفصل فى طلب رد الاعتبار حتى انتهاء التحقيقات أو صدور الحكم النهائى فى الدعوى الجنائية .$m251$,'442649beb950e266225375744d676ddd',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(251,0,1,$m251$إذا صدر على المدين حكم بالإدانة فى إحدى جرائم الإفلاس بعد صدور الحكم برد الاعتبار ، اعتبر هذا الحكم كأن لم يكن . ولا يجوز للمدين الحصول بعد ذلك على رد الاعتبار إلا بالشروط المنصوص عليها فى المادة (243) من هذا القانون .$m251$,'e2fa94d4b9b80f0cdbb9355b46d9f877',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(252,0,1,$m251$يعد متفالسا بالتدليس كل تاجر توقف عن دفع ديونه فى الأحوال الآتية :
1 - إذا أخفى دفاتره أو أعدمها أو غيرها .
2 - إذا اختلس أو خبأ جزءا من ماله إضرارا بدائنيه .
3 - إذا اعترف أو جعل نفسه مدينا بطريق التدليس بمبالغ ليست فى ذمته حقيقة ، سواء كان ذلك ناشئا عن مكتوباته أو ميزانيته أو غيرهما من الأوراق أو عن إقراره الشفاهى أو عن امتناعه من تقديم أوراق أو إيضاحات مع علمه بما يترتب على ذلك الامتناع .$m251$,'95bac2fb35afc597f6b4e4e3e9cd98e9',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(253,0,1,$m251$يعاقب المتفالس بالتدليس ومن شاركه فى ذلك بالسجن من ثلاث إلى خمس سنوات وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز خمسمائة ألف جنيه .$m251$,'8be11488e60ce3fc442dfdc2280697a1',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(254,0,1,$m251$يعد متفالسا بالتقصير على وجه العموم كل تاجر أدى لخسارة دائنيه بسبب عدم حزمه أو تقصيره الجسيم ، وعلى الخصوص التاجر الذى يكون فى إحدى الأحوال الآتية :
1 - إذا رئى أن مصاريفه الشخصية أو مصاريف منزله باهظة .
2 - إذا حصل على الصلح بطريق التدليس .
3 - إذا استهلك مبالغ كبيرة فى القمار أو أعمال اليانصيب المحض أو فى أى أعمال وهمية .
4 - إذا اشترى بضائع ليبيعها بأقل من أسعارها حتى يؤخر إشهار إفلاسه ، أو اقترض مبالغ أو أصدر أوراقا مالية أو استعمل طرقا أخرى مما يؤدى لخسائر شديدة لحصوله على النقود حتى يؤخر إشهار إفلاسه .
5 - عدم تحريره الدفاتر الملزم قانونا بإمساكها أو عدم إجرائه الجرد المنصوص عليه فى القانون أو إذا كانت دفاتره غير كاملة أو غير منتظمة بحيث لا يعرف منها مركزه المالى .
6 - عدم إعلانه التوقف عن الدفع فى الميعاد أو عدم تقديمه الميزانية أو ثبوت عدم صحة البيانات الواجب تقديمها بمقتضى هذا القانون .
7 - عدم توجهه بشخصه إلى قاضى التفليسة عند عدم وجود الأعذار الشرعية أو عدم تقديمه البيانات التى يطلبها القاضى المذكور أو ظهور عدم صحة تلك البيانات .
8 - تأديته عمدا بعد توقفه عن الدفع مديونية أحد دائنيه أو تمييزه إضرارا بباقى الدائنين أو إذا سمح له بمزية خصوصية بقصد الحصول على قبوله الصلح .
9 - إذا حكم بإفلاسه قبل أن يقوم بالتعهدات المترتبة على صلح سابق .$m251$,'f588d8e2c2a6e285a6784f67fa270a26',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(255,0,1,$m251$إذا أفلست شركة مساهمة أو شركة حصص ، يحكم على أعضاء مجلس إدارتها ومديريها بالعقوبات المقررة للتفالس بالتدليس إذا ثبت أنهم ارتكبوا أمرا من الأمور المنصوص عليها فى المادة (252) من هذا القانون أو إذا فعلوا ما يترتب عليه إفلاس الشركة بطريق الغش أو التدليس ، وعلى الخصوص إذا ساعدوا على توقف الشركة عن الدفع سواء بإعلانهم ما يخالف الحقيقة عن رأس المال المكتتب أو المدفوع أو بتوزيعهم أرباحا وهمية أو بأخذهم لأنفسهم بطريق الغش ما يزيد عن المرخص لهم به فى عقد الشركة .$m251$,'f2fe8215ad61163a289334f544126d01',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(256,0,1,$m251$إذا أفلست شركة مساهمة أو شركة حصص يحكم على أعضاء مجلس إدارتها ومديريها بالعقوبة المقررة للتفالس بالتقصير فى الحالات الآتية :
1 - إذا ثبت أنهم ارتكبوا أمرا من الأمور المنصوص عليها فى البنود من الثالث إلى التاسع من المادة (254) من هذا القانون .
2 - إذا أهملوا بطريق الغش فى نشر عقد الشركة بالكيفية التى نص عليها القانون .
3 - إذا اشتركوا فى أعمال مغايرة لما هو منصوص عليه فى النظام الأساسى للشركة .$m251$,'e38172a6bfd22877c18fb4c90e7c5b16',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(257,0,1,$m251$يعاقب المتفالس بالتقصير بغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مائتى ألف جنيه .$m251$,'25eacfa8630a5e034ec71e8a75659e91',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(258,0,1,$m251$فيما عدا أحوال الاشتراك المبينة قانونا ، يعاقب بالحبس وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز خمسمائة ألف جنيه أو بإحدى هاتين العقوبتين فى الحالات الآتية :
1 - كل شخص سرق أو أخفى أو خبأ كل أو بعض أموال المفلس من المنقولات أو العقارات ولو كان ذلك الشخص زوج المفلس أو من فروعه أو من أصوله أو أنسبائه الذين فى درجة الفروع والأصول .
2 - من لا يكونون من الدائنين ويشتركون فى مداولات الصلح بطريق الغش أو يقدمون ويثبتون بطريق الغش فى تفليسة سندات ديون صورية باسمهم أو باسم غيرهم .
3 - الدائنون الذين يزيدون قيمة ديونهم بطريق الغش أو يشترطون لأنفسهم مع المفلس أو غيره مزايا خصوصية فى نظير إعطاء صوتهم فى مداولات الصلح أو التفليسة أو الوعد بإعطائه أو يعقدون مشارطة خصوصية لنفعهم وإضرارا بباقى الدائنين .
4 - أمناء التفليسة الذين يختلسون شيئا أثناء تأدية عملهم .
ويحكم القاضى أيضا ومن تلقاء نفسه فيما يجب رده إلى جماعة الدائنين وفى التعويضات التى تطلب باسمهم إذا اقتضى الحال ذلك ولو فى حالة الحكم بالبراءة .$m251$,'83066c0c27c402de4e7fd00baa19fa04',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(259,0,1,$m251$تسرى فى شأن جرائم الصلح الواقى من الإفلاس الأحكام الآتية :
1 - يعاقب المدين بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على خمسمائة ألف جنيه أو بإحدى هاتين العقوبتين إذا :
(أ) أخفى بسوء نية كل أمواله أو بعضها أو غالى فى تقديرها بقصد الحصول على الصلح .
(ب) ترك بسوء نية دائنا بدين وهمى أو ممنوعا أو مغالى فى دينه يشترك فى مداولات الصلح والتصويت عليها أو مكنه من ذلك .
(ج) أغفل بسوء نية ذكر دائن فى قائمة الدائنين .
2 - يعاقب الدائن بالعقوبة المنصوص عليها بالفقرة السابقة إذا اشترك بسوء نية فى مداولات الصلح والتصويت عليه وهو ممنوع من هذا الاشتراك ، أو كان دينه مغالى فيه ، أو قرر له المدين أو أى شخص آخر مزايا خاصة مقابل تصويته مع الصلح .
3 - يعاقب أمين الصلح بذات العقوبة إذا قدم أو أقر بسوء نية ببيانات غير صحيحة عن حالة المدين .$m251$,'522af5722952f7fd3291c283d64ba0b3',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(260,0,1,$m251$لا يترتب على إقامة الدعوى الجنائية بالإفلاس بالتدليس أو بالتقصير أى تعديل فى الأحكام الخاصة بإجراءات التفليسة إلا إذا نص القانون على غير ذلك .$m251$,'3c007108cf5724009e2a8e0e9eed3a6d',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(261,0,1,$m251$فى حالة إقامة الدعوى الجنائية على المفلس ، يجب على أمين التفليسة أن يقدم للنيابة العامة أو للمحكمة ، كل ما تطلبه من وثائق أو مستندات أو معلومات أو إيضاحات تتعلق بالتفليسة .
وتبقى الوثائق والمستندات المذكورة أثناء التحقيق أو المحاكمة لدى النيابة العامة أو المحكمة وترد بعد انتهاء التحقيق أو المحاكمة إلى أمين التفليسة أو إلى المدين أو ورثته على حسب الأحوال .$m251$,'267961c0d600813284563402d422c3d1',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$),
(262,0,1,$m251$إذا كانت الجريمة تتعلق باتفاق عقده المدين أو أى شخص مع أحد الدائنين لمنح هذا الدائن مزايا خاصة مقابل التصويت على الصلح ، جاز للمحكمة الجنائية أن تقضى من تلقاء ذاتها بإبطال هذا الاتفاق وبالإلزام الدائن برد ما استولى عليه بمقتضاه ولو صدر الحكم فى الجريمة بالبراءة . وللمحكمة أن تقضى أيضا بناء على طلب ذوى الشأن بالتعويض عند الاقتضاء .$m251$,'4e652a8be097dd0767ef528ed9b07fc9',DATE '2018-03-21',NULL,'active',NULL,NULL,$m251$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 7 مكرر (د) فى 19 فبراير 2018 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة (وقد عُدّل بعد ذلك حسب علمنا)، فلا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m251$);

DO $m251$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m251_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m251_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[251] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m251_art) <> 269 OR (SELECT sum(char_length(body)) FROM m251_art) <> 98688 OR (SELECT count(*) FROM m251_ver) <> 269 THEN
    RAISE EXCEPTION '[251] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=11 AND law_year=2018 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الإفلاس%' THEN
    RAISE EXCEPTION '[251] يوجد مستند آخر برقم 11 لسنة 2018 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (11, 2018, $t251$القانون رقم 11 لسنة 2018 بإصدار قانون تنظيم إعادة الهيكلة والصلح الواقى والإفلاس (النص الأصلى كما نشر بالجريدة الرسمية)$t251$, $t251$قانون إعادة الهيكلة والصلح الواقى والإفلاس 11/2018$t251$, 'other', 'in_force', NULL, DATE '2018-02-19', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m251_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m251_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m251_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 269 THEN
    RAISE EXCEPTION '[251] عدد صفوف النص % بدل 269', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 269 THEN
    RAISE EXCEPTION '[251] عدد نسخ النص % بدل 269', v_vcnt;
  END IF;
  RAISE NOTICE '[251] قانون 11/2018: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m251$;
